struct ScopedBox64GuestEntryActive {
    explicit ScopedBox64GuestEntryActive(const char* phase_) : phase(phase_) {
        const int depth = g_box64_guest_entry_depth.fetch_add(1, std::memory_order_acq_rel) + 1;
        g_box64_guest_entry_active.store(true, std::memory_order_release);
#ifdef __ANDROID__
        executor_lsx4_reinstall_bus_handler();
#endif
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_GUEST_ACTIVE] phase=%s event=enter depth=%d",
                  phase ? phase : "?", depth);
    }

    ~ScopedBox64GuestEntryActive() {
        const int previous = g_box64_guest_entry_depth.fetch_sub(1, std::memory_order_acq_rel);
        const int depth = previous - 1;
        if (previous <= 1) {
            g_box64_guest_entry_depth.store(0, std::memory_order_release);
            g_box64_guest_entry_active.store(false, std::memory_order_release);
        }
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_GUEST_ACTIVE] phase=%s event=leave depth=%d",
                  phase ? phase : "?", depth < 0 ? 0 : depth);
    }

    ScopedBox64GuestEntryActive(const ScopedBox64GuestEntryActive&) = delete;
    ScopedBox64GuestEntryActive& operator=(const ScopedBox64GuestEntryActive&) = delete;

private:
    const char* phase;
};

