extern "C" bool executor_lsx4_android_should_suppress_guest_thread(void* start_routine,
                                                                       void* arg,
                                                                       const char* name) {
    (void)arg;
    const bool mapped_backend_active =
        RuntimeGuestJitActive() || RuntimeGuestFexActive() ||
        g_box64_guest_entry_active.load(std::memory_order_acquire);
    if (!mapped_backend_active || start_routine == nullptr) {
        return false;
    }
    const auto start_address = reinterpret_cast<std::uint64_t>(start_routine);
    const bool is_guest_entry = IsGuestExecutableAddress(start_address);
    if (!is_guest_entry) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_HOST_THREAD_ROUTE] native start=%p name=%s jit=%d fex=%d; "
                  "bypassing guest x86 dispatcher",
                  start_routine, name ? name : "<unnamed>",
                  RuntimeGuestJitActive() ? 1 : 0,
                  RuntimeGuestFexActive() ? 1 : 0);
    }
    return is_guest_entry;
}

extern "C" void executor_lsx4_android_note_suppressed_guest_thread(void* thread,
                                                                       void* start_routine,
                                                                       void* arg,
                                                                       const char* name) {
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_GUEST_THREAD] suppressed guest pthread=%p start=%p arg=%p name=%s",
              thread, start_routine, arg, name ? name : "<unnamed>");
}

extern "C" bool executor_lsx4_android_should_suppress_guest_once(void* once_control,
                                                                      void* init_routine) {
    (void)once_control;
    (void)init_routine;




    if (RuntimeGuestJitActive() || RuntimeGuestFexActive()) {
        return false;
    }
    return g_box64_guest_entry_active.load(std::memory_order_acquire) &&
           g_box64_run_mapped_function == nullptr;
}

extern "C" void executor_lsx4_android_note_suppressed_guest_once(void* once_control,
                                                                     void* init_routine) {
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_GUEST_ONCE] suppressed guest pthread_once=%p init=%p",
              once_control, init_routine);
}

extern "C" bool executor_lsx4_android_should_auto_allocate_pthread_key(int key) {
    return g_box64_guest_entry_active.load(std::memory_order_acquire) && key >= 0 && key < 256;
}

extern "C" void executor_lsx4_android_note_auto_allocated_pthread_key(int key) {
    static std::atomic_int log_budget{32};
    if (log_budget.fetch_sub(1, std::memory_order_relaxed) > 0) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_GUEST_TLS] auto-allocated pthread key=%d for active guest",
                  key);
    }
}

std::string JsonEscape(const std::string& value) {
    std::string escaped;
    escaped.reserve(value.size() + value.size() / 8);
    constexpr char hex[] = "0123456789abcdef";
    for (const unsigned char byte : value) {
        if (byte >= 0x20 && byte != '"' && byte != '\\') {
            escaped.push_back(static_cast<char>(byte));
            continue;
        }
        if (byte == '"' || byte == '\\') {
            escaped.push_back('\\');
            escaped.push_back(static_cast<char>(byte));
            continue;
        }
        escaped.append("\\u00");
        escaped.push_back(hex[byte >> 4]);
        escaped.push_back(hex[byte & 0x0f]);
    }
    return escaped;
}

std::filesystem::path FirmwareModulesRoot() {
    if (g_root.empty()) {
        return {};
    }
    return std::filesystem::path(g_root) / "sys_modules";
}

void AppendJsonStringArray(std::ostringstream& out, const std::vector<std::string>& values) {
    out << '[';
    for (std::size_t i = 0; i < values.size(); ++i) {
        if (i > 0) {
            out << ',';
        }
        out << '"' << JsonEscape(values[i]) << '"';
    }
    out << ']';
}

std::string BuildFirmwareSupportStatusJson() {
    if (g_root.empty()) {
        return R"({"enabled":false,"reason":"runtime not initialized"})";
    }

    try {
        const auto root = FirmwareModulesRoot();
        const bool root_exists = std::filesystem::exists(root);
        std::vector<std::string> present;
        std::vector<std::string> missing;
        present.reserve(ExecutorSupportedFirmwareModules.size());
        missing.reserve(ExecutorSupportedFirmwareModules.size());

        for (const char* module : ExecutorSupportedFirmwareModules) {
            const auto module_path = root / module;
            if (root_exists && std::filesystem::exists(module_path)) {
                present.emplace_back(module);
            } else {
                missing.emplace_back(module);
            }
        }

        int game_specific_dir_count = 0;
        if (root_exists) {
            for (const auto& entry : std::filesystem::directory_iterator(root)) {
                std::error_code ec;
                if (entry.is_directory(ec)) {
                    ++game_specific_dir_count;
                }
            }
        }

        std::ostringstream out;
        const auto game_specific_pattern = (root / "<TITLE_ID>" / "<module>.sprx").string();

        out << R"({"enabled":true,)"
            << R"("policy":"hle-first-user-provided-legal-dumps-only",)"
            << R"("sysModulesPath":")" << JsonEscape(root.string()) << R"(",)"
            << R"("gameSpecificPathPattern":")" << JsonEscape(game_specific_pattern) << R"(",)"
            << R"("supportedCount":)" << ExecutorSupportedFirmwareModules.size() << ','
            << R"("presentCount":)" << present.size() << ','
            << R"("missingCount":)" << missing.size() << ','
            << R"("present":)";
        AppendJsonStringArray(out, present);
        out << R"(,"missing":)";
        AppendJsonStringArray(out, missing);
        out << R"(,"gameSpecificDirCount":)" << game_specific_dir_count << ','
            << R"("legalNotice":"firmware modules are not bundled; import user-owned PS4 dumps",)"
            << R"("nextStep":"import legal dumps into app sandbox or use upstream HLE fallback"})";
        return out.str();
    } catch (const std::exception& e) {
        return std::string(R"({"enabled":false,"reason":"status probe failed","error":")") +
               JsonEscape(e.what()) + R"("})";
    } catch (...) {
        return R"({"enabled":false,"reason":"status probe failed","error":"unknown"})";
    }
}

void ConfigureFirmwareSupportLocked() {
    if (g_root.empty()) {
        g_firmware_status = R"({"enabled":false,"reason":"runtime not initialized"})";
        return;
    }

    try {
        const auto root = FirmwareModulesRoot();
        std::filesystem::create_directories(root);
        Config::setSysModulesPath(root);
        g_firmware_status = BuildFirmwareSupportStatusJson();
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_FIRMWARE] sys_modules=%s",
                  root.string().c_str());
    } catch (const std::exception& e) {
        g_firmware_status =
            std::string(R"({"enabled":false,"reason":"sys_modules staging failed","error":")") +
            JsonEscape(e.what()) + R"("})";
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_FIRMWARE] staging failed: %s", e.what());
    } catch (...) {
        g_firmware_status =
            R"({"enabled":false,"reason":"sys_modules staging failed","error":"unknown"})";
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_FIRMWARE] staging failed: unknown");
    }
}

std::string Hex64(const std::uint64_t value) {
    std::ostringstream out;
    out << "0x" << std::hex << value;
    return out.str();
}

std::string LocalBytesHex(const std::uint8_t* data, const std::size_t size) {
    if (data == nullptr || size == 0) {
        return "";
    }
    std::ostringstream out;
    static constexpr char Hex[] = "0123456789abcdef";
    for (std::size_t i = 0; i < size; ++i) {
        if (i != 0) {
            out << ' ';
        }
        const std::uint8_t byte = data[i];
        out << Hex[(byte >> 4) & 0xf] << Hex[byte & 0xf];
    }
    return out.str();
}

std::string ProtString(const std::int32_t prot) {
    std::string out;
    out += (prot & PF_READ) ? 'r' : '-';
    out += (prot & PF_WRITE) ? 'w' : '-';
    out += (prot & PF_EXEC) ? 'x' : '-';
    return out;
}

bool GuestAddressInsideModule(const Core::Module& module, const std::uint64_t address) {
    const auto info = module.GetModuleInfo();
    for (std::uint32_t i = 0; i < info.num_segments; ++i) {
        const auto& segment = info.segments[i];
        const std::uint64_t begin = segment.address;
        const std::uint64_t end = begin + segment.size;
        if (address >= begin && address < end) {
            return true;
        }
    }
    return false;
}

bool RestoreMappedEntryExecutableProtections(const Core::Module& module, std::string& error) {
    static std::atomic_int trace_budget{2};
    const bool trace_protections = trace_budget.fetch_sub(1, std::memory_order_relaxed) > 0;
    const auto info = module.GetModuleInfo();
    constexpr std::uint64_t PageSize = 0x1000;
    const std::uint64_t entry = module.GetEntryAddress();
    bool entry_in_segment = false;

    for (std::uint32_t i = 0; i < info.num_segments; ++i) {
        const auto& segment = info.segments[i];
        if (segment.size == 0) {
            continue;
        }

        const std::uint64_t begin = segment.address;
        const std::uint64_t end = begin + segment.size;
        if (entry >= begin && entry < end) {
            entry_in_segment = true;
            if (trace_protections) {
                NativeLog(ANDROID_LOG_INFO,
                          "[EXECUTOR_MAPPED_ENTRY_PROT] entrySegment index=%u addr=%p size=0x%llx prot=%s entry=%p",
                          i, reinterpret_cast<void*>(begin),
                          static_cast<unsigned long long>(segment.size),
                          ProtString(segment.prot).c_str(), reinterpret_cast<void*>(entry));
            }
        }

        if ((segment.prot & PF_EXEC) == 0) {
            continue;
        }

        const std::uint64_t page_base = Common::AlignDown(begin, PageSize);
        const std::uint64_t page_end = Common::AlignUp(end, PageSize);
        const std::uint64_t page_size = page_end - page_base;

        int host_prot = PROT_NONE;
        if (segment.prot & PF_READ) {
            host_prot |= PROT_READ;
        }
        if (segment.prot & PF_WRITE) {
            host_prot |= PROT_WRITE;
        }
        if (segment.prot & PF_EXEC) {
            host_prot |= PROT_EXEC;
        }

        errno = 0;
        const int rc = ::mprotect(reinterpret_cast<void*>(page_base), page_size, host_prot);
        if (trace_protections || rc != 0) {
            NativeLog(rc == 0 ? ANDROID_LOG_INFO : ANDROID_LOG_ERROR,
                      "[EXECUTOR_MAPPED_ENTRY_PROT] execProtect index=%u addr=%p size=0x%llx prot=%s rc=%d errno=%d",
                      i, reinterpret_cast<void*>(page_base),
                      static_cast<unsigned long long>(page_size), ProtString(segment.prot).c_str(),
                      rc, rc == 0 ? 0 : errno);
        }
        if (rc != 0) {
            error = std::string("mprotect executable segment failed index=") + std::to_string(i) +
                    " errno=" + std::to_string(errno) + " error=" + std::strerror(errno);
            return false;
        }
    }

    if (!entry_in_segment && trace_protections) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_MAPPED_ENTRY_PROT] entryOutsideSegments entry=%p segmentCount=%u",
                  reinterpret_cast<void*>(entry), info.num_segments);
    }

    return true;
}

template <typename Segment>
bool SegmentContainedBy(const Segment& inner, const Segment& outer) {
    if (inner.size == 0 || outer.size == 0) {
        return false;
    }
    const std::uint64_t inner_begin = inner.address;
    const std::uint64_t inner_end = inner.address + inner.size;
    const std::uint64_t outer_begin = outer.address;
    const std::uint64_t outer_end = outer.address + outer.size;
    return inner_begin >= outer_begin && inner_end <= outer_end;
}

