std::string GuestBytesHexCheckedLocked(const std::uint64_t address, const std::size_t size) {
    if (!address || size == 0) {
        return "";
    }
    std::ostringstream out;
    for (std::size_t i = 0; i < size; ++i) {
        if (i != 0) {
            out << ' ';
        }
        std::uint8_t byte = 0;
        if (!GuestReadByteCheckedLocked(address + i, byte)) {
            out << "??";
            continue;
        }
        static constexpr char Hex[] = "0123456789abcdef";
        out << Hex[(byte >> 4) & 0xf] << Hex[byte & 0xf];
    }
    return out.str();
}

void LogGuestStackCallchainLocked(const char* tag, const std::uint64_t rsp,
                                  const std::size_t scan_size) {
    if (rsp == 0 || scan_size < sizeof(std::uint64_t)) {
        return;
    }

    std::uint32_t hits = 0;
    for (std::uint64_t stack_off = 0; stack_off + sizeof(std::uint64_t) <= scan_size;
         stack_off += sizeof(std::uint64_t)) {
        const std::uint64_t slot_addr = rsp + stack_off;
        std::uint64_t candidate = 0;
        if (!GuestReadQwordCheckedLocked(slot_addr, candidate)) {
            continue;
        }
        Core::Module* module = FindGuestModuleByAddress(candidate);
        if (module == nullptr) {
            continue;
        }
        const std::uint64_t module_offset = GuestModuleOffset(*module, candidate);
        const std::uint64_t context = candidate >= 64 ? candidate - 64 : candidate;
        NativeLog(ANDROID_LOG_INFO,
                  "[%s] hit=%u stackOff=0x%llx slot=%p value=%p moduleOffset=0x%llx "
                  "module=%s retBytes=%s context=%s",
                  tag ? tag : "EXECUTOR_GUEST_CALLCHAIN", hits,
                  static_cast<unsigned long long>(stack_off),
                  reinterpret_cast<void*>(slot_addr), reinterpret_cast<void*>(candidate),
                  static_cast<unsigned long long>(module_offset), module->file.string().c_str(),
                  GuestBytesHexCheckedLocked(candidate, 32).c_str(),
                  GuestBytesHexCheckedLocked(context, 160).c_str());
        ++hits;
        if (hits >= 32) {
            NativeLog(ANDROID_LOG_INFO,
                      "[%s] truncated=1 rsp=%p scanSize=0x%zx",
                      tag ? tag : "EXECUTOR_GUEST_CALLCHAIN", reinterpret_cast<void*>(rsp),
                      scan_size);
            break;
        }
    }
    if (hits == 0) {
        NativeLog(ANDROID_LOG_INFO, "[%s] hits=0 rsp=%p scanSize=0x%zx stackHead=%s",
                  tag ? tag : "EXECUTOR_GUEST_CALLCHAIN", reinterpret_cast<void*>(rsp),
                  scan_size, GuestBytesHexCheckedLocked(rsp, 128).c_str());
    }
}

void LogMemoryManagerAllocateDispatchTraceLocked(const char* tag, const std::uint64_t max_entries) {
    const std::uint64_t count =
        g_memory_manager_allocate_dispatch_count.load(std::memory_order_relaxed);
    if (count == 0 || max_entries == 0) {
        NativeLog(ANDROID_LOG_INFO, "[%s] count=%llu entries=0",
                  tag ? tag : "EXECUTOR_MEMALLOC_DISPATCH_TRACE",
                  static_cast<unsigned long long>(count));
        return;
    }

    const std::uint64_t shown = std::min<std::uint64_t>(count, max_entries);
    for (std::uint64_t i = 0; i < shown; ++i) {
        const std::uint64_t seq = count - 1 - i;
        const auto entry =
            g_memory_manager_allocate_dispatch_trace[seq %
                                                     g_memory_manager_allocate_dispatch_trace.size()];
        Core::Module* target_module = FindGuestModuleByAddress(entry.dispatch_target);
        Core::Module* caller_module = FindGuestModuleByAddress(entry.caller_return);
        const std::uint64_t target_offset =
            target_module ? GuestModuleOffset(*target_module, entry.dispatch_target) : 0;
        const std::uint64_t caller_offset =
            caller_module ? GuestModuleOffset(*caller_module, entry.caller_return) : 0;
        NativeLog(ANDROID_LOG_ERROR,
                  "[%s] seq=%llu count=%llu slot=0x%llx obj=0x%llx vtable=0x%llx "
                  "target=0x%llx targetClass=%s targetOff=0x%llx size=0x%llx rounded=0x%llx "
                  "label=0x%llx caller=0x%llx callerOff=0x%llx callerModule=%s targetBytes=%s "
                  "objBytes=%s vtableBytes=%s",
                  tag ? tag : "EXECUTOR_MEMALLOC_DISPATCH_TRACE",
                  static_cast<unsigned long long>(seq), static_cast<unsigned long long>(count),
                  static_cast<unsigned long long>(entry.selected_slot),
                  static_cast<unsigned long long>(entry.allocator_object),
                  static_cast<unsigned long long>(entry.allocator_vtable),
                  static_cast<unsigned long long>(entry.dispatch_target),
                  ClassifyGuestAddressLocked(entry.dispatch_target).c_str(),
                  static_cast<unsigned long long>(target_offset),
                  static_cast<unsigned long long>(entry.size),
                  static_cast<unsigned long long>(entry.rounded_size),
                  static_cast<unsigned long long>(entry.label),
                  static_cast<unsigned long long>(entry.caller_return),
                  static_cast<unsigned long long>(caller_offset),
                  caller_module ? caller_module->file.string().c_str() : "<unknown>",
                  GuestBytesHexBestEffortLocked(entry.dispatch_target >= 16
                                                    ? entry.dispatch_target - 16
                                                    : entry.dispatch_target,
                                                0x60)
                      .c_str(),
                  GuestBytesHexBestEffortLocked(entry.allocator_object, 0x60).c_str(),
                  GuestBytesHexBestEffortLocked(entry.allocator_vtable, 0x40).c_str());
    }
}

std::string GuestCStringPreviewLocked(const std::uint64_t address, const std::size_t limit) {
    if (address == 0 || limit == 0) {
        return "";
    }

    std::string out;
    out.reserve(std::min<std::size_t>(limit, 128));
    for (std::size_t i = 0; i < limit; ++i) {
        std::uint8_t ch = 0;
        if (!GuestReadByteCheckedLocked(address + i, ch)) {
            break;
        }
        if (ch == 0) {
            break;
        }
        if (ch == '\n') {
            out += "\\n";
        } else if (ch == '\r') {
            out += "\\r";
        } else if (ch == '\t') {
            out += "\\t";
        } else if (std::isprint(ch)) {
            out.push_back(static_cast<char>(ch));
        } else {
            static constexpr char Hex[] = "0123456789abcdef";
            out += "\\x";
            out.push_back(Hex[(ch >> 4) & 0xf]);
            out.push_back(Hex[ch & 0xf]);
        }
    }
    return out;
}

int GuestCStringPrintableScoreLocked(const std::uint64_t address, const std::size_t limit) {
    if (address == 0 || limit == 0) {
        return -1;
    }

    int printable = 0;
    int non_printable = 0;
    bool has_percent = false;
    for (std::size_t i = 0; i < limit; ++i) {
        std::uint8_t ch = 0;
        if (!GuestReadByteCheckedLocked(address + i, ch)) {
            break;
        }
        if (ch == 0) {
            break;
        }
        if (ch == '%') {
            has_percent = true;
        }
        if (ch == '\n' || ch == '\r' || ch == '\t' || std::isprint(ch)) {
            ++printable;
        } else {
            ++non_printable;
        }
    }
    if (printable == 0) {
        return -1;
    }
    return printable - (non_printable * 4) + (has_percent ? 8 : 0);
}

std::string BuildMappedEntryBoundaryProbeJsonLocked() {
    const auto& probe = g_box64_boundary_probe;
    std::ostringstream out;
    out << "{"
        << R"("active":)" << (probe.active ? "true" : "false") << ","
        << R"("phase":")" << JsonEscape(probe.phase) << R"(",)"
        << R"("modulePath":")" << JsonEscape(probe.module_path) << R"(",)"
        << R"("moduleBase":")" << Hex64(probe.module_base) << R"(",)"
        << R"("entry":")" << Hex64(probe.entry) << R"(",)"
        << R"("entryOffset":")" << Hex64(probe.entry_offset) << R"(",)"
        << R"("entryBytes":")" << JsonEscape(probe.entry_bytes) << R"(",)"
        << R"("exitFunc":")" << Hex64(probe.exit_func) << R"(",)"
        << R"("exitBytes":")" << JsonEscape(probe.exit_bytes) << R"(",)"
        << R"("stackBase":")" << Hex64(probe.stack_base) << R"(",)"
        << R"("stackSize":")" << Hex64(probe.stack_size) << R"(",)"
        << R"("tcbBase":")" << Hex64(probe.tcb_base) << R"(",)"
        << R"("hleTrampolineBase":")" << Hex64(probe.hle_trampoline_base) << R"(",)"
        << R"("hleTrampolineSize":")" << Hex64(probe.hle_trampoline_size) << R"(",)"
        << R"("segmentCount":)" << probe.segment_count << ","
        << R"("hleCallCount":)" << probe.hle_call_count << ","
        << R"("firstHleName":")" << JsonEscape(probe.first_hle_name) << R"(",)"
        << R"("firstHleSymbol":")" << JsonEscape(probe.first_hle_symbol) << R"(",)"
        << R"("firstHleNative":")" << Hex64(probe.first_hle_native) << R"(",)"
        << R"("firstHleGuestRsp":")" << Hex64(probe.first_hle_guest_rsp) << R"(",)"
        << R"("firstHleGuestReturn":")" << Hex64(probe.first_hle_guest_return) << R"(",)"
        << R"("firstHleReturnClass":")" << JsonEscape(probe.first_hle_return_class) << R"(",)"
        << R"("firstHleReturnModule":")" << JsonEscape(probe.first_hle_return_module) << R"(",)"
        << R"("firstHleReturnOffset":")" << Hex64(probe.first_hle_return_offset) << R"(",)"
        << R"("lastHleName":")" << JsonEscape(probe.last_hle_name) << R"(",)"
        << R"("lastHleSymbol":")" << JsonEscape(probe.last_hle_symbol) << R"(",)"
        << R"("lastHleNative":")" << Hex64(probe.last_hle_native) << R"(",)"
        << R"("lastHleGuestRsp":")" << Hex64(probe.last_hle_guest_rsp) << R"(",)"
        << R"("lastHleGuestReturn":")" << Hex64(probe.last_hle_guest_return) << R"(",)"
        << R"("lastHleReturnClass":")" << JsonEscape(probe.last_hle_return_class) << R"(",)"
        << R"("lastHleReturnModule":")" << JsonEscape(probe.last_hle_return_module) << R"(",)"
        << R"("lastHleReturnOffset":")" << Hex64(probe.last_hle_return_offset) << R"(",)"
        << R"("debugTextCount":)" << probe.debug_text_count << ","
        << R"("firstDebugText":")" << JsonEscape(probe.first_debug_text) << R"(",)"
        << R"("lastDebugText":")" << JsonEscape(probe.last_debug_text) << R"(",)"
        << R"("lastDebugTextAddress":")" << Hex64(probe.last_debug_text_address) << R"(",)"
        << R"("lastDebugTextSource":")" << JsonEscape(probe.last_debug_text_source) << R"(",)"
        << R"("completed":)" << (probe.completed ? "true" : "false") << ","
        << R"("signaled":)" << (probe.signaled ? "true" : "false") << ","
        << R"("timeout":)" << (probe.timeout ? "true" : "false") << ","
        << R"("result":)" << probe.result << ","
        << R"("faultRip":")" << Hex64(probe.fault_rip) << R"(",)"
        << R"("faultAddr":")" << Hex64(probe.fault_addr) << R"(",)"
        << R"("faultRsp":")" << Hex64(probe.fault_rsp) << R"(",)"
        << R"("faultRax":")" << Hex64(probe.fault_rax) << R"(",)"
        << R"("faultRbx":")" << Hex64(probe.fault_rbx) << R"(",)"
        << R"("faultRcx":")" << Hex64(probe.fault_rcx) << R"(",)"
        << R"("faultRdx":")" << Hex64(probe.fault_rdx) << R"(",)"
        << R"("faultRsi":")" << Hex64(probe.fault_rsi) << R"(",)"
        << R"("faultRdi":")" << Hex64(probe.fault_rdi) << R"(",)"
        << R"("faultRbp":")" << Hex64(probe.fault_rbp) << R"(",)"
        << R"("faultR8":")" << Hex64(probe.fault_r8) << R"(",)"
        << R"("faultR9":")" << Hex64(probe.fault_r9) << R"(",)"
        << R"("faultR10":")" << Hex64(probe.fault_r10) << R"(",)"
        << R"("faultR11":")" << Hex64(probe.fault_r11) << R"(",)"
        << R"("faultR12":")" << Hex64(probe.fault_r12) << R"(",)"
        << R"("faultR13":")" << Hex64(probe.fault_r13) << R"(",)"
        << R"("faultR14":")" << Hex64(probe.fault_r14) << R"(",)"
        << R"("faultR15":")" << Hex64(probe.fault_r15) << R"(",)"
        << R"("faultRipClass":")" << JsonEscape(probe.fault_rip_class) << R"(",)"
        << R"("faultModulePath":")" << JsonEscape(probe.fault_module_path) << R"(",)"
        << R"("faultModuleOffset":")" << Hex64(probe.fault_module_offset) << R"(",)"
        << R"("faultBytes":")" << JsonEscape(probe.fault_bytes) << R"(",)"
        << R"("faultContextBytes":")" << JsonEscape(probe.fault_context_bytes) << R"(",)"
        << R"("faultStackBytes":")" << JsonEscape(probe.fault_stack_bytes) << R"(",)"
        << R"("faultNearestSymbol":")" << JsonEscape(probe.fault_nearest_symbol)
        << R"(",)"
        << R"("faultNearestSymbolOffset":")" << Hex64(probe.fault_nearest_symbol_offset)
        << R"(",)"
        << R"("faultNearestSymbolDelta":")" << Hex64(probe.fault_nearest_symbol_delta)
        << R"(",)"
        << R"("recentHle":[)";
    bool first_recent_json = true;
    const std::uint64_t first_recent =
        probe.recent_hle_sequence > probe.recent_hle.size()
            ? probe.recent_hle_sequence - probe.recent_hle.size()
            : 1;
    for (std::uint64_t seq = first_recent; seq <= probe.recent_hle_sequence; ++seq) {
        const auto& recent = probe.recent_hle[seq % probe.recent_hle.size()];
        if (recent.sequence != seq) {
            continue;
        }
        if (!first_recent_json) {
            out << ',';
        }
        first_recent_json = false;
        out << "{"
            << R"("seq":)" << recent.sequence << ","
            << R"("name":")" << JsonEscape(recent.name) << R"(",)"
            << R"("symbol":")" << JsonEscape(recent.symbol) << R"(",)"
            << R"("native":")" << Hex64(recent.native) << R"(",)"
            << R"("result":")" << Hex64(recent.result) << R"(",)"
            << R"("guestRsp":")" << Hex64(recent.guest_rsp) << R"(",)"
            << R"("guestReturn":")" << Hex64(recent.guest_return) << R"(",)"
            << R"("returnClass":")" << JsonEscape(recent.return_class) << R"(",)"
            << R"("modulePath":")" << JsonEscape(recent.module_path) << R"(",)"
            << R"("moduleOffset":")" << Hex64(recent.module_offset) << R"(",)"
            << R"("retBytes":")" << JsonEscape(recent.ret_bytes) << R"(",)"
            << R"("args":[")" << Hex64(recent.args[0]) << R"(",")"
            << Hex64(recent.args[1]) << R"(",")" << Hex64(recent.args[2])
            << R"(",")" << Hex64(recent.args[3]) << R"(",")"
            << Hex64(recent.args[4]) << R"(",")" << Hex64(recent.args[5])
            << R"("])"
            << "}";
    }
    out << "],"
        << R"("message":")" << JsonEscape(probe.message) << R"(")"
        << "}";
    return out.str();
}

std::string SnapshotMappedEntryBoundaryProbeJson() {
    std::lock_guard lock(g_box64_boundary_probe_lock);
    return BuildMappedEntryBoundaryProbeJsonLocked();
}

bool ExecutorMappedEntryHleHistoryEnabled() {
    static const bool enabled = [] {
        const auto flag = [](const char* name) {
            const char* value = std::getenv(name);
            return value != nullptr && value[0] != '\0' && std::strcmp(value, "0") != 0;
        };
        return flag("EXECUTOR_TRACE_MAPPED_ENTRY_HLE_HISTORY") ||
               flag("EXECUTOR_VERBOSE_HLE_BOUNDARY_RESULT") ||
               (!g_root.empty() && std::filesystem::exists(
                   std::filesystem::path(g_root) / "translator" /
                   "trace-mapped-entry-hle"));
    }();
    return enabled;
}

void BeginMappedEntryBoundaryProbe(const char* phase, Core::Module& module,
                                   const ExecutorBox64MappedEntryRequest& request) {
    std::lock_guard lock(g_box64_boundary_probe_lock);
    g_box64_boundary_probe = {};
    g_box64_boundary_probe.active = true;
    g_box64_boundary_probe.phase = phase ? phase : "unknown";
    g_box64_boundary_probe.module_path = module.file.string();
    g_box64_boundary_probe.entry = request.entry;
    g_box64_boundary_probe.entry_offset = GuestModuleOffset(module, request.entry);
    g_box64_boundary_probe.module_base = ModuleBaseAddress(module);
    g_box64_boundary_probe.exit_func = request.exit_func;
    g_box64_boundary_probe.stack_base = request.stack_base;
    g_box64_boundary_probe.stack_size = request.stack_size;
    g_box64_boundary_probe.tcb_base = request.tcb_base;
    MarkBox64GuestGcRootsDirty();
    g_box64_boundary_probe.hle_trampoline_base = request.hle_trampoline_base;
    g_box64_boundary_probe.hle_trampoline_size = request.hle_trampoline_size;
    g_box64_boundary_probe.segment_count = request.segment_count;
    g_box64_boundary_probe.entry_bytes = GuestBytesHex(request.entry, 96);
    g_box64_boundary_probe.exit_bytes = GuestBytesHex(request.exit_func, 16);

    std::uint64_t entry_param_q0 = 0;
    std::uint64_t entry_param_q1 = 0;
    if (request.entry_params != 0) {
        std::memcpy(&entry_param_q0, reinterpret_cast<const void*>(request.entry_params),
                    sizeof(entry_param_q0));
        std::memcpy(&entry_param_q1,
                    reinterpret_cast<const void*>(request.entry_params + sizeof(std::uint64_t)),
                    sizeof(entry_param_q1));
    }
    const std::uint64_t stack_top = request.stack_base + request.stack_size;
    std::uint64_t first_call_target = 0;
    std::uint64_t first_call_plt_slot = 0;
    std::uint64_t first_call_plt_value = 0;
    std::string first_call_bytes;
    std::string first_call_target_bytes;
    std::string first_call_plt_value_bytes;
    std::string first_call_plt_value_class = "none";
    std::ostringstream call_probe;
    if (request.entry != 0) {
        const auto* entry_bytes = reinterpret_cast<const std::uint8_t*>(request.entry);
        std::size_t call_count = 0;
        for (std::size_t i = 0; i + 5 <= 96; ++i) {
            if (entry_bytes[i] == 0xe8) {
                std::int32_t rel = 0;
                std::memcpy(&rel, entry_bytes + i + 1, sizeof(rel));
                const std::uint64_t call_target =
                    request.entry + i + 5 + static_cast<std::int64_t>(rel);
                std::uint64_t plt_slot = 0;
                std::uint64_t plt_value = 0;
                std::string plt_class = "none";
                std::string plt_value_bytes;
                if (IsCurrentMappedEntryReadableAddressLocked(call_target + 6)) {
                    const auto* target_bytes = reinterpret_cast<const std::uint8_t*>(call_target);
                    if (target_bytes[0] == 0xff && target_bytes[1] == 0x25) {
                        std::int32_t disp = 0;
                        std::memcpy(&disp, target_bytes + 2, sizeof(disp));
                        plt_slot = call_target + 6 + static_cast<std::int64_t>(disp);
                        if (IsCurrentMappedEntryReadableAddressLocked(plt_slot) &&
                            IsCurrentMappedEntryReadableAddressLocked(plt_slot +
                                                                      sizeof(std::uint64_t) - 1)) {
                            std::memcpy(&plt_value, reinterpret_cast<const void*>(plt_slot),
                                        sizeof(plt_value));
                            plt_class = ClassifyMappedEntryAddress(request, plt_value);
                            plt_value_bytes = GuestBytesHex(plt_value, 24);
                        }
                    }
                }
                if (call_count == 0) {
                    first_call_target = call_target;
                    first_call_bytes = GuestBytesHex(request.entry + i, 5);
                    first_call_target_bytes = GuestBytesHex(first_call_target, 96);
                    first_call_plt_slot = plt_slot;
                    first_call_plt_value = plt_value;
                    first_call_plt_value_class = plt_class;
                    first_call_plt_value_bytes = GuestBytesHex(first_call_plt_value, 64);
                }
                if (call_count < 8) {
                    if (call_count != 0) {
                        call_probe << ";";
                    }
                    call_probe << "i=" << call_count << "@+" << Hex64(i)
                               << " target=" << Hex64(call_target)
                               << " slot=" << Hex64(plt_slot)
                               << " value=" << Hex64(plt_value)
                               << " class=" << plt_class
                               << " bytes=" << plt_value_bytes;
                    ++call_count;
                    continue;
                }
                break;
            }
        }
    }
    if (!call_probe.str().empty()) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_MAPPED_ENTRY_CALL_PROBE] phase=%s entry=%p %s",
                  g_box64_boundary_probe.phase.c_str(), reinterpret_cast<void*>(request.entry),
                  call_probe.str().c_str());
    }

    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_MAPPED_ENTRY_BOUNDARY] phase=%s event=begin entry=%p "
              "entry_offset=0x%llx exit_func=%p stack=%p stack_size=0x%llx tcb=%p "
              "hle_base=%p hle_size=0x%llx entry_params=%p ep_q0=0x%llx ep_q1=0x%llx "
              "stack_top=%p first_call_target=%p first_call_bytes=%s "
              "first_call_target_bytes=%s first_call_plt_slot=%p first_call_plt_value=%p "
              "first_call_plt_value_class=%s first_call_plt_value_bytes=%s "
              "entry_call_probe=%s entry_bytes=%s exit_bytes=%s module=%s",
              g_box64_boundary_probe.phase.c_str(), reinterpret_cast<void*>(request.entry),
              static_cast<unsigned long long>(g_box64_boundary_probe.entry_offset),
              reinterpret_cast<void*>(request.exit_func),
              reinterpret_cast<void*>(request.stack_base),
              static_cast<unsigned long long>(request.stack_size),
              reinterpret_cast<void*>(request.tcb_base),
              reinterpret_cast<void*>(request.hle_trampoline_base),
              static_cast<unsigned long long>(request.hle_trampoline_size),
              reinterpret_cast<void*>(request.entry_params),
              static_cast<unsigned long long>(entry_param_q0),
              static_cast<unsigned long long>(entry_param_q1),
              reinterpret_cast<void*>(stack_top), reinterpret_cast<void*>(first_call_target),
              first_call_bytes.c_str(), first_call_target_bytes.c_str(),
              reinterpret_cast<void*>(first_call_plt_slot),
              reinterpret_cast<void*>(first_call_plt_value), first_call_plt_value_class.c_str(),
              first_call_plt_value_bytes.c_str(), call_probe.str().c_str(),
              g_box64_boundary_probe.entry_bytes.c_str(),
              g_box64_boundary_probe.exit_bytes.c_str(), module.file.string().c_str());
}

std::string FinishMappedEntryBoundaryProbe(const char* phase, const int result,
                                           const char* message) {
    std::unique_lock lock(g_box64_boundary_probe_lock);
    if (!g_box64_boundary_probe.active &&
        g_box64_boundary_probe.phase != (phase ? phase : "unknown")) {
        return BuildMappedEntryBoundaryProbeJsonLocked();
    }
    g_box64_boundary_probe.active = false;
    g_box64_boundary_probe.completed = result == 0;
    g_box64_boundary_probe.signaled = result >= 128 && result <= 191;
    g_box64_boundary_probe.timeout = result == -124;
    g_box64_boundary_probe.result = result;
    g_box64_boundary_probe.message = message ? message : "";

    ExecutorBox64MappedEntryRequest probe_request{};
    probe_request.entry = g_box64_boundary_probe.entry;
    probe_request.stack_base = g_box64_boundary_probe.stack_base;
    probe_request.stack_size = g_box64_boundary_probe.stack_size;
    probe_request.tcb_base = g_box64_boundary_probe.tcb_base;
    probe_request.exit_func = g_box64_boundary_probe.exit_func;
    probe_request.hle_trampoline_base = g_box64_boundary_probe.hle_trampoline_base;
    probe_request.hle_trampoline_size = g_box64_boundary_probe.hle_trampoline_size;

    const std::string_view message_view{g_box64_boundary_probe.message};
    ParseHexMessageField(message_view, "rip=", g_box64_boundary_probe.fault_rip);
    ParseHexMessageField(message_view, "fault=", g_box64_boundary_probe.fault_addr);
    ParseHexMessageField(message_view, "rsp=", g_box64_boundary_probe.fault_rsp);
    ParseHexMessageField(message_view, "rax=", g_box64_boundary_probe.fault_rax);
    ParseHexMessageField(message_view, "rbx=", g_box64_boundary_probe.fault_rbx);
    ParseHexMessageField(message_view, "rcx=", g_box64_boundary_probe.fault_rcx);
    ParseHexMessageField(message_view, "rdx=", g_box64_boundary_probe.fault_rdx);
    ParseHexMessageField(message_view, "rsi=", g_box64_boundary_probe.fault_rsi);
    ParseHexMessageField(message_view, "rdi=", g_box64_boundary_probe.fault_rdi);
    ParseHexMessageField(message_view, "rbp=", g_box64_boundary_probe.fault_rbp);
    ParseHexMessageField(message_view, "r8=", g_box64_boundary_probe.fault_r8);
    ParseHexMessageField(message_view, "r9=", g_box64_boundary_probe.fault_r9);
    ParseHexMessageField(message_view, "r10=", g_box64_boundary_probe.fault_r10);
    ParseHexMessageField(message_view, "r11=", g_box64_boundary_probe.fault_r11);
    ParseHexMessageField(message_view, "r12=", g_box64_boundary_probe.fault_r12);
    ParseHexMessageField(message_view, "r13=", g_box64_boundary_probe.fault_r13);
    ParseHexMessageField(message_view, "r14=", g_box64_boundary_probe.fault_r14);
    ParseHexMessageField(message_view, "r15=", g_box64_boundary_probe.fault_r15);
    if (g_box64_boundary_probe.fault_rip != 0) {
        g_box64_boundary_probe.fault_rip_class =
            ClassifyMappedEntryAddress(probe_request, g_box64_boundary_probe.fault_rip);
        if (Core::Module* module = FindGuestModuleByAddress(g_box64_boundary_probe.fault_rip)) {
            g_box64_boundary_probe.fault_module_path = module->file.string();
            g_box64_boundary_probe.fault_module_offset =
                GuestModuleOffset(*module, g_box64_boundary_probe.fault_rip);
            g_box64_boundary_probe.fault_bytes =
                GuestBytesHexCheckedLocked(g_box64_boundary_probe.fault_rip, 32);
            const std::uint64_t context_begin =
                g_box64_boundary_probe.fault_rip >= 96 ? g_box64_boundary_probe.fault_rip - 96
                                                       : g_box64_boundary_probe.fault_rip;
            g_box64_boundary_probe.fault_context_bytes =
                GuestBytesHexCheckedLocked(context_begin, 192);
            g_box64_boundary_probe.fault_nearest_symbol = NearestGuestSymbolName(
                *module, g_box64_boundary_probe.fault_rip,
                g_box64_boundary_probe.fault_nearest_symbol_offset,
                g_box64_boundary_probe.fault_nearest_symbol_delta);
        }
    }
    if (g_box64_boundary_probe.fault_rsp != 0) {
        g_box64_boundary_probe.fault_stack_bytes =
            GuestBytesHexCheckedLocked(g_box64_boundary_probe.fault_rsp, 192);
    }

    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_FAULT_REGS] rip=%p fault=%p rsp=%p rbp=%p rax=%p rbx=%p rcx=%p "
              "rdx=%p rsi=%p rdi=%p r8=%p r9=%p r10=%p r11=%p r12=%p r13=%p r14=%p r15=%p",
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rip),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_addr),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rsp),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rbp),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rax),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rbx),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rcx),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rdx),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rsi),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rdi),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r8),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r9),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r10),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r11),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r12),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r13),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r14),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r15));
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_FAULT_POINTERS] rdi=%p bytes=%s r13=%p bytes=%s r14=%p bytes=%s "
              "rbp=%p bytes=%s rsp=%p bytes=%s",
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rdi),
              GuestBytesHexCheckedLocked(g_box64_boundary_probe.fault_rdi, 96).c_str(),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r13),
              GuestBytesHexCheckedLocked(g_box64_boundary_probe.fault_r13, 96).c_str(),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r14),
              GuestBytesHexCheckedLocked(g_box64_boundary_probe.fault_r14, 96).c_str(),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rbp),
              GuestBytesHexCheckedLocked(g_box64_boundary_probe.fault_rbp, 96).c_str(),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rsp),
              GuestBytesHexCheckedLocked(g_box64_boundary_probe.fault_rsp, 96).c_str());
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_MAPPED_ENTRY_BOUNDARY] phase=%s event=end result=%d signaled=%d "
              "timeout=%d hle_calls=%llu first_hle=%s first_return=%p "
              "first_return_class=%s last_hle=%s last_return=%p last_return_class=%s "
              "fault_rip=%p fault_class=%s fault_offset=0x%llx fault_symbol=%s+0x%llx "
              "fault_bytes=%s fault_context=%s fault_stack=%s regs="
              "rax:%p rbx:%p rcx:%p rdx:%p rsi:%p rdi:%p rbp:%p rsp:%p "
              "r8:%p r9:%p r10:%p r11:%p r12:%p r13:%p r14:%p r15:%p message=%s",
              g_box64_boundary_probe.phase.c_str(), result,
              g_box64_boundary_probe.signaled ? 1 : 0,
              g_box64_boundary_probe.timeout ? 1 : 0,
              static_cast<unsigned long long>(g_box64_boundary_probe.hle_call_count),
              g_box64_boundary_probe.first_hle_name.empty()
                  ? "<none>"
                  : g_box64_boundary_probe.first_hle_name.c_str(),
              reinterpret_cast<void*>(g_box64_boundary_probe.first_hle_guest_return),
              g_box64_boundary_probe.first_hle_return_class.empty()
                  ? "<none>"
                  : g_box64_boundary_probe.first_hle_return_class.c_str(),
              g_box64_boundary_probe.last_hle_name.empty()
                  ? "<none>"
                  : g_box64_boundary_probe.last_hle_name.c_str(),
              reinterpret_cast<void*>(g_box64_boundary_probe.last_hle_guest_return),
              g_box64_boundary_probe.last_hle_return_class.empty()
                  ? "<none>"
                  : g_box64_boundary_probe.last_hle_return_class.c_str(),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rip),
              g_box64_boundary_probe.fault_rip_class.empty()
                  ? "<none>"
                  : g_box64_boundary_probe.fault_rip_class.c_str(),
              static_cast<unsigned long long>(g_box64_boundary_probe.fault_module_offset),
              g_box64_boundary_probe.fault_nearest_symbol.empty()
                  ? "<none>"
                  : g_box64_boundary_probe.fault_nearest_symbol.c_str(),
              static_cast<unsigned long long>(g_box64_boundary_probe.fault_nearest_symbol_delta),
              g_box64_boundary_probe.fault_bytes.empty()
                  ? "<none>"
                  : g_box64_boundary_probe.fault_bytes.c_str(),
              g_box64_boundary_probe.fault_context_bytes.empty()
                  ? "<none>"
                  : g_box64_boundary_probe.fault_context_bytes.c_str(),
              g_box64_boundary_probe.fault_stack_bytes.empty()
                  ? "<none>"
                  : g_box64_boundary_probe.fault_stack_bytes.c_str(),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rax),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rbx),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rcx),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rdx),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rsi),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rdi),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rbp),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_rsp),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r8),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r9),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r10),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r11),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r12),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r13),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r14),
              reinterpret_cast<void*>(g_box64_boundary_probe.fault_r15),
              message ? message : "");

    if (g_box64_boundary_probe.fault_rip != 0) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_FAULT_CONTEXT] rip=%p offset=0x%llx context=%s",
                  reinterpret_cast<void*>(g_box64_boundary_probe.fault_rip),
                  static_cast<unsigned long long>(g_box64_boundary_probe.fault_module_offset),
                  g_box64_boundary_probe.fault_context_bytes.empty()
                      ? "<none>"
                      : g_box64_boundary_probe.fault_context_bytes.c_str());
    }
    if (g_box64_boundary_probe.fault_rsp != 0) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_FAULT_STACK] rsp=%p bytes=%s",
                  reinterpret_cast<void*>(g_box64_boundary_probe.fault_rsp),
                  g_box64_boundary_probe.fault_stack_bytes.empty()
                      ? "<none>"
                      : g_box64_boundary_probe.fault_stack_bytes.c_str());
        LogGuestStackCallchainLocked("EXECUTOR_FAULT_CALLCHAIN_DEEP",
                                     g_box64_boundary_probe.fault_rsp, 1024);

        for (std::uint64_t stack_off = 0; stack_off + sizeof(std::uint64_t) <= 192;
             stack_off += sizeof(std::uint64_t)) {
            const std::uint64_t slot_addr = g_box64_boundary_probe.fault_rsp + stack_off;
            if (!IsCurrentMappedEntryReadableAddressLocked(slot_addr)) {
                continue;
            }
            std::uint64_t candidate = 0;
            std::memcpy(&candidate, reinterpret_cast<const void*>(slot_addr), sizeof(candidate));
            Core::Module* module = FindGuestModuleByAddress(candidate);
            if (module == nullptr) {
                continue;
            }
            const std::uint64_t module_offset = GuestModuleOffset(*module, candidate);
            const std::uint64_t context = candidate >= 64 ? candidate - 64 : candidate;
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_FAULT_CALLCHAIN] stackOff=0x%llx value=%p "
                      "moduleOffset=0x%llx module=%s retBytes=%s context=%s",
                      static_cast<unsigned long long>(stack_off),
                      reinterpret_cast<void*>(candidate),
                      static_cast<unsigned long long>(module_offset),
                      module->file.string().c_str(),
                      GuestBytesHexCheckedLocked(candidate, 32).c_str(),
                      GuestBytesHexCheckedLocked(context, 160).c_str());
        }
    }

    const std::uint64_t first_recent =
        g_box64_boundary_probe.recent_hle_sequence > g_box64_boundary_probe.recent_hle.size()
            ? g_box64_boundary_probe.recent_hle_sequence - g_box64_boundary_probe.recent_hle.size()
            : 1;
    for (std::uint64_t seq = first_recent; seq <= g_box64_boundary_probe.recent_hle_sequence;
         ++seq) {
        const auto& recent =
            g_box64_boundary_probe.recent_hle[seq % g_box64_boundary_probe.recent_hle.size()];
        if (recent.sequence != seq) {
            continue;
        }
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_HLE_RECENT] seq=%llu name=%s symbol=%s native=%p result=%p "
                  "ret=%p returnOff=0x%llx retClass=%s module=%s retBytes=%s "
                  "args=%p,%p,%p,%p,%p,%p rsp=%p",
                  static_cast<unsigned long long>(recent.sequence),
                  recent.name.empty() ? "<unknown>" : recent.name.c_str(),
                  recent.symbol.empty() ? "<unknown>" : recent.symbol.c_str(),
                  reinterpret_cast<void*>(recent.native), reinterpret_cast<void*>(recent.result),
                  reinterpret_cast<void*>(recent.guest_return),
                  static_cast<unsigned long long>(recent.module_offset),
                  recent.return_class.empty() ? "<unknown>" : recent.return_class.c_str(),
                  recent.module_path.empty() ? "<unknown>" : recent.module_path.c_str(),
                  recent.ret_bytes.empty() ? "<unreadable>" : recent.ret_bytes.c_str(),
                  reinterpret_cast<void*>(recent.args[0]), reinterpret_cast<void*>(recent.args[1]),
                  reinterpret_cast<void*>(recent.args[2]), reinterpret_cast<void*>(recent.args[3]),
                  reinterpret_cast<void*>(recent.args[4]), reinterpret_cast<void*>(recent.args[5]),
                  reinterpret_cast<void*>(recent.guest_rsp));
    }

    const bool should_present_itemzflow_bootstrap =
        g_box64_boundary_probe.phase == "core" &&
        g_box64_boundary_probe.module_path.find("ItemzCore.self") != std::string::npos &&
        g_box64_boundary_probe.last_debug_text.find("program_id") != std::string::npos &&
        g_itemzflow_bootstrap_frame_count.load(std::memory_order_acquire) == 0;
    std::string snapshot = BuildMappedEntryBoundaryProbeJsonLocked();
    lock.unlock();

    if (should_present_itemzflow_bootstrap) {
        std::lock_guard status_lock(g_lock);
        PresentItemzflowLauncherFrameLocked(1920, 1080, "itemzcore_program_id_boundary");
    }
    return snapshot;
}

void RecordMappedEntryHleBoundary(const char* name, const char* symbol_name,
                                  const std::uint64_t native_function,
                                  const std::uint64_t guest_rsp) {
    if (!ExecutorMappedEntryHleHistoryEnabled()) {
        return;
    }
    std::lock_guard lock(g_box64_boundary_probe_lock);
    if (!g_box64_boundary_probe.active) {
        return;
    }

    const std::uint64_t guest_return = GuestReturnAddress(guest_rsp);
    Core::Module* module = FindGuestModuleByAddress(guest_return);
    ExecutorBox64MappedEntryRequest probe_request{};
    probe_request.entry = g_box64_boundary_probe.entry;
    probe_request.stack_base = g_box64_boundary_probe.stack_base;
    probe_request.stack_size = g_box64_boundary_probe.stack_size;
    probe_request.tcb_base = g_box64_boundary_probe.tcb_base;
    probe_request.exit_func = g_box64_boundary_probe.exit_func;
    probe_request.hle_trampoline_base = g_box64_boundary_probe.hle_trampoline_base;
    probe_request.hle_trampoline_size = g_box64_boundary_probe.hle_trampoline_size;
    const std::string return_class = ClassifyMappedEntryAddress(probe_request, guest_return);
    const std::string module_path = module ? module->file.string() : "";
    const std::uint64_t module_offset = module ? GuestModuleOffset(*module, guest_return) : 0;
    ++g_box64_boundary_probe.hle_call_count;
    const bool first = g_box64_boundary_probe.hle_call_count == 1;
    if (first) {
        g_box64_boundary_probe.first_hle_name = name ? name : "";
        g_box64_boundary_probe.first_hle_symbol = symbol_name ? symbol_name : "";
        g_box64_boundary_probe.first_hle_native = native_function;
        g_box64_boundary_probe.first_hle_guest_rsp = guest_rsp;
        g_box64_boundary_probe.first_hle_guest_return = guest_return;
        g_box64_boundary_probe.first_hle_return_class = return_class;
        g_box64_boundary_probe.first_hle_return_module = module_path;
        g_box64_boundary_probe.first_hle_return_offset = module_offset;
    }
    g_box64_boundary_probe.last_hle_name = name ? name : "";
    g_box64_boundary_probe.last_hle_symbol = symbol_name ? symbol_name : "";
    g_box64_boundary_probe.last_hle_native = native_function;
    g_box64_boundary_probe.last_hle_guest_rsp = guest_rsp;
    g_box64_boundary_probe.last_hle_guest_return = guest_return;
    g_box64_boundary_probe.last_hle_return_class = return_class;
    g_box64_boundary_probe.last_hle_return_module = module_path;
    g_box64_boundary_probe.last_hle_return_offset = module_offset;

    static std::atomic_int log_budget{32};
    static const bool trace_hle = std::getenv("EXECUTOR_TRACE_LIVE_HLE") != nullptr;
    if ((trace_hle || first) &&
        log_budget.fetch_sub(1, std::memory_order_relaxed) > 0) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_MAPPED_ENTRY_HLE] phase=%s count=%llu name=%s symbol=%s "
                  "native=%p guest_rsp=%p guest_return=%p return_class=%s "
                  "return_offset=0x%llx module=%s",
                  g_box64_boundary_probe.phase.c_str(),
                  static_cast<unsigned long long>(g_box64_boundary_probe.hle_call_count),
                  name && name[0] ? name : "<unknown>",
                  symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
                  reinterpret_cast<void*>(native_function), reinterpret_cast<void*>(guest_rsp),
                  reinterpret_cast<void*>(guest_return), return_class.c_str(),
                  static_cast<unsigned long long>(module_offset),
                  module_path.empty() ? "<unknown>" : module_path.c_str());
    }
}

void RecordMappedEntryHleResult(const char* name, const char* symbol_name,
                                const std::uint64_t native_function, const std::uint64_t result,
                                const std::uint64_t arg0, const std::uint64_t arg1,
                                const std::uint64_t arg2, const std::uint64_t arg3,
                                const std::uint64_t arg4, const std::uint64_t arg5,
                                const std::uint64_t guest_rsp) {
    if (!ExecutorMappedEntryHleHistoryEnabled()) {
        return;
    }
    std::lock_guard lock(g_box64_boundary_probe_lock);
    if (!g_box64_boundary_probe.active) {
        return;
    }

    const std::uint64_t guest_return = GuestReturnAddress(guest_rsp);
    Core::Module* module = FindGuestModuleByAddress(guest_return);
    ExecutorBox64MappedEntryRequest probe_request{};
    probe_request.entry = g_box64_boundary_probe.entry;
    probe_request.stack_base = g_box64_boundary_probe.stack_base;
    probe_request.stack_size = g_box64_boundary_probe.stack_size;
    probe_request.tcb_base = g_box64_boundary_probe.tcb_base;
    probe_request.exit_func = g_box64_boundary_probe.exit_func;
    probe_request.hle_trampoline_base = g_box64_boundary_probe.hle_trampoline_base;
    probe_request.hle_trampoline_size = g_box64_boundary_probe.hle_trampoline_size;

    const std::uint64_t seq = ++g_box64_boundary_probe.recent_hle_sequence;
    auto& recent = g_box64_boundary_probe.recent_hle[seq % g_box64_boundary_probe.recent_hle.size()];
    recent = {};
    recent.sequence = seq;
    recent.name = name ? name : "";
    recent.symbol = symbol_name ? symbol_name : "";
    recent.native = native_function;
    recent.guest_rsp = guest_rsp;
    recent.guest_return = guest_return;
    recent.return_class = ClassifyMappedEntryAddress(probe_request, guest_return);
    recent.module_path = module ? module->file.string() : "";
    recent.module_offset = module ? GuestModuleOffset(*module, guest_return) : 0;
    recent.result = result;
    recent.args = {arg0, arg1, arg2, arg3, arg4, arg5};
    recent.ret_bytes = IsCurrentMappedEntryReadableAddressLocked(guest_return)
                           ? GuestBytesHexCheckedLocked(guest_return, 24)
                           : std::string{};

    {
        const std::string_view n = name ? name : "";
        const std::string_view s = symbol_name ? symbol_name : "";
        const auto has = [&](const char* token) {
            return n.find(token) != std::string_view::npos ||
                   s.find(token) != std::string_view::npos;
        };
        const bool critical =
            has("sceGnm") || has("sceAgc") || has("sceVideoOut") || has("sceSysmodule") ||
            has("scePthread") || has("pthread") || has("sem_") || has("sceKernelWait") ||
            has("sceKernelSignal") || has("sceKernelCreateEqueue") ||
            has("sceKernelCreateEventFlag") || has("sceKernelPollEventFlag") ||
            has("sceKernelSetEventFlag") || has("sceKernelOpen") || has("sceKernelRead") ||
            has("sceKernelReadv") || has("sceKernelPread") || has("sceKernelPreadv") ||
            has("sceKernelLseek") || has("sceKernelStat") || has("sceKernelFstat") ||
            has("sceKernelMmap") || has("sceKernelMunmap") || has("sceKernelClose") ||
            has("sceKernelLoadStartModule") || has("LoadStartModule") ||
            has("scePad") || has("sceUserService") ||
            has("sceSystemService") || has("sceSaveData") || has("Fios") || has("File");
        static std::atomic_int light_boundary_budget{384};
        static std::atomic_int verbose_boundary_budget{12000};
        static const bool verbose =
            std::getenv("EXECUTOR_TRACE_LIVE_HLE") != nullptr ||
            std::getenv("EXECUTOR_TRACE_LIVE_WIDE") != nullptr ||
            std::getenv("EXECUTOR_VERBOSE_HLE_BOUNDARY_RESULT") != nullptr;
        const int previous =
            verbose ? verbose_boundary_budget.fetch_sub(1, std::memory_order_relaxed)
                    : light_boundary_budget.fetch_sub(1, std::memory_order_relaxed);
        if ((critical || verbose) && previous > 0) {
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_HLE_BOUNDARY_RESULT] seq=%llu name=%s symbol=%s native=%p "
                      "result=%p ret=%p retClass=%s returnOff=0x%llx module=%s "
                      "args=%p,%p,%p,%p,%p,%p rsp=%p",
                      static_cast<unsigned long long>(seq),
                      name && name[0] ? name : "<unknown>",
                      symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
                      reinterpret_cast<void*>(native_function), reinterpret_cast<void*>(result),
                      reinterpret_cast<void*>(guest_return), recent.return_class.c_str(),
                      static_cast<unsigned long long>(recent.module_offset),
                      recent.module_path.empty() ? "<unknown>" : recent.module_path.c_str(),
                      reinterpret_cast<void*>(arg0), reinterpret_cast<void*>(arg1),
                      reinterpret_cast<void*>(arg2), reinterpret_cast<void*>(arg3),
                      reinterpret_cast<void*>(arg4), reinterpret_cast<void*>(arg5),
                      reinterpret_cast<void*>(guest_rsp));
        }
    }

    if ((symbol_name && (std::strstr(symbol_name, "Fios") || std::strstr(symbol_name, "Exists"))) ||
        (name && std::strstr(name, "Exists"))) {
        const std::uint64_t aa[6] = {arg0, arg1, arg2, arg3, arg4, arg5};
        for (int ai = 0; ai < 6; ++ai) {
            const std::uint64_t a = aa[ai];
            if (a < 0x10000ull || a >= 0x810000000ull) {
                continue;
            }
            if (!IsCurrentMappedEntryReadableAddressLocked(a)) {
                continue;
            }
            char pbuf[176];
            int k = 0;
            for (; k < static_cast<int>(sizeof(pbuf)) - 1; ++k) {
                char c = 0;
                std::memcpy(&c, reinterpret_cast<const void*>(a + static_cast<std::uint64_t>(k)), 1);
                if (c == 0) {
                    break;
                }
                pbuf[k] = (c >= 0x20 && c < 0x7f) ? c : '.';
            }
            pbuf[k] = 0;
            if (std::strstr(pbuf, "Assembly-CSharp")) {
                NativeLog(ANDROID_LOG_ERROR,
                          "[EXECUTOR_ASM_EXISTS_CALLER] sym=%s path=%s result=0x%llx caller=0x%llx "
                          "retClass=%s retOff=0x%llx retMod=%s",
                          symbol_name && symbol_name[0] ? symbol_name : "?", pbuf,
                          static_cast<unsigned long long>(result),
                          static_cast<unsigned long long>(guest_return), recent.return_class.c_str(),
                          static_cast<unsigned long long>(recent.module_offset),
                          recent.module_path.empty() ? "?" : recent.module_path.c_str());
                break;
            }
        }
    }

    {
        const std::uint64_t low32 = result & 0xFFFFFFFFull;
        const std::uint64_t high32 = result >> 32;
        const bool error_like = (low32 & 0x80000000ull) != 0 &&
                                (high32 == 0 || high32 == 0xFFFFFFFFull);
        if (error_like) {
            const bool expected_libc_compare_result = IsLibcCompareHleTarget(name, symbol_name);
            static const bool trace_libc_compare_errors =
                std::getenv("EXECUTOR_TRACE_LIBC_COMPARE_ERRORS") != nullptr;
            if (expected_libc_compare_result && !trace_libc_compare_errors) {
                return;
            }
            const std::string_view n = name ? name : "";
            const std::string_view s = symbol_name ? symbol_name : "";
            const auto has = [&](const char* token) {
                return n.find(token) != std::string_view::npos ||
                       s.find(token) != std::string_view::npos;
            };
            const bool expected_trylock_busy =
                low32 == 0x80020010ull &&
                (has("pthread_mutex_trylock") || has("posix_pthread_mutex_trylock") ||
                 has("upoVrzMHFeE"));
            static const bool verbose_trylock_busy =
                std::getenv("EXECUTOR_VERBOSE_HLE_TRYLOCK_BUSY") != nullptr;
            if (!expected_trylock_busy || verbose_trylock_busy) {
                g_conformance.hle_error_count.fetch_add(1, std::memory_order_relaxed);
                static std::atomic_int hle_error_budget{6000};
                static std::atomic_int hle_error_light_budget{24};
                static const bool verbose_hle_err =
                    std::getenv("EXECUTOR_VERBOSE_HLE_ERR") != nullptr;
                const bool quiet_light_hle_errors =
                    ExecutorLightOracleMode() && !verbose_hle_err;
                const int hle_error_budget_before =
                    quiet_light_hle_errors
                        ? hle_error_light_budget.fetch_sub(1, std::memory_order_relaxed)
                        : hle_error_budget.fetch_sub(1, std::memory_order_relaxed);
                if (hle_error_budget_before > 0) {
                    NativeLog(ANDROID_LOG_WARN,
                              "[EXECUTOR_HLE_ERR] seq=%llu name=%s symbol=%s result=0x%llx "
                              "retClass=%s retOff=0x%llx retMod=%s args=%p,%p,%p,%p,%p,%p",
                              static_cast<unsigned long long>(seq),
                              name && name[0] ? name : "<unknown>",
                              symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
                              static_cast<unsigned long long>(result),
                              recent.return_class.c_str(),
                              static_cast<unsigned long long>(recent.module_offset),
                              recent.module_path.empty() ? "<unknown>" : recent.module_path.c_str(),
                              reinterpret_cast<void*>(arg0), reinterpret_cast<void*>(arg1),
                              reinterpret_cast<void*>(arg2), reinterpret_cast<void*>(arg3),
                              reinterpret_cast<void*>(arg4), reinterpret_cast<void*>(arg5));
                    static std::FILE* err_file = std::fopen(
                        "/data/data/app.lsx4.android/files/executor-hle-err.log", "w");
                    if (err_file != nullptr) {
                        std::fprintf(err_file,
                                     "seq=%llu name=%s symbol=%s result=0x%llx retClass=%s retOff=0x%llx "
                                     "retMod=%s args=0x%llx,0x%llx,0x%llx,0x%llx,0x%llx,0x%llx\n",
                                     static_cast<unsigned long long>(seq),
                                     name && name[0] ? name : "<unknown>",
                                     symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
                                     static_cast<unsigned long long>(result),
                                     recent.return_class.c_str(),
                                     static_cast<unsigned long long>(recent.module_offset),
                                     recent.module_path.empty() ? "<unknown>" : recent.module_path.c_str(),
                                     HleLogWord(arg0), HleLogWord(arg1),
                                     HleLogWord(arg2), HleLogWord(arg3),
                                     HleLogWord(arg4), HleLogWord(arg5));
                        std::fflush(err_file);
                    }
                }
            }
        }
    }

    static const bool trace_mono_hle = std::getenv("EXECUTOR_TRACE_MONO_HLE") != nullptr;
    if (trace_mono_hle && module != nullptr &&
        module->file.string().find("mono-ps4") != std::string::npos) {
        static std::atomic_int mono_hle_result_budget{12000};
        if (mono_hle_result_budget.fetch_sub(1, std::memory_order_relaxed) > 0) {
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_MONO_HLE_RESULT] seq=%llu name=%s symbol=%s result=%p "
                      "ret=%p monoOff=0x%llx args=%p,%p,%p,%p,%p,%p retBytes=%s",
                      static_cast<unsigned long long>(seq),
                      name && name[0] ? name : "<unknown>",
                      symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
                      reinterpret_cast<void*>(result), reinterpret_cast<void*>(guest_return),
                      static_cast<unsigned long long>(recent.module_offset),
                      reinterpret_cast<void*>(arg0), reinterpret_cast<void*>(arg1),
                      reinterpret_cast<void*>(arg2), reinterpret_cast<void*>(arg3),
                      reinterpret_cast<void*>(arg4), reinterpret_cast<void*>(arg5),
                      recent.ret_bytes.empty() ? "<unreadable>" : recent.ret_bytes.c_str());
        }
    }
}

bool IsKernelDebugOutTextTarget(const char* name, const char* symbol_name) {
    return HleNameMatches(name, "sceKernelDebugOutText", "9JYNqN6jAKI") ||
           (symbol_name != nullptr &&
            std::string_view(symbol_name).find("sceKernelDebugOutText") !=
                std::string_view::npos);
}

void RecordMappedEntryDebugText(const std::uint64_t arg0, const std::uint64_t arg1,
                                const std::uint64_t arg2, const std::uint64_t arg3,
                                const std::uint64_t arg4, const std::uint64_t arg5,
                                const std::uint64_t guest_rsp) {
    std::unique_lock lock(g_box64_boundary_probe_lock);
    if (!g_box64_boundary_probe.active) {
        return;
    }

    struct Candidate {
        const char* source;
        std::uint64_t address;
        int bias;
    };
    std::vector<Candidate> candidates{
        {"arg0_context", arg0, -8},
        {"arg1_text", arg1, 24},
        {"arg2_format_or_shadow", arg2, -32},
        {"arg3", arg3, 2},
        {"arg4", arg4, 2},
        {"arg5", arg5, 2},
    };

    const auto add_indirect_candidates = [&](const char* prefix, const std::uint64_t base) {
        if (base == 0) {
            return;
        }
        for (std::size_t offset = 0; offset <= 64; offset += sizeof(std::uint64_t)) {
            if (!IsCurrentMappedEntryReadableAddressLocked(base + offset) ||
                !IsCurrentMappedEntryReadableAddressLocked(base + offset + sizeof(std::uint64_t) -
                                                           1)) {
                continue;
            }
            std::uint64_t value = 0;
            std::memcpy(&value, reinterpret_cast<const void*>(base + offset), sizeof(value));
            if (value == 0) {
                continue;
            }
            candidates.push_back(
                {prefix, value, offset == 0 ? 12 : static_cast<int>(8 - offset / 8)});
        }
    };

    add_indirect_candidates("arg1_indirect", arg1);
    add_indirect_candidates("guest_rsp_indirect", guest_rsp);

    std::string selected_source;
    std::uint64_t selected_address = 0;
    std::string selected_preview;
    int selected_score = -1;
    for (const auto& candidate : candidates) {
        int score = GuestCStringPrintableScoreLocked(candidate.address, 512);
        const std::string preview = GuestCStringPreviewLocked(candidate.address, 512);
        if (preview == "%s %-5s %s:%d: %s\\n" || preview == "%s %-5s %s:%d: %s\n") {
            score -= 64;
        }
        score += candidate.bias;
        if (!preview.empty() && score > selected_score) {
            selected_source = candidate.source;
            selected_address = candidate.address;
            selected_preview = preview;
            selected_score = score;
        }
    }

    if (selected_preview.empty() || selected_score <= 0) {
        selected_source = "none";
        selected_address = 0;
        selected_preview.clear();
    } else {
        ++g_box64_boundary_probe.debug_text_count;
        if (g_box64_boundary_probe.first_debug_text.empty()) {
            g_box64_boundary_probe.first_debug_text = selected_preview;
        }
        g_box64_boundary_probe.last_debug_text = selected_preview;
        g_box64_boundary_probe.last_debug_text_address = selected_address;
        g_box64_boundary_probe.last_debug_text_source = selected_source;
    }

    const bool should_present_itemzflow_bootstrap =
        g_box64_boundary_probe.phase == "core" &&
        g_box64_boundary_probe.module_path.find("ItemzCore.self") != std::string::npos &&
        selected_preview.find("program_id") != std::string::npos &&
        g_itemzflow_bootstrap_frame_count.load(std::memory_order_acquire) == 0;

    static std::atomic_int debug_log_budget{512};
    if (debug_log_budget.fetch_sub(1, std::memory_order_relaxed) > 0) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_GUEST_DEBUG_TEXT] phase=%s source=%s address=%p "
                  "guest_rsp=%p text=\"%s\" arg1=%p arg2=%p arg1_hex=%s arg2_hex=%s",
                  g_box64_boundary_probe.phase.c_str(), selected_source.c_str(),
                  reinterpret_cast<void*>(selected_address),
                  reinterpret_cast<void*>(guest_rsp), selected_preview.c_str(),
                  reinterpret_cast<void*>(arg1), reinterpret_cast<void*>(arg2),
                  IsCurrentMappedEntryReadableAddressLocked(arg1) ? GuestBytesHex(arg1, 32).c_str()
                                                                  : "<unreadable>",
                  IsCurrentMappedEntryReadableAddressLocked(arg2) ? GuestBytesHex(arg2, 32).c_str()
                                                                  : "<unreadable>");
    }

    if (should_present_itemzflow_bootstrap) {
        lock.unlock();
        std::lock_guard status_lock(g_lock);
        PresentItemzflowLauncherFrameLocked(1920, 1080, "itemzcore_program_id_debug_text");
    }
}

bool IsPs4StoreModule(const Core::Module& module) {
    const std::string path = module.file.string();
    return path.find("ps4-store") != std::string::npos ||
           path.find("homebrew.elf") != std::string::npos;
}

extern "C" bool executor_lsx4_android_should_relax_guest_mutex(void* mutex) {
    const auto address = reinterpret_cast<std::uint64_t>(mutex);
    static const bool tolerate_low_guest_mutex =
        std::getenv("EXECUTOR_TOLERATE_LOW_GUEST_MUTEX") != nullptr;
    if (tolerate_low_guest_mutex && address < 0x10000) {
        static std::atomic_int log_budget{64};
        if (log_budget.fetch_sub(1, std::memory_order_relaxed) > 0) {
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_MUTEX_RELAX] live low guest mutex no-op guest=%p",
                      mutex);
        }
        return true;
    }

    auto* module = FindGuestModuleByAddress(address);
    if (!module || !IsPs4StoreModule(*module)) {
        return false;
    }

    const auto offset = GuestModuleOffset(*module, address);
    const bool sqlite_static_mutex =
        (offset >= 0x476000 && offset < 0x478000) || offset == 0x476098 || offset == 0x477720;
    if (!sqlite_static_mutex) {
        return false;
    }

    static std::atomic_int log_budget{32};
    if (log_budget.fetch_sub(1, std::memory_order_relaxed) > 0) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_MUTEX_RELAX] PS4 Store static mutex guest=%p offset=0x%llx module=%s",
                  mutex, static_cast<unsigned long long>(offset), module->file.string().c_str());
    }
    return true;
}

