void RecordLoadExecRequest(const char* title, const std::string& guest_path,
                           const std::filesystem::path& host_path, const int count) {
    std::lock_guard lock(g_load_exec_lock);
    g_load_exec_title = title ? title : "";
    g_load_exec_guest_path = guest_path;
    g_load_exec_host_path = host_path;
    g_load_exec_request_count = count;
}

LoadExecRequestSnapshot SnapshotLoadExecRequest() {
    std::lock_guard lock(g_load_exec_lock);
    LoadExecRequestSnapshot snapshot;
    snapshot.requested = !g_load_exec_title.empty();
    snapshot.count = g_load_exec_request_count;
    snapshot.title = g_load_exec_title;
    snapshot.guest_path = g_load_exec_guest_path;
    snapshot.host_path = g_load_exec_host_path;
    snapshot.host_exists =
        !snapshot.host_path.empty() && std::filesystem::exists(snapshot.host_path);
    return snapshot;
}

void ClearLoadExecRequest() {
    std::lock_guard lock(g_load_exec_lock);
    g_load_exec_title.clear();
    g_load_exec_guest_path.clear();
    g_load_exec_host_path.clear();
    g_load_exec_request_count = 0;
}

