float FloatFromXmmLow32(const std::uint64_t raw) {
    float value = 0.0f;
    const auto low = static_cast<std::uint32_t>(raw & 0xffffffffu);
    std::memcpy(&value, &low, sizeof(value));
    return value;
}

double DoubleFromXmmLow64(std::uint64_t raw);
std::uint64_t FloatToXmmLow32(float value);
std::uint64_t DoubleToXmmLow64(double value);

std::uint64_t GuestStackArg(const std::uint64_t guest_rsp, const std::size_t index) {
    if (guest_rsp == 0) {
        return 0;
    }
    constexpr std::uint64_t kWordSize = sizeof(std::uint64_t);
    if (index == std::numeric_limits<std::size_t>::max()) {
        return 0;
    }
    const auto word_index = static_cast<std::uint64_t>(index) + 1;
    if (word_index > std::numeric_limits<std::uint64_t>::max() / kWordSize) {
        return 0;
    }
    const std::uint64_t offset = word_index * kWordSize;
    if (offset > std::numeric_limits<std::uint64_t>::max() - guest_rsp) {
        return 0;
    }
    std::uint64_t value = 0;
    const std::uint64_t slot = guest_rsp + offset;
    return ExecutorJitReadGuestBytes(slot, &value, sizeof(value)) ? value : 0;
}

std::uint64_t GuestReturnAddress(const std::uint64_t guest_rsp) {
    if (guest_rsp == 0) {
        return 0;
    }
    std::uint64_t value = 0;
    return ExecutorJitReadGuestBytes(guest_rsp, &value, sizeof(value)) ? value : 0;
}

static bool ExecutorConformanceBadPtrIsLow(std::uint64_t ptr) {
    return ptr != 0 && ptr < 0x100000000ull;
}

static bool ExecutorConformanceBadPtrIsImageBaseResidual(std::uint64_t ptr) {
    return ptr >= 0x100000000ull && ptr < 0x200000000ull;
}

static bool ExecutorConformanceBadPtrIsTaggedOrWide(std::uint64_t ptr) {
    return ptr >= 0x100000000000ull;
}

static void ExecutorConformanceNoteBadPtr(std::uint64_t lhs, std::uint64_t rhs,
                                          std::uint64_t guest_return) {
    g_conformance.badptr_count.fetch_add(1, std::memory_order_relaxed);
    g_conformance.last_badptr_lhs.store(lhs, std::memory_order_relaxed);
    g_conformance.last_badptr_rhs.store(rhs, std::memory_order_relaxed);
    g_conformance.last_badptr_ret.store(guest_return, std::memory_order_relaxed);
    const std::uint64_t args[] = {lhs, rhs};
    for (std::uint64_t ptr : args) {
        if (ExecutorConformanceBadPtrIsLow(ptr)) {
            g_conformance.badptr_low_count.fetch_add(1, std::memory_order_relaxed);
        }
        if (ExecutorConformanceBadPtrIsImageBaseResidual(ptr)) {
            g_conformance.badptr_imagebase_count.fetch_add(1, std::memory_order_relaxed);
        }
        if (ExecutorConformanceBadPtrIsTaggedOrWide(ptr)) {
            g_conformance.badptr_tagged_count.fetch_add(1, std::memory_order_relaxed);
        }
    }
}

static void ExecutorConformanceAtomicMax(std::atomic<std::uint64_t>& value,
                                         std::uint64_t candidate) {
    std::uint64_t current = value.load(std::memory_order_relaxed);
    while (candidate > current &&
           !value.compare_exchange_weak(current, candidate, std::memory_order_relaxed,
                                        std::memory_order_relaxed)) {
    }
}

extern "C" void executor_conformance_note_reloc_audit(std::uint64_t relative,
                                                       std::uint64_t imagebase_addends,
                                                       std::uint64_t icall_hits,
                                                       std::uint64_t fallback_repairs) {
    g_conformance.reloc_probe_count.fetch_add(1, std::memory_order_relaxed);
    ExecutorConformanceAtomicMax(g_conformance.reloc_relative_count, relative);
    ExecutorConformanceAtomicMax(g_conformance.reloc_imagebase_addends, imagebase_addends);
    ExecutorConformanceAtomicMax(g_conformance.reloc_icall_hits, icall_hits);
    g_conformance.reloc_fallback_repairs.fetch_add(fallback_repairs, std::memory_order_relaxed);
}

extern "C" void executor_conformance_note_mono_domain_open(const char* name) {
    if (name == nullptr) {
        return;
    }
    g_conformance.mono_domain_open_count.fetch_add(1, std::memory_order_relaxed);
    if (std::strstr(name, "UnityEngine") != nullptr) {
        g_conformance.mono_unityengine_open_count.fetch_add(1, std::memory_order_relaxed);
    }
    if (std::strstr(name, "Assembly-CSharp") != nullptr) {
        g_conformance.mono_assembly_csharp_open_count.fetch_add(1, std::memory_order_relaxed);
    }
}

extern "C" void executor_conformance_note_managed_text(const char* text, std::size_t size) {
    if (text == nullptr || size == 0) {
        return;
    }
    constexpr std::size_t MaxProbe = 4096;
    const std::string_view view(text, std::min(size, MaxProbe));
    if (view.find("Unhandled Exception") != std::string_view::npos ||
        view.find("NullReferenceException") != std::string_view::npos ||
        view.find("System.NullReferenceException") != std::string_view::npos) {
        g_conformance.managed_exception_count.fetch_add(1, std::memory_order_relaxed);
    }
}

extern "C" std::uint64_t ExecutorGetLastHleGuestRsp() {
    std::lock_guard lock{g_box64_boundary_probe_lock};
    return g_box64_boundary_probe.last_hle_guest_rsp;
}

const char* ClassifyHleReturnSite(const std::uint64_t guest_return,
                                  const std::uint64_t hle_result) {
    if (guest_return == 0) {
        return "ret_slot_null";
    }
    if (!IsCurrentMappedEntryReadableAddressLocked(guest_return)) {
        return "ret_unreadable";
    }
    const auto* code = reinterpret_cast<const std::uint8_t*>(guest_return);
    if (hle_result == 0 && code[0] == 0x48 && code[1] == 0x8b && code[2] == 0x80) {
        return "ret_uses_null_rax_mov_rax_mem";
    }
    if (hle_result == 0 && code[0] == 0x48 && code[1] == 0x8b &&
        (code[2] & 0xf8) == 0x40) {
        return "ret_uses_null_rax_mov_reg_mem";
    }
    if (hle_result == 0 && code[0] == 0x48 && code[1] == 0x83) {
        return "ret_tests_null_rax";
    }
    return "ret_site_unclassified";
}

void RecordUnityPreloadPersistentReturnProbe(const char* name, const char* symbol_name,
                                             const std::uint64_t result,
                                             const std::uint64_t guest_return,
                                             const std::uint64_t arg0,
                                             const std::uint64_t arg1,
                                             const std::uint64_t arg2,
                                             const std::uint64_t arg3,
                                             const std::uint64_t arg4,
                                              const std::uint64_t arg5,
                                              const std::uint64_t guest_rsp) {
    static const bool enabled = ExecutorEnvFlag("EXECUTOR_TRACE_UNITY_PRELOAD_RETURN") ||
                                ExecutorEnvFlag("EXECUTOR_TRACE_LIVE_WIDE") ||
                                ExecutorEnvFlag("EXECUTOR_TRACE_LIVE_HLE");
    if (!enabled) {
        return;
    }
    Core::Module* module = FindGuestModuleByAddress(guest_return);
    if (!module) {
        return;
    }
    const std::uint64_t off = GuestModuleOffset(*module, guest_return);
    if (off != 0x4375c && off != 0x4376c) {
        return;
    }

    static std::atomic_int budget{64};
    if (budget.fetch_sub(1, std::memory_order_relaxed) <= 0) {
        return;
    }

    ExecutorBox64GuestRegsSnapshot regs{};
    const int regs_rc = TryGetCurrentGuestRegsSnapshot(regs);

    const auto read_q = [](std::uint64_t addr) -> std::uint64_t {
        std::uint64_t value = 0;
        if (addr != 0) {
            GuestReadQwordBestEffortLocked(addr, value);
        }
        return value;
    };

    std::uint64_t arg0_q0 = 0;
    std::uint64_t arg0_q8 = 0;
    std::uint64_t arg2_q0 = 0;
    std::uint64_t arg2_q8 = 0;
    std::uint64_t rax_q0 = 0;
    std::uint64_t r12_q0 = 0;
    std::uint64_t r13_q0 = 0;
    std::uint64_t r15_q0 = 0;
    std::string stack_bytes;
    {
        std::lock_guard lock(g_box64_boundary_probe_lock);
        arg0_q0 = read_q(arg0 + 0x00);
        arg0_q8 = read_q(arg0 + 0x08);
        arg2_q0 = read_q(arg2 + 0x00);
        arg2_q8 = read_q(arg2 + 0x08);
        if (regs_rc == 0) {
            rax_q0 = read_q(regs.regs[0]);
            r12_q0 = read_q(regs.regs[12]);
            r13_q0 = read_q(regs.regs[13]);
            r15_q0 = read_q(regs.regs[15]);
        }
        stack_bytes = GuestBytesHexCheckedLocked(guest_rsp, 96);
    }

    NativeLog(ANDROID_LOG_WARN,
              "[EXECUTOR_UNITY_PRELOAD_PERSISTENT_RET] name=%s symbol=%s result=%p "
              "ret=%p off=0x%llx regsRc=%d args=%p,%p,%p,%p,%p,%p "
              "rax=%p rbx=%p rcx=%p rdx=%p rsp=%p rbp=%p rsi=%p rdi=%p "
              "r8=%p r9=%p r10=%p r11=%p r12=%p r13=%p r14=%p r15=%p rip=%p "
              "arg0_q0=%p arg0_q8=%p arg2_q0=%p arg2_q8=%p "
              "rax_q0=%p r12_q0=%p r13_q0=%p r15_q0=%p stack=%s",
              name && name[0] ? name : "<unknown>",
              symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
              reinterpret_cast<void*>(result), reinterpret_cast<void*>(guest_return),
              static_cast<unsigned long long>(off), regs_rc,
              reinterpret_cast<void*>(arg0), reinterpret_cast<void*>(arg1),
              reinterpret_cast<void*>(arg2), reinterpret_cast<void*>(arg3),
              reinterpret_cast<void*>(arg4), reinterpret_cast<void*>(arg5),
              reinterpret_cast<void*>(regs.regs[0]), reinterpret_cast<void*>(regs.regs[3]),
              reinterpret_cast<void*>(regs.regs[1]), reinterpret_cast<void*>(regs.regs[2]),
              reinterpret_cast<void*>(regs.regs[4]), reinterpret_cast<void*>(regs.regs[5]),
              reinterpret_cast<void*>(regs.regs[6]), reinterpret_cast<void*>(regs.regs[7]),
              reinterpret_cast<void*>(regs.regs[8]), reinterpret_cast<void*>(regs.regs[9]),
              reinterpret_cast<void*>(regs.regs[10]), reinterpret_cast<void*>(regs.regs[11]),
              reinterpret_cast<void*>(regs.regs[12]), reinterpret_cast<void*>(regs.regs[13]),
              reinterpret_cast<void*>(regs.regs[14]), reinterpret_cast<void*>(regs.regs[15]),
              reinterpret_cast<void*>(regs.rip), reinterpret_cast<void*>(arg0_q0),
              reinterpret_cast<void*>(arg0_q8), reinterpret_cast<void*>(arg2_q0),
              reinterpret_cast<void*>(arg2_q8), reinterpret_cast<void*>(rax_q0),
              reinterpret_cast<void*>(r12_q0), reinterpret_cast<void*>(r13_q0),
              reinterpret_cast<void*>(r15_q0), stack_bytes.c_str());
}

const char* StoreAllocatorKind(const char* symbol_name) {
    if (SymbolNameContains(symbol_name, "ExecutorMspaceMalloc")) {
        return "mspace_malloc";
    }
    if (SymbolNameContains(symbol_name, "ExecutorMspaceCalloc")) {
        return "mspace_calloc";
    }
    if (SymbolNameContains(symbol_name, "ExecutorMspaceRealloc")) {
        return "mspace_realloc";
    }
    if (SymbolNameContains(symbol_name, "ExecutorMspaceFree")) {
        return "mspace_free";
    }
    if (SymbolNameContains(symbol_name, "ExecutorMspaceMemalign")) {
        return "mspace_memalign";
    }
    if (SymbolNameContains(symbol_name, "ExecutorLibcMalloc")) {
        return "malloc";
    }
    if (SymbolNameContains(symbol_name, "ExecutorLibcMemalign")) {
        return "memalign";
    }
    if (SymbolNameContains(symbol_name, "ExecutorLibcCalloc")) {
        return "calloc";
    }
    if (SymbolNameContains(symbol_name, "ExecutorLibcRealloc")) {
        return "realloc";
    }
    if (SymbolNameContains(symbol_name, "ExecutorLibcFree")) {
        return "free";
    }
    if (SymbolNameContains(symbol_name, "ExecutorPngMalloc")) {
        return "png_malloc";
    }
    if (SymbolNameContains(symbol_name, "ExecutorPngCalloc")) {
        return "png_calloc";
    }
    if (SymbolNameContains(symbol_name, "ExecutorPngFree")) {
        return "png_free";
    }
    return nullptr;
}

std::uint64_t StoreAllocatorSizeHint(const char* kind, const std::uint64_t arg0,
                                     const std::uint64_t arg1, const std::uint64_t arg2) {
    if (kind == nullptr) {
        return 0;
    }
    if (std::strcmp(kind, "mspace_malloc") == 0 || std::strcmp(kind, "png_malloc") == 0) {
        return arg1;
    }
    if (std::strcmp(kind, "mspace_memalign") == 0) {
        return arg2;
    }
    if (std::strcmp(kind, "mspace_calloc") == 0 || std::strcmp(kind, "calloc") == 0) {
        const std::uint64_t count = std::strcmp(kind, "mspace_calloc") == 0 ? arg1 : arg0;
        const std::uint64_t size = std::strcmp(kind, "mspace_calloc") == 0 ? arg2 : arg1;
        return count > 0 && size > UINT64_MAX / count ? UINT64_MAX : count * size;
    }
    if (std::strcmp(kind, "mspace_realloc") == 0) {
        return arg2;
    }
    if (std::strcmp(kind, "malloc") == 0) {
        return arg0;
    }
    if (std::strcmp(kind, "memalign") == 0) {
        return arg1;
    }
    if (std::strcmp(kind, "realloc") == 0) {
        return arg1;
    }
    if (std::strcmp(kind, "png_calloc") == 0) {
        return arg1;
    }
    return 0;
}

bool IsStoreAllocatorSymbol(const char* symbol_name) {
    return StoreAllocatorKind(symbol_name) != nullptr;
}

enum class ExecutorHlePointerResultFamily : std::uint8_t {
    None,
    Allocator,
    Stdio,
    Directory,
    ProcessObject,
};

bool StoreAllocatorReturnsPointer(const char* kind) {
    return kind != nullptr && std::strcmp(kind, "free") != 0 &&
           std::strcmp(kind, "mspace_free") != 0 && std::strcmp(kind, "png_free") != 0;
}

bool HleNameIsAllocatorPointerProducer(const char* name) {
    const std::string_view value = name != nullptr ? std::string_view{name} : std::string_view{};
    if (value.empty() || value.find("free") != std::string_view::npos ||
        value.find("Free") != std::string_view::npos ||
        value.find("usable") != std::string_view::npos ||
        value.find("Usable") != std::string_view::npos ||
        value.find("Stats") != std::string_view::npos ||
        value.find("Create") != std::string_view::npos ||
        value.find("Destroy") != std::string_view::npos) {
        return false;
    }
    return value == "malloc" || value == "_malloc" || value == "_sceLibcMalloc" ||
           value == "calloc" || value == "_calloc" || value == "_sceLibcCalloc" ||
           value == "realloc" || value == "_realloc" || value == "_sceLibcRealloc" ||
           value == "reallocalign" || value == "internal_reallocalign" ||
           value == "memalign" || value == "_memalign" || value == "aligned_alloc" ||
           value == "strdup" || value == "png_malloc" || value == "png_calloc" ||
           value == "png_malloc_default" || value.starts_with("sceLibcMspaceMalloc") ||
           value.starts_with("sceLibcMspaceCalloc") ||
           value.starts_with("sceLibcMspaceRealloc") ||
           value.starts_with("sceLibcMspaceReallocalign") ||
           value.starts_with("sceLibcMspaceMemalign") ||
           value.starts_with("sceLibcMspaceAlignedAlloc") ||
           value.starts_with("sceLibcPafMspaceMalloc") ||
           value.starts_with("sceLibcPafMspaceCalloc") ||
           value.starts_with("sceLibcPafMspaceRealloc") ||
           value.starts_with("sceLibcPafMspaceMemalign") ||
           value.starts_with("coil_mspace_malloc") ||
           value.starts_with("coil_mspace_calloc") || value.starts_with("_Zn");
}

ExecutorHlePointerResultFamily ClassifyHlePointerResultFamily(const char* name,
                                                               const char* symbol_name,
                                                               const char* allocator_kind) {
    if (StoreAllocatorReturnsPointer(allocator_kind) ||
        SymbolNameContains(symbol_name, "ExecutorLibcStrdup") ||
        HleNameIsAllocatorPointerProducer(name)) {
        return ExecutorHlePointerResultFamily::Allocator;
    }
    const std::string_view hle_name = name != nullptr ? std::string_view{name} : std::string_view{};
    if (hle_name == "fopen" || hle_name == "xeYO4u7uyJ0" ||
        (SymbolNameContains(symbol_name, "ExecutorLibcFopen") &&
         !SymbolNameContains(symbol_name, "ExecutorLibcFopenS"))) {
        return ExecutorHlePointerResultFamily::Stdio;
    }
    if (!HleNameMatches(name, "readdir_r", "J0kng1yac3M") &&
        !SymbolNameContains(symbol_name, "ExecutorReaddirR") &&
        (HleNameMatches(name, "opendir", "ay3uROQAc5A") ||
         HleNameMatches(name, "__opendir2", "KOy7MeQ7OAU") ||
         HleNameMatches(name, "readdir", "lybyyKtP54c") ||
         SymbolNameContains(symbol_name, "ExecutorOpendir") ||
         SymbolNameContains(symbol_name, "ExecutorReaddir"))) {
        return ExecutorHlePointerResultFamily::Directory;
    }
    if (HleNameMatches(name, "getenv", "smbQukfxYJM") ||
        HleNameMatches(name, "__wrap_getenv", "5FdejCVZfZs") ||
        HleNameMatches(name, "g_getenv", "iHFQ4ROnqJ8") ||
        HleNameMatches(name, "monoeg_g_getenv", "n-IyBYJNbQ0") ||
        HleNameMatches(name, "__error", "9BcDykPmo1I") ||
        SymbolNameContains(symbol_name, "ExecutorLibcGetenv") ||
        SymbolNameContains(symbol_name, "ExecutorLibcError")) {
        return ExecutorHlePointerResultFamily::ProcessObject;
    }
    return ExecutorHlePointerResultFamily::None;
}

const char* HlePointerResultFamilyName(ExecutorHlePointerResultFamily family) {
    switch (family) {
    case ExecutorHlePointerResultFamily::Allocator:
        return "allocator";
    case ExecutorHlePointerResultFamily::Stdio:
        return "stdio";
    case ExecutorHlePointerResultFamily::Directory:
        return "directory";
    case ExecutorHlePointerResultFamily::ProcessObject:
        return "process-object";
    default:
        return "none";
    }
}

bool ExecutorEnvFlag(const char* name) {
    const char* value = std::getenv(name);
    return value != nullptr && value[0] != '\0' && std::strcmp(value, "0") != 0;
}

bool IsPthreadCondTimedWaitHleTarget(const char* name, const char* symbol_name) {
    const auto matches = [](const char* value) {
        return value != nullptr &&
               (std::strstr(value, "pthread_cond_timedwait") != nullptr ||
                std::strstr(value, "pthread_cond_reltimedwait") != nullptr ||
                std::strstr(value, "PthreadCondTimedwait") != nullptr ||
                std::strstr(value, "PthreadCondRelTimedwait") != nullptr);
    };
    return matches(name) || matches(symbol_name);
}

bool ExecutorConsumeLogBudget(std::atomic_int& budget) {
    int remaining = budget.load(std::memory_order_relaxed);
    while (remaining > 0) {
        if (budget.compare_exchange_weak(remaining, remaining - 1, std::memory_order_relaxed,
                                         std::memory_order_relaxed)) {
            return true;
        }
    }
    return false;
}

bool ExecutorShouldLogHleStackArgs(std::atomic_int& initial_budget) {
    static const bool verbose = ExecutorEnvFlag("EXECUTOR_TRACE_HLE_STACK_ARGS");
    return verbose || ExecutorConsumeLogBudget(initial_budget);
}

bool IsLiveTraceHleTarget(const char* name, const char* symbol_name) {
    const std::string_view n = name ? name : "";
    const std::string_view s = symbol_name ? symbol_name : "";
    const auto has = [&](const char* token) {
        return n.find(token) != std::string_view::npos ||
               s.find(token) != std::string_view::npos;
    };
    return has("sceGnm") || has("sceAgc") || has("sceVideoOut") || has("sceSysmodule") ||
           has("scePthread") || has("pthread") || has("sem_") || has("sceKernelWait") ||
           has("sceKernelSignal") || has("sceKernelCreateEqueue") ||
           has("sceKernelCreateEventFlag") || has("sceKernelPollEventFlag") ||
           has("sceKernelSetEventFlag") || has("sceKernelOpen") || has("sceKernelRead") ||
           has("sceKernelReadv") || has("sceKernelPread") || has("sceKernelPreadv") ||
           has("sceKernelLseek") || has("sceKernelStat") || has("sceKernelFstat") ||
           has("sceKernelClose") || has("sceKernelLoadStartModule") ||
           has("LoadStartModule") || has("scePad") || has("sceUserService");
}

bool IsBlockingSemWaitHleTarget(const char* name, const char* symbol_name) {
    return HleNameMatches(name, "sem_wait", "YCV5dGGBcCo") ||
           HleNameMatches(name, "scePthreadSemWait", "C36iRE0F5sE") ||
           SymbolNameContains(symbol_name, "posix_sem_wait") ||
           SymbolNameContains(symbol_name, "scePthreadSemWait");
}

bool IsPosixSemInitHleTarget(const char* name, const char* symbol_name) {
    return HleNameMatches(name, "sem_init", "pDuPEf3m4fI") ||
           HleNameMatches(name, "scePthreadSemInit", "GEnUkDZoUwY") ||
           SymbolNameContains(symbol_name, "posix_sem_init") ||
           SymbolNameContains(symbol_name, "scePthreadSemInit");
}

bool IsPosixSemPostHleTarget(const char* name, const char* symbol_name) {
    return HleNameMatches(name, "sem_post", "IKP8typ0QUk") ||
           HleNameMatches(name, "scePthreadSemPost", "aishVAiFaYM") ||
           SymbolNameContains(symbol_name, "posix_sem_post") ||
           SymbolNameContains(symbol_name, "scePthreadSemPost");
}

bool IsPosixSemTryWaitHleTarget(const char* name, const char* symbol_name) {
    return HleNameMatches(name, "sem_trywait", "WBWzsRifCEA") ||
           HleNameMatches(name, "scePthreadSemTrywait", "H2a+IN9TP0E") ||
           SymbolNameContains(symbol_name, "posix_sem_trywait") ||
           SymbolNameContains(symbol_name, "scePthreadSemTrywait");
}

bool IsPosixSemTimedWaitHleTarget(const char* name, const char* symbol_name) {
    return HleNameMatches(name, "sem_timedwait", "w5IHyvahg-o") ||
           HleNameMatches(name, "scePthreadSemTimedwait", "fjN6NQHhK8k") ||
           SymbolNameContains(symbol_name, "posix_sem_timedwait") ||
           SymbolNameContains(symbol_name, "scePthreadSemTimedwait");
}

const char* PosixSemSiteOpForHleTarget(const char* name, const char* symbol_name) {
    if (IsPosixSemInitHleTarget(name, symbol_name)) {
        return "init";
    }
    if (IsBlockingSemWaitHleTarget(name, symbol_name)) {
        return "wait";
    }
    if (IsPosixSemPostHleTarget(name, symbol_name)) {
        return "post";
    }
    if (IsPosixSemTryWaitHleTarget(name, symbol_name)) {
        return "trywait";
    }
    if (IsPosixSemTimedWaitHleTarget(name, symbol_name)) {
        return "timedwait";
    }
    return nullptr;
}

extern "C" void executor_live_record_posix_sem_hle_site(const char* op, void* sem_addr,
                                                        std::uint64_t guest_return,
                                                        std::uint64_t module_offset,
                                                        const char* module_name)
    __attribute__((weak));

void RecordPosixSemHleSite(const char* op, const std::uint64_t sem_addr,
                           const std::uint64_t guest_rsp) {
    static const bool enabled =
        ExecutorEnvFlag("EXECUTOR_TRACE_LIVE_WIDE") ||
        ExecutorEnvFlag("EXECUTOR_TRACE_LIVE_SYNC") ||
        ExecutorEnvFlag("EXECUTOR_SYNC_FRONTIER") ||
        ExecutorEnvFlag("EXECUTOR_LIVE_HLE_FLIGHT") || ExecutorLightOracleMode();
    if (!enabled || op == nullptr || executor_live_record_posix_sem_hle_site == nullptr) {
        return;
    }

    const std::uint64_t guest_return = GuestReturnAddress(guest_rsp);
    Core::Module* module = FindGuestModuleByAddress(guest_return);
    executor_live_record_posix_sem_hle_site(
        op, reinterpret_cast<void*>(sem_addr), guest_return,
        module ? GuestModuleOffset(*module, guest_return) : 0,
        module ? module->file.string().c_str() : "<unknown>");
}

bool IsLibcCompareHleTarget(const char* name, const char* symbol_name) {
    return HleNameMatches(name, "strcmp", "Ovb2dSJOAuE") ||
           HleNameMatches(name, "strncmp", "aesyjrHVWy4") ||
           HleNameMatches(name, "memcmp", "DfivPArhucg") ||
           SymbolNameContains(symbol_name, "ExecutorLibcStrcmp") ||
           SymbolNameContains(symbol_name, "ExecutorLibcStrncmp") ||
           SymbolNameContains(symbol_name, "ExecutorLibcMemcmp");
}

void RecordLibcCompareBadPtr(const char* name, const char* symbol_name,
                             const std::uint64_t native_function,
                             const std::uint64_t arg0, const std::uint64_t arg1,
                             const std::uint64_t arg2, const std::uint64_t arg3,
                             const std::uint64_t arg4, const std::uint64_t arg5,
                              const std::uint64_t guest_rsp,
                              const bool is_libc_compare_target) {
    static const bool enabled = ExecutorEnvFlag("EXECUTOR_TRACE_LIBC_COMPARE_BADPTR") ||
                                ExecutorEnvFlag("EXECUTOR_TRACE_LIBC_STRCMP_STRINGS");
    if (!enabled || !is_libc_compare_target) {
        return;
    }

    auto* memory = Core::Memory::TryInstance();
    const auto mapped_or_memory_readable = [&](std::uint64_t address) {
        return IsCurrentMappedEntryReadableAddressLocked(address) ||
               (memory != nullptr && memory->IsValidMapping(address, 1));
    };
    const bool lhs_readable = mapped_or_memory_readable(arg0);
    const bool rhs_readable = mapped_or_memory_readable(arg1);
    if (lhs_readable && rhs_readable) {
        return;
    }

    const std::uint64_t guest_return = GuestReturnAddress(guest_rsp);
    ExecutorConformanceNoteBadPtr(arg0, arg1, guest_return);

    static std::atomic_int log_budget{256};
    if (log_budget.fetch_sub(1, std::memory_order_relaxed) <= 0) {
        return;
    }

    Core::Module* module = FindGuestModuleByAddress(guest_return);
    const std::uint64_t module_offset = module ? GuestModuleOffset(*module, guest_return) : 0;
    std::string lhs_preview;
    std::string rhs_preview;
    std::string lhs_bytes;
    std::string rhs_bytes;
    std::string arg3_preview;
    std::string arg4_preview;
    std::string arg5_preview;
    std::string arg3_bytes;
    std::string arg4_bytes;
    std::string arg5_bytes;
    std::string stack_bytes;
    std::string ret_context;
    ExecutorBox64GuestRegsSnapshot guest_regs{};
    const int guest_regs_rc = TryGetCurrentGuestRegsSnapshot(guest_regs);
    const std::uint64_t lhs_mspace_candidate =
        ExecutorConformanceBadPtrIsLow(arg0) ? (0x200000000ull | arg0) : 0;
    const std::uint64_t rhs_mspace_candidate =
        ExecutorConformanceBadPtrIsLow(arg1) ? (0x200000000ull | arg1) : 0;
    std::string lhs_mspace_preview;
    std::string rhs_mspace_preview;
    std::string guest_rdi_preview;
    std::string guest_rsi_preview;
    bool lhs_mspace_readable = false;
    bool rhs_mspace_readable = false;
    {
        std::lock_guard lock(g_box64_boundary_probe_lock);
        lhs_preview = GuestCStringPreviewLocked(arg0, 192);
        rhs_preview = GuestCStringPreviewLocked(arg1, 192);
        lhs_bytes = GuestBytesHexCheckedLocked(arg0, 32);
        rhs_bytes = GuestBytesHexCheckedLocked(arg1, 32);
        arg3_preview = GuestCStringPreviewLocked(arg3, 192);
        arg4_preview = GuestCStringPreviewLocked(arg4, 192);
        arg5_preview = GuestCStringPreviewLocked(arg5, 192);
        arg3_bytes = GuestBytesHexCheckedLocked(arg3, 96);
        arg4_bytes = GuestBytesHexCheckedLocked(arg4, 96);
        arg5_bytes = GuestBytesHexCheckedLocked(arg5, 96);
        stack_bytes = GuestBytesHexCheckedLocked(guest_rsp, 96);
        const std::uint64_t context = guest_return >= 64 ? guest_return - 64 : guest_return;
        ret_context = GuestBytesHexCheckedLocked(context, 160);
        if (lhs_mspace_candidate != 0) {
            lhs_mspace_preview = GuestCStringPreviewLocked(lhs_mspace_candidate, 128);
            lhs_mspace_readable = !GuestBytesHexCheckedLocked(lhs_mspace_candidate, 1).empty();
        }
        if (rhs_mspace_candidate != 0) {
            rhs_mspace_preview = GuestCStringPreviewLocked(rhs_mspace_candidate, 128);
            rhs_mspace_readable = !GuestBytesHexCheckedLocked(rhs_mspace_candidate, 1).empty();
        }
        if (guest_regs_rc == 0) {
            guest_rdi_preview = GuestCStringPreviewLocked(guest_regs.regs[7], 128);
            guest_rsi_preview = GuestCStringPreviewLocked(guest_regs.regs[6], 128);
        }
    }

    static std::atomic_int origin_budget{128};
    if (origin_budget.fetch_sub(1, std::memory_order_relaxed) > 0) {
        NativeLog(ANDROID_LOG_WARN,
                  "[EXECUTOR_LIBC_BADPTR_ORIGIN] name=%s symbol=%s ret=%p returnOff=0x%llx "
                  "module=%s hleArgs=%p,%p,%p,%p,%p,%p guestRegsRc=%d "
                  "rax=%p rcx=%p rdx=%p rbx=%p rsp=%p rbp=%p rsi=%p rdi=%p "
                  "r8=%p r9=%p r10=%p r11=%p r12=%p r13=%p r14=%p r15=%p rip=%p "
                  "rdiMatchesArg0=%d rsiMatchesArg1=%d "
                  "lhsMspace=%p lhsMspaceReadable=%d lhsMspaceStr=\"%s\" "
                  "rhsMspace=%p rhsMspaceReadable=%d rhsMspaceStr=\"%s\" "
                  "guestRdiStr=\"%s\" guestRsiStr=\"%s\"",
                  name && name[0] ? name : "<unknown>",
                  symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
                  reinterpret_cast<void*>(guest_return),
                  static_cast<unsigned long long>(module_offset),
                  module ? module->file.string().c_str() : "<unknown>",
                  reinterpret_cast<void*>(arg0), reinterpret_cast<void*>(arg1),
                  reinterpret_cast<void*>(arg2), reinterpret_cast<void*>(arg3),
                  reinterpret_cast<void*>(arg4), reinterpret_cast<void*>(arg5),
                  guest_regs_rc,
                  reinterpret_cast<void*>(guest_regs.regs[0]),
                  reinterpret_cast<void*>(guest_regs.regs[1]),
                  reinterpret_cast<void*>(guest_regs.regs[2]),
                  reinterpret_cast<void*>(guest_regs.regs[3]),
                  reinterpret_cast<void*>(guest_regs.regs[4]),
                  reinterpret_cast<void*>(guest_regs.regs[5]),
                  reinterpret_cast<void*>(guest_regs.regs[6]),
                  reinterpret_cast<void*>(guest_regs.regs[7]),
                  reinterpret_cast<void*>(guest_regs.regs[8]),
                  reinterpret_cast<void*>(guest_regs.regs[9]),
                  reinterpret_cast<void*>(guest_regs.regs[10]),
                  reinterpret_cast<void*>(guest_regs.regs[11]),
                  reinterpret_cast<void*>(guest_regs.regs[12]),
                  reinterpret_cast<void*>(guest_regs.regs[13]),
                  reinterpret_cast<void*>(guest_regs.regs[14]),
                  reinterpret_cast<void*>(guest_regs.regs[15]),
                  reinterpret_cast<void*>(guest_regs.rip),
                  guest_regs_rc == 0 && guest_regs.regs[7] == arg0 ? 1 : 0,
                  guest_regs_rc == 0 && guest_regs.regs[6] == arg1 ? 1 : 0,
                  reinterpret_cast<void*>(lhs_mspace_candidate), lhs_mspace_readable ? 1 : 0,
                  lhs_mspace_preview.c_str(), reinterpret_cast<void*>(rhs_mspace_candidate),
                  rhs_mspace_readable ? 1 : 0, rhs_mspace_preview.c_str(),
                  guest_rdi_preview.c_str(), guest_rsi_preview.c_str());
    }

    NativeLog(ANDROID_LOG_WARN,
              "[EXECUTOR_LIBC_COMPARE_BADPTR] name=%s symbol=%s native=%p "
              "ret=%p returnOff=0x%llx module=%s lhs=%p rhs=%p size=%p "
              "lhsReadable=%d rhsReadable=%d lhsStr=\"%s\" rhsStr=\"%s\" "
              "lhsBytes=%s rhsBytes=%s lhsLo32=0x%08llx lhsHi32=0x%08llx "
              "args=%p,%p,%p,%p,%p,%p arg3Str=\"%s\" arg4Str=\"%s\" arg5Str=\"%s\" "
              "arg3Bytes=%s arg4Bytes=%s arg5Bytes=%s rsp=%p stack=%s retCtx=%s",
              name && name[0] ? name : "<unknown>",
              symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
              reinterpret_cast<void*>(native_function), reinterpret_cast<void*>(guest_return),
              static_cast<unsigned long long>(module_offset),
              module ? module->file.string().c_str() : "<unknown>",
              reinterpret_cast<void*>(arg0), reinterpret_cast<void*>(arg1),
              reinterpret_cast<void*>(arg2), lhs_readable ? 1 : 0, rhs_readable ? 1 : 0,
              lhs_preview.c_str(), rhs_preview.c_str(), lhs_bytes.c_str(), rhs_bytes.c_str(),
              static_cast<unsigned long long>(arg0 & 0xffffffffULL),
              static_cast<unsigned long long>((arg0 >> 32) & 0xffffffffULL),
              reinterpret_cast<void*>(arg0), reinterpret_cast<void*>(arg1),
              reinterpret_cast<void*>(arg2), reinterpret_cast<void*>(arg3),
              reinterpret_cast<void*>(arg4), reinterpret_cast<void*>(arg5),
              arg3_preview.c_str(), arg4_preview.c_str(), arg5_preview.c_str(),
              arg3_bytes.empty() ? "<unreadable>" : arg3_bytes.c_str(),
              arg4_bytes.empty() ? "<unreadable>" : arg4_bytes.c_str(),
              arg5_bytes.empty() ? "<unreadable>" : arg5_bytes.c_str(),
              reinterpret_cast<void*>(guest_rsp), stack_bytes.c_str(),
              ret_context.empty() ? "<unreadable>" : ret_context.c_str());
}

void RecordLiveHleCallsite(const char* name, const char* symbol_name,
                           HleMachineWord native_function, HleMachineWord arg0,
                           HleMachineWord arg1, HleMachineWord arg2,
                           HleMachineWord arg3, HleMachineWord arg4,
                           HleMachineWord arg5, HleMachineWord guest_rsp,
                           const bool is_live_trace_target) {
    static const bool enabled = ExecutorEnvFlag("EXECUTOR_TRACE_LIVE_WIDE") ||
                                ExecutorEnvFlag("EXECUTOR_TRACE_LIVE_HLE");
    if (!enabled) {
        return;
    }
    if (!is_live_trace_target) {
        return;
    }
    const std::uint64_t guest_return = GuestReturnAddress(guest_rsp);
    Core::Module* module = FindGuestModuleByAddress(guest_return);
    const std::string module_path = module ? module->file.string() : "";
    const std::uint64_t module_offset = module ? GuestModuleOffset(*module, guest_return) : 0;
    const bool is_eboot =
        module_path.find("eboot.bin") != std::string::npos ||
        module_path.find("PS4Player") != std::string::npos;
    static std::atomic_uint64_t sequence{0};
    const std::uint64_t seq = sequence.fetch_add(1, std::memory_order_relaxed);
    const bool gate_critical =
        (name && (std::strstr(name, "sceGnm") || std::strstr(name, "sceAgc"))) ||
        (symbol_name && (std::strstr(symbol_name, "sceGnm") ||
                         std::strstr(symbol_name, "sceAgc")));
    const bool sampled = seq < 12000 || (seq != 0 && (seq & (seq - 1)) == 0);


    static const bool verbose_hle_callsite =
        std::getenv("EXECUTOR_VERBOSE_HLE_CALLSITE") != nullptr;
    if (ExecutorLightOracleMode() && !gate_critical && !verbose_hle_callsite) {
        return;
    }
    const bool verbose_hle = verbose_hle_callsite;
    if ((gate_critical && (verbose_hle || seq < 12000)) || sampled) {
        NativeLog(
            ANDROID_LOG_INFO,
            "[EXECUTOR_LIVE_HLE_CALLSITE] name=%s symbol=%s native=%p ret=%p returnOff=0x%llx "
            "moduleKind=%s module=%s args=%p,%p,%p,%p,%p,%p rsp=%p",
            name && name[0] ? name : "<unknown>",
            symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
            reinterpret_cast<void*>(native_function), reinterpret_cast<void*>(guest_return),
            static_cast<unsigned long long>(module_offset), is_eboot ? "eboot" : "other",
            module_path.empty() ? "<unknown>" : module_path.c_str(),
            reinterpret_cast<void*>(arg0), reinterpret_cast<void*>(arg1),
            reinterpret_cast<void*>(arg2), reinterpret_cast<void*>(arg3),
            reinterpret_cast<void*>(arg4), reinterpret_cast<void*>(arg5),
            reinterpret_cast<void*>(guest_rsp));
    }
}

struct ExecutorLiveHleFlightEntry {
    std::uint64_t seq{};
    std::uint64_t native_function{};
    std::uint64_t guest_return{};
    std::uint64_t return_off{};
    std::uint64_t result{};
    std::uint64_t args[6]{};
    std::uint64_t rsp{};
    std::uint32_t tid{};
    char thread[32]{};
    char phase[8]{};
    char name[96]{};
    char symbol[128]{};
    char module[96]{};
};

std::mutex g_live_hle_flight_lock;
std::array<ExecutorLiveHleFlightEntry, 1024> g_live_hle_flight{};
std::unordered_map<std::uint32_t, ExecutorLiveHleFlightEntry> g_live_hle_inflight;
std::atomic<std::uint64_t> g_live_hle_flight_seq{0};

struct ExecutorCurrentHleContext {
    std::uint64_t guest_rsp = 0;
    std::uint64_t guest_return = 0;
    bool guest_return_resolved = false;
    std::array<std::uint64_t, 8> floating_arguments{};
    const char* name = nullptr;
    const char* symbol = nullptr;
};

thread_local ExecutorCurrentHleContext g_executor_current_hle_context{};

struct ScopedExecutorCurrentHleContext {
    ExecutorCurrentHleContext previous{};

    ScopedExecutorCurrentHleContext(
        const std::uint64_t guest_rsp, const char* name, const char* symbol,
        const std::array<std::uint64_t, 8>& floating_arguments)
        : previous(g_executor_current_hle_context) {
        g_executor_current_hle_context = {
            .guest_rsp = guest_rsp,





            .guest_return = 0,
            .guest_return_resolved = false,
            .floating_arguments = floating_arguments,
            .name = name,
            .symbol = symbol,
        };
    }

    ~ScopedExecutorCurrentHleContext() {
        g_executor_current_hle_context = previous;
    }
};

std::string ExecutorBasenameForFlight(const std::string& path) {
    if (path.empty()) {
        return {};
    }
    std::error_code ec;
    const auto base = std::filesystem::path(path).filename().string();
    if (!base.empty()) {
        return base;
    }
    return path;
}

bool ExecutorLightOracleKeepsHleFlightTarget(const char* name, const char* symbol_name) {
    const std::string_view n = name ? name : "";
    const std::string_view s = symbol_name ? symbol_name : "";
    const auto has = [&](const char* token) {
        return n.find(token) != std::string_view::npos ||
               s.find(token) != std::string_view::npos;
    };
    if (IsPthreadHleTarget(name, symbol_name) || IsBlockingSemWaitHleTarget(name, symbol_name) ||
        IsPosixSemInitHleTarget(name, symbol_name) ||
        IsPosixSemPostHleTarget(name, symbol_name) ||
        IsPosixSemTryWaitHleTarget(name, symbol_name) ||
        IsPosixSemTimedWaitHleTarget(name, symbol_name)) {
        return true;
    }

    return has("sceGnm") || has("sceAgc") || has("sceVideoOut") || has("sceSysmodule") ||
           has("scePthread") || has("pthread") || has("sem_") || has("sceKernelWait") ||
           has("sceKernelSignal") || has("sceKernelCreateEqueue") ||
           has("sceKernelCreateEventFlag") || has("sceKernelPollEventFlag") ||
           has("sceKernelSetEventFlag") || has("sceKernelOpen") || has("sceKernelRead") ||
           has("sceKernelReadv") || has("sceKernelPread") || has("sceKernelPreadv") ||
           has("sceKernelLseek") || has("sceKernelStat") || has("sceKernelFstat") ||
           has("sceKernelMmap") || has("sceKernelMunmap") || has("sceKernelClose") ||
           has("sceKernelLoadStartModule") || has("LoadStartModule") ||
           has("scePad") || has("sceUserService") || has("sceSystemService") ||
           has("sceSaveData") || has("Fios") || has("File") || has("abort") ||
           has("stack_chk") || has("sceKernelDebugOutText");
}

void ExecutorPersistUnityPreloadHleFlight(const ExecutorLiveHleFlightEntry& entry) {
    if (!ExecutorEnvFlag("EXECUTOR_LIVE_HLE_FLIGHT") &&
        !ExecutorEnvFlag("EXECUTOR_TRACE_LIVE_HLE") &&
        !ExecutorEnvFlag("EXECUTOR_TRACE_LIVE_WIDE")) {
        return;
    }
    if (g_root.empty()) {
        return;
    }

    static std::mutex log_lock;
    std::lock_guard lock(log_lock);
    try {
        const auto dir = std::filesystem::path(g_root) / "translator";
        std::filesystem::create_directories(dir);
        const auto path = dir / "unitypreload-hle-flight.log";
        static bool reset = false;
        if (!reset) {
            std::error_code ec;
            std::filesystem::remove(path, ec);
            reset = true;
        }

        const bool unity_preload = std::strstr(entry.thread, "UnityPreload") != nullptr;
        const bool title_main = std::strstr(entry.thread, "main") != nullptr ||
                                std::strstr(entry.thread, "Main") != nullptr ||
                                std::strstr(entry.thread, "Spelunky") != nullptr;
        if (!unity_preload && !title_main) {
            return;
        }

        static std::atomic_int budget{32768};
        if (budget.fetch_sub(1, std::memory_order_relaxed) <= 0) {
            return;
        }

        std::ofstream out(path, std::ios::app);
        if (!out) {
            return;
        }
        out << "seq=" << entry.seq << " phase=" << entry.phase << " tid=" << entry.tid
            << " thread=\"" << (entry.thread[0] ? entry.thread : "<unnamed>") << "\""
            << " name=" << entry.name << " symbol=" << entry.symbol
            << " result=0x" << std::hex << entry.result
            << " ret=0x" << entry.guest_return << " off=0x" << entry.return_off
            << " module=" << entry.module
            << " args=0x" << entry.args[0] << ",0x" << entry.args[1] << ",0x"
            << entry.args[2] << ",0x" << entry.args[3] << ",0x" << entry.args[4]
            << ",0x" << entry.args[5] << " rsp=0x" << entry.rsp
            << " native=0x" << entry.native_function << std::dec << '\n';
    } catch (...) {
    }
}

void ExecutorLiveHleFlightRecord(const char* phase, const char* name, const char* symbol_name,
                                 const std::uint64_t native_function, const std::uint64_t result,
                                 const std::uint64_t arg0, const std::uint64_t arg1,
                                 const std::uint64_t arg2, const std::uint64_t arg3,
                                 const std::uint64_t arg4, const std::uint64_t arg5,
                                 const std::uint64_t guest_rsp,
                                 const int preclassified_light_oracle_target = -1) {
    struct FlightConfig {
        bool light_oracle;
        bool explicit_flight;
        bool trace_hle;
        bool trace_wide;
    };
    static const FlightConfig config{
        ExecutorLightOracleMode(), ExecutorEnvFlag("EXECUTOR_LIVE_HLE_FLIGHT"),
        ExecutorEnvFlag("EXECUTOR_TRACE_LIVE_HLE"),
        ExecutorEnvFlag("EXECUTOR_TRACE_LIVE_WIDE")};
    if (!config.light_oracle && !config.explicit_flight && !config.trace_hle &&
        !config.trace_wide) {
        return;
    }
    if (config.light_oracle && !config.explicit_flight && !config.trace_hle &&
        !config.trace_wide &&
        !(preclassified_light_oracle_target >= 0
              ? preclassified_light_oracle_target != 0
              : ExecutorLightOracleKeepsHleFlightTarget(name, symbol_name))) {
        return;
    }
    const auto seq = g_live_hle_flight_seq.fetch_add(1, std::memory_order_relaxed) + 1;
    ExecutorLiveHleFlightEntry entry{};
    entry.seq = seq;
    entry.native_function = native_function;
    entry.result = result;
    entry.args[0] = arg0;
    entry.args[1] = arg1;
    entry.args[2] = arg2;
    entry.args[3] = arg3;
    entry.args[4] = arg4;
    entry.args[5] = arg5;
    entry.rsp = guest_rsp;
    entry.tid = static_cast<std::uint32_t>(syscall(SYS_gettid));
    pthread_getname_np(pthread_self(), entry.thread, sizeof(entry.thread));
    std::snprintf(entry.phase, sizeof(entry.phase), "%s", phase ? phase : "?");
    std::snprintf(entry.name, sizeof(entry.name), "%s", name && name[0] ? name : "<unknown>");
    std::snprintf(entry.symbol, sizeof(entry.symbol), "%s",
                  symbol_name && symbol_name[0] ? symbol_name : "<unknown>");

    entry.guest_return = GuestReturnAddress(guest_rsp);
    if (Core::Module* module = FindGuestModuleByAddress(entry.guest_return)) {
        entry.return_off = GuestModuleOffset(*module, entry.guest_return);
        const auto module_base = ExecutorBasenameForFlight(module->file.string());
        std::snprintf(entry.module, sizeof(entry.module), "%s", module_base.c_str());
    } else {
        std::snprintf(entry.module, sizeof(entry.module), "%s", "<unknown>");
    }

    ExecutorPersistUnityPreloadHleFlight(entry);

    std::lock_guard lock(g_live_hle_flight_lock);
    g_live_hle_flight[seq % g_live_hle_flight.size()] = entry;
    if (std::strcmp(entry.phase, "call") == 0) {
        g_live_hle_inflight[entry.tid] = entry;
    } else if (std::strcmp(entry.phase, "ret") == 0) {
        g_live_hle_inflight.erase(entry.tid);
    }
}

extern "C" void executor_live_hle_flight_record_external(
    const char* phase, const char* name, const char* symbol_name,
    const std::uint64_t native_function, const std::uint64_t result,
    const std::uint64_t arg0, const std::uint64_t arg1, const std::uint64_t arg2,
    const std::uint64_t arg3, const std::uint64_t arg4, const std::uint64_t arg5,
    const std::uint64_t guest_rsp) {
    ExecutorLiveHleFlightRecord(phase, name, symbol_name, native_function, result, arg0, arg1,
                                arg2, arg3, arg4, arg5, guest_rsp);
}

extern "C" void executor_live_hle_flight_dump(const char* reason, std::uint64_t builder_total,
                                              std::uint64_t builder_draw,
                                              std::uint64_t builder_shader,
                                              std::uint64_t active_cb,
                                              std::uint64_t active_dw) {
    const auto last_seq = g_live_hle_flight_seq.load(std::memory_order_relaxed);
    NativeLog(ANDROID_LOG_WARN,
              "[EXECUTOR_LIVE_HLE_FLIGHT_DUMP] reason=%s lastSeq=%llu builderTotal=%llu "
              "builderDraw=%llu builderShader=%llu activeCb=%p activeDw=%llu",
              reason && reason[0] ? reason : "<unknown>",
              static_cast<unsigned long long>(last_seq),
              static_cast<unsigned long long>(builder_total),
              static_cast<unsigned long long>(builder_draw),
              static_cast<unsigned long long>(builder_shader), reinterpret_cast<void*>(active_cb),
              static_cast<unsigned long long>(active_dw));

    std::array<ExecutorLiveHleFlightEntry, 384> snapshot{};
    std::array<ExecutorLiveHleFlightEntry, 64> inflight{};
    std::size_t count = 0;
    std::size_t inflight_count = 0;
    {
        std::lock_guard lock(g_live_hle_flight_lock);
        for (const auto& [tid, entry] : g_live_hle_inflight) {
            (void)tid;
            if (inflight_count < inflight.size()) {
                inflight[inflight_count++] = entry;
            }
        }
        const auto first = last_seq > snapshot.size() ? last_seq - snapshot.size() + 1 : 1;
        for (auto seq = first; seq <= last_seq && count < snapshot.size(); ++seq) {
            const auto& entry = g_live_hle_flight[seq % g_live_hle_flight.size()];
            if (entry.seq == seq) {
                snapshot[count++] = entry;
            }
        }
    }

    for (std::size_t i = 0; i < inflight_count; ++i) {
        const auto& e = inflight[i];
        NativeLog(ANDROID_LOG_WARN,
                  "[EXECUTOR_LIVE_HLE_INFLIGHT] seq=%llu phase=%s tid=%u thread=\"%s\" "
                  "name=%s symbol=%s result=%p ret=%p off=0x%llx module=%s "
                  "args=%p,%p,%p,%p,%p,%p rsp=%p native=%p",
                  static_cast<unsigned long long>(e.seq), e.phase, e.tid,
                  e.thread[0] ? e.thread : "<unnamed>", e.name, e.symbol,
                  reinterpret_cast<void*>(e.result), reinterpret_cast<void*>(e.guest_return),
                  static_cast<unsigned long long>(e.return_off), e.module,
                  reinterpret_cast<void*>(e.args[0]), reinterpret_cast<void*>(e.args[1]),
                  reinterpret_cast<void*>(e.args[2]), reinterpret_cast<void*>(e.args[3]),
                  reinterpret_cast<void*>(e.args[4]), reinterpret_cast<void*>(e.args[5]),
                  reinterpret_cast<void*>(e.rsp), reinterpret_cast<void*>(e.native_function));
    }

    for (std::size_t i = 0; i < count; ++i) {
        const auto& e = snapshot[i];
        NativeLog(ANDROID_LOG_WARN,
                  "[EXECUTOR_LIVE_HLE_FLIGHT] seq=%llu phase=%s tid=%u thread=\"%s\" "
                  "name=%s symbol=%s result=%p ret=%p off=0x%llx module=%s "
                  "args=%p,%p,%p,%p,%p,%p rsp=%p native=%p",
                  static_cast<unsigned long long>(e.seq), e.phase, e.tid,
                  e.thread[0] ? e.thread : "<unnamed>", e.name, e.symbol,
                  reinterpret_cast<void*>(e.result), reinterpret_cast<void*>(e.guest_return),
                  static_cast<unsigned long long>(e.return_off), e.module,
                  reinterpret_cast<void*>(e.args[0]), reinterpret_cast<void*>(e.args[1]),
                  reinterpret_cast<void*>(e.args[2]), reinterpret_cast<void*>(e.args[3]),
                  reinterpret_cast<void*>(e.args[4]), reinterpret_cast<void*>(e.args[5]),
                  reinterpret_cast<void*>(e.rsp), reinterpret_cast<void*>(e.native_function));
    }
}

extern "C" int executor_live_get_current_hle_call_site(std::uint64_t* guest_return,
                                                       std::uint64_t* return_off,
                                                       std::uint64_t* arg0,
                                                       char* symbol,
                                                       std::size_t symbol_size,
                                                       char* module,
                                                       std::size_t module_size) {
    if (g_executor_current_hle_context.guest_rsp != 0) {
        if (guest_return != nullptr) {
            if (!g_executor_current_hle_context.guest_return_resolved) {
                g_executor_current_hle_context.guest_return = GuestReturnAddress(
                    g_executor_current_hle_context.guest_rsp);
                g_executor_current_hle_context.guest_return_resolved = true;
            }
            *guest_return = g_executor_current_hle_context.guest_return;
        }
        if (return_off != nullptr) {
            *return_off = 0;
        }
        if (arg0 != nullptr) {
            *arg0 = 0;
        }
        if (symbol != nullptr && symbol_size != 0) {
            std::snprintf(symbol, symbol_size, "%s",
                          g_executor_current_hle_context.symbol
                              ? g_executor_current_hle_context.symbol
                              : "<unknown>");
        }
        if (module != nullptr && module_size != 0) {
            std::snprintf(module, module_size, "%s", "<current-hle-boundary>");
        }
        return 0;
    }
    const auto tid = static_cast<std::uint32_t>(syscall(SYS_gettid));
    std::lock_guard lock(g_live_hle_flight_lock);
    if (const auto it = g_live_hle_inflight.find(tid); it != g_live_hle_inflight.end()) {
        const auto& entry = it->second;
        if (guest_return != nullptr) {
            *guest_return = entry.guest_return;
        }
        if (return_off != nullptr) {
            *return_off = entry.return_off;
        }
        if (arg0 != nullptr) {
            *arg0 = entry.args[0];
        }
        if (symbol != nullptr && symbol_size != 0) {
            std::snprintf(symbol, symbol_size, "%s", entry.symbol);
        }
        if (module != nullptr && module_size != 0) {
            std::snprintf(module, module_size, "%s", entry.module);
        }
        return 0;
    }
    const auto last_seq = g_live_hle_flight_seq.load(std::memory_order_relaxed);
    const auto first = last_seq > g_live_hle_flight.size() ? last_seq - g_live_hle_flight.size() + 1
                                                           : 1;
    for (auto seq = last_seq; seq >= first && seq != 0; --seq) {
        const auto& entry = g_live_hle_flight[seq % g_live_hle_flight.size()];
        if (entry.seq != seq || entry.tid != tid || std::strcmp(entry.phase, "call") != 0) {
            continue;
        }
        if (guest_return != nullptr) {
            *guest_return = entry.guest_return;
        }
        if (return_off != nullptr) {
            *return_off = entry.return_off;
        }
        if (arg0 != nullptr) {
            *arg0 = entry.args[0];
        }
        if (symbol != nullptr && symbol_size != 0) {
            std::snprintf(symbol, symbol_size, "%s", entry.symbol);
        }
        if (module != nullptr && module_size != 0) {
            std::snprintf(module, module_size, "%s", entry.module);
        }
        return 0;
    }
    return -1;
}

extern "C" int executor_live_get_current_hle_guest_rsp(std::uint64_t* guest_rsp) {
    if (guest_rsp == nullptr) {
        return -1;
    }
    if (g_executor_current_hle_context.guest_rsp != 0) {
        *guest_rsp = g_executor_current_hle_context.guest_rsp;
        return 0;
    }
    const auto tid = static_cast<std::uint32_t>(syscall(SYS_gettid));
    std::lock_guard lock(g_live_hle_flight_lock);
    if (const auto it = g_live_hle_inflight.find(tid); it != g_live_hle_inflight.end()) {
        *guest_rsp = it->second.rsp;
        return it->second.rsp != 0 ? 0 : -1;
    }
    const auto last_seq = g_live_hle_flight_seq.load(std::memory_order_relaxed);
    const auto first = last_seq > g_live_hle_flight.size() ? last_seq - g_live_hle_flight.size() + 1
                                                           : 1;
    for (auto seq = last_seq; seq >= first && seq != 0; --seq) {
        const auto& entry = g_live_hle_flight[seq % g_live_hle_flight.size()];
        if (entry.seq != seq || entry.tid != tid || std::strcmp(entry.phase, "call") != 0) {
            continue;
        }
        *guest_rsp = entry.rsp;
        return entry.rsp != 0 ? 0 : -1;
    }
    return -1;
}

extern "C" int executor_live_get_current_hle_floating_arguments(
    std::uint64_t* values, const std::size_t capacity) {
    if (values == nullptr || capacity == 0 ||
        g_executor_current_hle_context.guest_rsp == 0) {
        return -1;
    }
    const std::size_t count =
        std::min(capacity, g_executor_current_hle_context.floating_arguments.size());
    std::copy_n(g_executor_current_hle_context.floating_arguments.begin(), count, values);
    if (capacity > count) {
        std::fill(values + count, values + capacity, 0);
    }
    return static_cast<int>(count);
}

extern "C" void executor_live_log_fiber_transition(
    const char* operation, const char* phase, const std::int32_t result,
    const void* subject, const void* current_fiber, const void* tcb_fiber,
    const std::uint64_t guest_rip, const std::uint64_t guest_rsp,
    const std::uint64_t guest_return) {
    if (operation != nullptr && std::strcmp(operation, "GetSelf") == 0) {
        return;
    }

    static std::atomic_int budget{16384};
    if (budget.fetch_sub(1, std::memory_order_relaxed) <= 0) {
        return;
    }
    const auto tid = static_cast<std::uint32_t>(syscall(SYS_gettid));
    NativeLog(
        ANDROID_LOG_INFO,
        "[EXECUTOR_FIBER_TRANSITION] tid=%u op=%s phase=%s result=0x%08x subject=%p "
        "current=%p tcbFiber=%p guestRip=%p guestRsp=%p guestReturn=%p",
        tid, operation ? operation : "<unknown>", phase ? phase : "<unknown>",
        static_cast<std::uint32_t>(result), subject, current_fiber, tcb_fiber,
        reinterpret_cast<void*>(guest_rip), reinterpret_cast<void*>(guest_rsp),
        reinterpret_cast<void*>(guest_return));

    static std::mutex trace_mutex;
    std::lock_guard trace_lock{trace_mutex};
    if (std::FILE* trace = std::fopen(
            "/data/data/app.lsx4.android/files/lsx4-home/fiber-transitions.txt", "a");
        trace != nullptr) {
        std::fprintf(
            trace,
            "tid=%u op=%s phase=%s result=0x%08x subject=%p current=%p tcbFiber=%p "
            "guestRip=0x%llx guestRsp=0x%llx guestReturn=0x%llx\n",
            tid, operation ? operation : "<unknown>", phase ? phase : "<unknown>",
            static_cast<std::uint32_t>(result), subject, current_fiber, tcb_fiber,
            static_cast<unsigned long long>(guest_rip),
            static_cast<unsigned long long>(guest_rsp),
            static_cast<unsigned long long>(guest_return));
        if (result != 0) {
            std::uint64_t guest_rbp = 0;
            if (const auto machine = Lsx4::Translation::PublishedLiveState(); machine) {
                guest_rbp = machine.Read(Lsx4::Translation::IntegerRegister::Frame);
            }
            std::fprintf(trace, "  failureStack rbp=0x%llx",
                         static_cast<unsigned long long>(guest_rbp));
            std::lock_guard probe_lock{g_box64_boundary_probe_lock};
            for (std::uint64_t offset = 0; offset != 0x100; offset += sizeof(std::uint64_t)) {
                std::uint64_t value = 0;
                const bool readable =
                    GuestReadQwordCheckedLocked(guest_rsp + offset, value);
                std::fprintf(trace, " sp%+03llx=%s0x%llx",
                             static_cast<unsigned long long>(offset),
                             readable ? "" : "?",
                             static_cast<unsigned long long>(value));
            }
            std::fprintf(trace, "\n");
        }
        std::fclose(trace);
    }
}

extern "C" void executor_live_dump_current_hle_context(const char* reason,
                                                       const std::uint64_t focus) {
    const auto tid = static_cast<std::uint32_t>(syscall(SYS_gettid));
    const char* const dump_reason = reason && reason[0] ? reason : "<unknown>";
    const auto append_durable_dump = [&](const auto& writer) {
        static std::mutex dump_mutex;
        std::lock_guard dump_lock{dump_mutex};
        if (std::FILE* trace = std::fopen(
                "/data/data/app.lsx4.android/files/lsx4-home/diagnostic-hle-abort.txt", "a");
            trace != nullptr) {
            writer(trace);
            std::fflush(trace);
            std::fclose(trace);
        }
    };
    ExecutorLiveHleFlightEntry entry{};
    bool found = false;





    if (g_executor_current_hle_context.guest_rsp != 0) {
        entry.tid = tid;
        entry.rsp = g_executor_current_hle_context.guest_rsp;
        entry.guest_return = GuestReturnAddress(entry.rsp);
        pthread_getname_np(pthread_self(), entry.thread, sizeof(entry.thread));
        std::snprintf(
            entry.name, sizeof(entry.name), "%s",
            g_executor_current_hle_context.name
                ? g_executor_current_hle_context.name
                : "<current-hle-boundary>");
        std::snprintf(
            entry.symbol, sizeof(entry.symbol), "%s",
            g_executor_current_hle_context.symbol
                ? g_executor_current_hle_context.symbol
                : "<current-hle-boundary>");
        if (Core::Module* module = FindGuestModuleByAddress(entry.guest_return)) {
            entry.return_off = GuestModuleOffset(*module, entry.guest_return);
            const auto module_base = ExecutorBasenameForFlight(module->file.string());
            std::snprintf(entry.module, sizeof(entry.module), "%s", module_base.c_str());
        } else {
            std::snprintf(entry.module, sizeof(entry.module), "%s", "<unknown>");
        }
        found = true;
    }
    if (!found) {
        std::lock_guard lock(g_live_hle_flight_lock);
        if (const auto it = g_live_hle_inflight.find(tid); it != g_live_hle_inflight.end()) {
            entry = it->second;
            found = true;
        }
        const auto last_seq = g_live_hle_flight_seq.load(std::memory_order_relaxed);
        const auto first = last_seq > g_live_hle_flight.size()
                               ? last_seq - g_live_hle_flight.size() + 1
                               : 1;
        for (auto seq = last_seq; !found && seq >= first && seq != 0; --seq) {
            const auto& candidate = g_live_hle_flight[seq % g_live_hle_flight.size()];
            if (candidate.seq != seq || candidate.tid != tid ||
                std::strcmp(candidate.phase, "call") != 0) {
                continue;
            }
            entry = candidate;
            found = true;
            break;
        }
    }

    if (!found) {
        NativeLog(ANDROID_LOG_WARN,
                  "[EXECUTOR_HLE_CONTEXT_DUMP] reason=%s found=0 tid=%u focus=%p",
                  dump_reason, tid,
                  reinterpret_cast<void*>(focus));
        append_durable_dump([&](std::FILE* trace) {
            std::fprintf(trace, "reason=%s found=0 tid=%u focus=0x%llx\n", dump_reason,
                         tid, static_cast<unsigned long long>(focus));
        });
        return;
    }

    Core::Module* ret_module = FindGuestModuleByAddress(entry.guest_return);
    const std::uint64_t ret_context =
        entry.guest_return >= 64 ? entry.guest_return - 64 : entry.guest_return;
    const std::uint64_t focus_context = focus >= 64 ? focus - 64 : focus;
    std::string stack_bytes;
    std::string ret_context_bytes;
    std::string focus_bytes;
    {
        std::lock_guard lock(g_box64_boundary_probe_lock);
        stack_bytes = GuestBytesHexCheckedLocked(entry.rsp, 0x180);
        ret_context_bytes = GuestBytesHexCheckedLocked(ret_context, 0x140);
        focus_bytes = GuestBytesHexCheckedLocked(focus_context, 0x100);
        LogGuestStackCallchainLocked("EXECUTOR_HLE_CONTEXT_CALLCHAIN", entry.rsp, 0x600);
    }

    NativeLog(ANDROID_LOG_WARN,
              "[EXECUTOR_HLE_CONTEXT_DUMP] reason=%s found=1 seq=%llu tid=%u thread=%s "
              "name=%s symbol=%s native=%p ret=%p off=0x%llx module=%s "
              "args=%p,%p,%p,%p,%p,%p rsp=%p focus=%p "
              "stack=%s retCtx=%s focusCtx=%s",
              dump_reason,
              static_cast<unsigned long long>(entry.seq), entry.tid,
              entry.thread[0] ? entry.thread : "<unnamed>", entry.name, entry.symbol,
              reinterpret_cast<void*>(entry.native_function),
              reinterpret_cast<void*>(entry.guest_return),
              ret_module ? static_cast<unsigned long long>(GuestModuleOffset(*ret_module,
                                                                             entry.guest_return))
                         : 0ull,
              ret_module ? ret_module->file.string().c_str() : "<unknown>",
              reinterpret_cast<void*>(entry.args[0]), reinterpret_cast<void*>(entry.args[1]),
              reinterpret_cast<void*>(entry.args[2]), reinterpret_cast<void*>(entry.args[3]),
              reinterpret_cast<void*>(entry.args[4]), reinterpret_cast<void*>(entry.args[5]),
              reinterpret_cast<void*>(entry.rsp), reinterpret_cast<void*>(focus),
              stack_bytes.c_str(), ret_context_bytes.c_str(), focus_bytes.c_str());
    append_durable_dump([&](std::FILE* trace) {
        std::fprintf(
            trace,
            "reason=%s found=1 seq=%llu tid=%u thread=\"%s\" name=\"%s\" symbol=\"%s\" "
            "native=0x%llx ret=0x%llx off=0x%llx module=\"%s\" "
            "args=0x%llx,0x%llx,0x%llx,0x%llx,0x%llx,0x%llx rsp=0x%llx "
            "focus=0x%llx\nstack=%s\nretCtx=%s\nfocusCtx=%s\n",
            dump_reason, static_cast<unsigned long long>(entry.seq), entry.tid,
            entry.thread[0] ? entry.thread : "<unnamed>", entry.name, entry.symbol,
            static_cast<unsigned long long>(entry.native_function),
            static_cast<unsigned long long>(entry.guest_return),
            ret_module ? static_cast<unsigned long long>(
                             GuestModuleOffset(*ret_module, entry.guest_return))
                       : 0ull,
            ret_module ? ret_module->file.string().c_str() : "<unknown>",
            static_cast<unsigned long long>(entry.args[0]),
            static_cast<unsigned long long>(entry.args[1]),
            static_cast<unsigned long long>(entry.args[2]),
            static_cast<unsigned long long>(entry.args[3]),
            static_cast<unsigned long long>(entry.args[4]),
            static_cast<unsigned long long>(entry.args[5]),
            static_cast<unsigned long long>(entry.rsp),
            static_cast<unsigned long long>(focus), stack_bytes.c_str(),
            ret_context_bytes.c_str(), focus_bytes.c_str());
    });
}

bool IsAbortHleTarget(const char* name, const char* symbol_name) {
    return HleNameMatches(name, "abort", "L1SBTkC+Cvw") ||
           SymbolNameContains(symbol_name, "ExecutorAbort");
}

bool IsStackChkHleTarget(const char* name, const char* symbol_name) {
    return HleNameMatches(name, "__stack_chk_fail", "Ou3iL1abvng") ||
           SymbolNameContains(symbol_name, "stack_chk_fail");
}

bool IsBadAllocHleTarget(const char* name, const char* symbol_name) {
    return HleNameMatches(name, "_ZSt11_Xbad_allocv", "eT2UsmTewbU") ||
           SymbolNameContains(name, "bad_alloc") || SymbolNameContains(name, "Xbad_alloc") ||
           SymbolNameContains(symbol_name, "bad_alloc") ||
           SymbolNameContains(symbol_name, "Xbad_alloc");
}

extern std::uint64_t g_ghash_probe_addr;

std::string DecodeMonoStringBestEffortLocked(const std::uint64_t s) {
    if (s < 0x200000000ULL || s >= 0x810000000ULL) {
        return {};
    }
    std::uint64_t lenw = 0;
    if (!GuestReadQwordBestEffortLocked(s + 0x10, lenw)) {
        return {};
    }
    const std::uint32_t len = static_cast<std::uint32_t>(lenw & 0xffffffffu);
    if (len == 0 || len > 512) {
        return {};
    }
    std::string out;
    out.reserve(len);
    for (std::uint32_t k = 0; k < len; ++k) {
        std::uint64_t w = 0;
        if (!GuestReadQwordBestEffortLocked(s + 0x14 + (k & ~3u) * 2, w)) {
            break;
        }
        const std::uint16_t ch =
            static_cast<std::uint16_t>((w >> ((k & 3u) * 16)) & 0xffffu);
        out.push_back((ch >= 0x20 && ch < 0x7f) ? static_cast<char>(ch) : '?');
    }
    return out;
}

std::string DescribeMonoHeapObjectShallowLocked(const std::uint64_t obj) {
    if (obj < 0x200000000ULL || obj >= 0x810000000ULL) {
        return "nonheap";
    }

    std::uint64_t vt = 0;
    std::uint64_t klass = 0;
    std::uint64_t klass_name = 0;
    std::uint64_t klass_ns = 0;
    std::uint64_t sync_or_bounds = 0;
    std::uint64_t len_or_max = 0;
    GuestReadQwordBestEffortLocked(obj + 0x00, vt);
    GuestReadQwordBestEffortLocked(obj + 0x08, sync_or_bounds);
    GuestReadQwordBestEffortLocked(obj + 0x10, len_or_max);
    if (vt >= 0x200000000ULL && vt < 0x810000000ULL) {
        GuestReadQwordBestEffortLocked(vt + 0x00, klass);
    }
    if (klass >= 0x200000000ULL && klass < 0x810000000ULL) {
        GuestReadQwordBestEffortLocked(klass + 0x48, klass_name);
        GuestReadQwordBestEffortLocked(klass + 0x50, klass_ns);
    }

    std::ostringstream out;
    out << "obj=0x" << std::hex << obj << " vt=0x" << vt << " klass=0x" << klass;
    const std::string name = GuestCStringPreviewLocked(klass_name, 96);
    const std::string ns = GuestCStringPreviewLocked(klass_ns, 96);
    if (!ns.empty() || !name.empty()) {
        out << " klassName=\"" << ns << (ns.empty() || name.empty() ? "" : ".") << name << "\"";
    }
    const std::string as_string = DecodeMonoStringBestEffortLocked(obj);
    if (!as_string.empty()) {
        out << " str=\"" << as_string << "\"";
    }
    out << " q08=0x" << sync_or_bounds << " q10=0x" << len_or_max
        << " bytes=" << GuestBytesHexBestEffortLocked(obj, 0x50);
    return out.str();
}

std::string DescribeMonoArrayIpsBestEffortLocked(const std::uint64_t obj) {
    if (obj < 0x200000000ULL || obj >= 0x810000000ULL) {
        return {};
    }

    std::uint64_t bounds = 0;
    std::uint64_t max_length = 0;
    GuestReadQwordBestEffortLocked(obj + 0x10, bounds);
    GuestReadQwordBestEffortLocked(obj + 0x18, max_length);
    if (max_length == 0 || max_length > 64) {
        return {};
    }

    std::ostringstream out;
    out << " arrayBounds=0x" << std::hex << bounds << " max=0x" << max_length << " ips=";
    const std::uint64_t shown = std::min<std::uint64_t>(max_length, 16);
    for (std::uint64_t i = 0; i < shown; ++i) {
        std::uint64_t ip = 0;
        GuestReadQwordBestEffortLocked(obj + 0x20 + i * sizeof(ip), ip);
        if (i != 0) {
            out << ",";
        }
        out << "0x" << std::hex << ip;
        if (Core::Module* module = FindGuestModuleByAddress(ip)) {
            out << "@" << std::hex << GuestModuleOffset(*module, ip);
        }
    }
    return out.str();
}

std::string DescribeMonoObjectBestEffortLocked(const std::uint64_t obj) {
    if (obj < 0x200000000ULL || obj >= 0x810000000ULL) {
        return "nonheap";
    }
    std::uint64_t vt = 0;
    std::uint64_t klass = 0;
    std::uint64_t klass_name = 0;
    std::uint64_t klass_ns = 0;
    std::uint64_t msg_ptr = 0;
    std::uint64_t exc_cls_ptr = 0;
    GuestReadQwordBestEffortLocked(obj + 0x00, vt);
    if (vt >= 0x200000000ULL && vt < 0x810000000ULL) {
        GuestReadQwordBestEffortLocked(vt + 0x00, klass);
    }
    if (klass >= 0x200000000ULL && klass < 0x810000000ULL) {
        GuestReadQwordBestEffortLocked(klass + 0x48, klass_name);
        GuestReadQwordBestEffortLocked(klass + 0x50, klass_ns);
    }
    GuestReadQwordBestEffortLocked(obj + 0x20, msg_ptr);
    GuestReadQwordBestEffortLocked(obj + 0x30, exc_cls_ptr);

    const std::string name = GuestCStringPreviewLocked(klass_name, 96);
    const std::string ns = GuestCStringPreviewLocked(klass_ns, 96);
    const std::string msg = DecodeMonoStringBestEffortLocked(msg_ptr);
    const std::string exc_cls = DecodeMonoStringBestEffortLocked(exc_cls_ptr);
    std::ostringstream out;
    out << "obj=0x" << std::hex << obj << " vt=0x" << vt << " klass=0x" << klass;
    if (!ns.empty() || !name.empty()) {
        out << " klassName=\"" << ns << (ns.empty() || name.empty() ? "" : ".") << name << "\"";
    }
    if (!msg.empty()) {
        out << " excMessage=\"" << msg << "\"";
    }
    if (!exc_cls.empty()) {
        out << " excClassName=\"" << exc_cls << "\"";
    }
    for (std::uint64_t off :
         {0x10ull, 0x18ull, 0x20ull, 0x28ull, 0x30ull, 0x38ull, 0x40ull, 0x50ull,
          0x58ull, 0x60ull, 0x68ull}) {
        std::uint64_t p = 0;
        if (!GuestReadQwordBestEffortLocked(obj + off, p) || p < 0x200000000ULL ||
            p >= 0x810000000ULL) {
            continue;
        }
        const std::string as_string = DecodeMonoStringBestEffortLocked(p);
        std::uint64_t p_vt = 0;
        std::uint64_t p_msg = 0;
        std::uint64_t p_cls = 0;
        std::string p_msg_s;
        std::string p_cls_s;
        GuestReadQwordBestEffortLocked(p + 0x00, p_vt);
        if (GuestReadQwordBestEffortLocked(p + 0x20, p_msg)) {
            p_msg_s = DecodeMonoStringBestEffortLocked(p_msg);
        }
        if (GuestReadQwordBestEffortLocked(p + 0x30, p_cls)) {
            p_cls_s = DecodeMonoStringBestEffortLocked(p_cls);
        }
        out << " field+0x" << std::hex << off << "=0x" << p << "[vt=0x" << p_vt;
        if (!as_string.empty()) {
            out << " str=\"" << as_string << "\"";
        }
        out << " shallow={" << DescribeMonoHeapObjectShallowLocked(p) << "}";
        const std::string array_ips = DescribeMonoArrayIpsBestEffortLocked(p);
        if (!array_ips.empty()) {
            out << array_ips;
        }
        if (!p_msg_s.empty()) {
            out << " msg=\"" << p_msg_s << "\"";
        }
        if (!p_cls_s.empty()) {
            out << " cls=\"" << p_cls_s << "\"";
        }
        out << "]";
    }
    out << " bytes=" << GuestBytesHexBestEffortLocked(obj, 0x50);
    return out.str();
}

void LogMonoObjectFieldStringsLocked(const char* tag, const char* reason, std::uint64_t obj) {
    if (obj < 0x200000000ULL || obj >= 0x810000000ULL) {
        return;
    }
    for (std::uint64_t off :
         {0x10ull, 0x18ull, 0x20ull, 0x28ull, 0x30ull, 0x38ull, 0x40ull, 0x48ull,
          0x50ull, 0x58ull, 0x60ull, 0x68ull, 0x70ull}) {
        std::uint64_t p = 0;
        if (!GuestReadQwordBestEffortLocked(obj + off, p) || p < 0x200000000ULL ||
            p >= 0x810000000ULL) {
            continue;
        }
        const std::string mono_string = DecodeMonoStringBestEffortLocked(p);
        const std::string c_string = GuestCStringPreviewLocked(p, 128);
        std::uint64_t p_vt = 0;
        std::uint64_t p_klass = 0;
        GuestReadQwordBestEffortLocked(p + 0x00, p_vt);
        if (p_vt >= 0x200000000ULL && p_vt < 0x810000000ULL) {
            GuestReadQwordBestEffortLocked(p_vt + 0x00, p_klass);
        }
        NativeLog(ANDROID_LOG_ERROR,
                  "[%s] reason=%s obj=0x%llx off=0x%llx ptr=0x%llx vt=0x%llx klass=0x%llx "
                  "monoString=\"%s\" cString=\"%s\" shallow={%s}",
                  tag ? tag : "EXECUTOR_MONO_OBJECT_FIELD", reason ? reason : "<unknown>",
                  (unsigned long long)obj, (unsigned long long)off, (unsigned long long)p,
                  (unsigned long long)p_vt, (unsigned long long)p_klass, mono_string.c_str(),
                  c_string.c_str(), DescribeMonoHeapObjectShallowLocked(p).c_str());
    }
}

void RecordBadAllocDetail(const char* name, const char* symbol_name,
                          const std::uint64_t native_function, const std::uint64_t arg0,
                          const std::uint64_t arg1, const std::uint64_t arg2,
                          const std::uint64_t arg3, const std::uint64_t arg4,
                          const std::uint64_t arg5, const std::uint64_t guest_rsp) {
    static std::atomic_int bad_alloc_log_budget{64};
    if (bad_alloc_log_budget.fetch_sub(1, std::memory_order_relaxed) <= 0) {
        return;
    }

    const std::uint64_t guest_return = GuestReturnAddress(guest_rsp);
    Core::Module* module = FindGuestModuleByAddress(guest_return);
    const std::string module_path = module ? module->file.string() : "";
    const std::uint64_t module_offset = module ? GuestModuleOffset(*module, guest_return) : 0;
    const std::uint64_t return_context = guest_return >= 64 ? guest_return - 64 : guest_return;
    std::string stack_bytes;
    std::string return_context_bytes;
    {
        std::lock_guard lock(g_box64_boundary_probe_lock);
        stack_bytes = GuestBytesHexCheckedLocked(guest_rsp, 160);
        return_context_bytes = GuestBytesHexCheckedLocked(return_context, 160);
        LogGuestStackCallchainLocked("EXECUTOR_BAD_ALLOC_CALLCHAIN", guest_rsp, 2048);
    }

    NativeLog(ANDROID_LOG_ERROR,
              "[EXECUTOR_BAD_ALLOC_CALL] name=%s symbol=%s native=%p ret=%p returnOff=0x%llx "
              "module=%s args=%p,%p,%p,%p,%p,%p rsp=%p stack=%s retCtx=%s",
              name && name[0] ? name : "<unknown>",
              symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
              reinterpret_cast<void*>(native_function), reinterpret_cast<void*>(guest_return),
              static_cast<unsigned long long>(module_offset),
              module_path.empty() ? "<unknown>" : module_path.c_str(), reinterpret_cast<void*>(arg0),
              reinterpret_cast<void*>(arg1), reinterpret_cast<void*>(arg2),
              reinterpret_cast<void*>(arg3), reinterpret_cast<void*>(arg4),
              reinterpret_cast<void*>(arg5), reinterpret_cast<void*>(guest_rsp),
              stack_bytes.c_str(), return_context_bytes.c_str());
}

void RecordAbortDetail(const char* name, const char* symbol_name, const std::uint64_t native_function,
                       const std::uint64_t arg0, const std::uint64_t arg1,
                       const std::uint64_t arg2, const std::uint64_t arg3,
                       const std::uint64_t arg4, const std::uint64_t arg5,
                       const std::uint64_t guest_rsp) {
    static std::atomic_int abort_log_budget{128};
    if (abort_log_budget.fetch_sub(1, std::memory_order_relaxed) <= 0) {
        return;
    }

    const std::uint64_t guest_return = GuestReturnAddress(guest_rsp);
    Core::Module* module = FindGuestModuleByAddress(guest_return);
    const std::string module_path = module ? module->file.string() : "";
    const std::uint64_t module_offset = module ? GuestModuleOffset(*module, guest_return) : 0;
    const bool return_readable = IsCurrentMappedEntryReadableAddressLocked(guest_return);
    const std::uint64_t return_context = guest_return >= 64 ? guest_return - 64 : guest_return;
    std::uint64_t prev_call_target = 0;
    std::string prev_call_bytes;
    std::string prev_call_target_bytes;
    if (guest_return >= 5 && IsCurrentMappedEntryReadableAddressLocked(guest_return - 5)) {
        const auto* call = reinterpret_cast<const std::uint8_t*>(guest_return - 5);
        prev_call_bytes = GuestBytesHex(guest_return - 5, 5);
        if (call[0] == 0xe8) {
            std::int32_t displacement = 0;
            std::memcpy(&displacement, call + 1, sizeof(displacement));
            prev_call_target = static_cast<std::uint64_t>(
                static_cast<std::int64_t>(guest_return) + static_cast<std::int64_t>(displacement));
            if (IsCurrentMappedEntryReadableAddressLocked(prev_call_target)) {
                prev_call_target_bytes = GuestBytesHex(prev_call_target, 32);
            }
        }
    }

    const std::array<std::uint64_t, 6> args{arg0, arg1, arg2, arg3, arg4, arg5};
    std::array<std::string, 6> text{};
    std::array<std::string, 6> bytes{};
    {
        std::lock_guard lock(g_box64_boundary_probe_lock);
        for (std::size_t i = 0; i < args.size(); ++i) {
            text[i] = GuestCStringPreviewLocked(args[i], 192);
            bytes[i] = IsCurrentMappedEntryReadableAddressLocked(args[i])
                           ? GuestBytesHex(args[i], 32)
                           : std::string{"<unreadable>"};
        }
    }

    auto log_guest_bytes_chunks = [&](const char* tag, std::uint64_t address, std::size_t size) {
        constexpr std::size_t kChunk = 0x40;
        if (address == 0 || size == 0) {
            return;
        }
        for (std::size_t off = 0; off < size; off += kChunk) {
            const std::size_t chunk = std::min<std::size_t>(kChunk, size - off);
            const std::uint64_t cur = address + off;
            std::string hex;
            {
                std::lock_guard lock(g_box64_boundary_probe_lock);
                hex = GuestBytesHexCheckedLocked(cur, chunk);
            }
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_ABORT_CODE_CHUNK] tag=%s base=%p off=0x%zx size=0x%zx bytes=%s",
                      tag, reinterpret_cast<void*>(address), off, chunk,
                      hex.empty() ? "<unreadable>" : hex.c_str());
        }
    };
    const std::uint64_t wide_return_context =
        guest_return >= 0x120 ? guest_return - 0x120 : guest_return;
    log_guest_bytes_chunks("ret_wide", wide_return_context, 0x260);
    log_guest_bytes_chunks("guest_stack", guest_rsp, 0x120);
    if (prev_call_target != 0) {
        const std::uint64_t target_context =
            prev_call_target >= 0x20 ? prev_call_target - 0x20 : prev_call_target;
        log_guest_bytes_chunks("prev_call_target", target_context, 0x80);
    }
    for (std::size_t i = 0; i < args.size(); ++i) {
        if (args[i] >= 0x10000 && IsCurrentMappedEntryReadableAddressLocked(args[i])) {
            char tag[32]{};
            std::snprintf(tag, sizeof(tag), "arg%zu", i);
            log_guest_bytes_chunks(tag, args[i], 0x80);
        }
    }

    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_ABORT_DETAIL] name=%s symbol=%s native=%p ret=%p returnOff=0x%llx "
              "module=%s prevCallTarget=%p prevCallBytes=%s prevCallTargetBytes=%s "
              "retBytes=%s args=%p,%p,%p,%p,%p,%p "
              "str0=\"%s\" str1=\"%s\" str2=\"%s\" str3=\"%s\" str4=\"%s\" str5=\"%s\" "
              "argBytes0=%s argBytes1=%s argBytes2=%s argBytes3=%s argBytes4=%s argBytes5=%s "
              "retCtx=%s rsp=%p",
              name && name[0] ? name : "<unknown>",
              symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
              reinterpret_cast<void*>(native_function), reinterpret_cast<void*>(guest_return),
              static_cast<unsigned long long>(module_offset),
              module_path.empty() ? "<unknown>" : module_path.c_str(),
              reinterpret_cast<void*>(prev_call_target), prev_call_bytes.c_str(),
              prev_call_target_bytes.empty() ? "<unreadable>" : prev_call_target_bytes.c_str(),
              return_readable ? GuestBytesHex(guest_return, 24).c_str() : "<unreadable>",
              reinterpret_cast<void*>(arg0), reinterpret_cast<void*>(arg1),
              reinterpret_cast<void*>(arg2), reinterpret_cast<void*>(arg3),
              reinterpret_cast<void*>(arg4), reinterpret_cast<void*>(arg5), text[0].c_str(),
              text[1].c_str(), text[2].c_str(), text[3].c_str(), text[4].c_str(),
              text[5].c_str(), bytes[0].c_str(), bytes[1].c_str(), bytes[2].c_str(),
              bytes[3].c_str(), bytes[4].c_str(), bytes[5].c_str(),
              IsCurrentMappedEntryReadableAddressLocked(return_context)
                  ? GuestBytesHex(return_context, 128).c_str()
                  : "<unreadable>",
              reinterpret_cast<void*>(guest_rsp));
    std::fprintf(stderr,
                 "[EXECUTOR_ABORT_DETAIL] symbol=%s ret=%p returnOff=0x%llx args=%p,%p,%p,%p,%p,%p "
                 "str0=\"%s\" str1=\"%s\" str2=\"%s\" str3=\"%s\" str4=\"%s\" str5=\"%s\" "
                 "argBytes0=%s argBytes5=%s\n",
                 symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
                 reinterpret_cast<void*>(guest_return), static_cast<unsigned long long>(module_offset),
                 reinterpret_cast<void*>(arg0), reinterpret_cast<void*>(arg1),
                 reinterpret_cast<void*>(arg2), reinterpret_cast<void*>(arg3),
                 reinterpret_cast<void*>(arg4), reinterpret_cast<void*>(arg5), text[0].c_str(),
                 text[1].c_str(), text[2].c_str(), text[3].c_str(), text[4].c_str(),
                 text[5].c_str(), bytes[0].c_str(), bytes[5].c_str());
    std::fflush(stderr);
}

void RecordGuestCanaryContext(const char* tag, const char* name, const char* symbol_name,
                              const std::uint64_t result, const std::uint64_t arg0,
                              const std::uint64_t guest_rsp) {
    ExecutorBox64GuestRegsSnapshot regs{};
    const int regs_rc = TryGetCurrentGuestRegsSnapshot(regs);
    const std::uint64_t guest_return = GuestReturnAddress(guest_rsp);
    Core::Module* module = FindGuestModuleByAddress(guest_return);
    const std::uint64_t off = module ? GuestModuleOffset(*module, guest_return) : 0;

    std::uint64_t rbp_m08 = 0;
    std::uint64_t rbp_m10 = 0;
    std::uint64_t rbp_m18 = 0;
    std::uint64_t rbp_m20 = 0;
    std::uint64_t rbp_m28 = 0;
    std::uint64_t rbp_m30 = 0;
    std::uint64_t stack_ret = 0;
    std::uint64_t guard_value = 0;
    auto* guard_ptr = Libraries::Kernel::GetStackChkGuardExportStorage();
    if (guard_ptr != nullptr) {
        std::memcpy(&guard_value, guard_ptr, sizeof(guard_value));
    }
    std::string stack_bytes;
    {
        std::lock_guard lock(g_box64_boundary_probe_lock);
        if (regs_rc == 0) {
            (void)GuestReadQwordBestEffortLocked(regs.regs[5] - 0x08, rbp_m08);
            (void)GuestReadQwordBestEffortLocked(regs.regs[5] - 0x10, rbp_m10);
            (void)GuestReadQwordBestEffortLocked(regs.regs[5] - 0x18, rbp_m18);
            (void)GuestReadQwordBestEffortLocked(regs.regs[5] - 0x20, rbp_m20);
            (void)GuestReadQwordBestEffortLocked(regs.regs[5] - 0x28, rbp_m28);
            (void)GuestReadQwordBestEffortLocked(regs.regs[5] - 0x30, rbp_m30);
            (void)GuestReadQwordBestEffortLocked(regs.regs[4], stack_ret);
        }
        stack_bytes = GuestBytesHexCheckedLocked(guest_rsp, 96);
    }

    NativeLog(ANDROID_LOG_WARN,
              "[EXECUTOR_GUEST_CANARY_CTX] tag=%s name=%s symbol=%s result=%p sem=%p "
              "ret=%p off=0x%llx module=%s regsRc=%d rip=%p oldIp=%p rsp=%p rbp=%p "
              "rax=%p rbx=%p rcx=%p rdx=%p rsi=%p rdi=%p r12=%p r13=%p r14=%p r15=%p "
              "stackRet=%p guardPtr=%p guard=0x%llx rbp_m08=0x%llx rbp_m10=0x%llx "
              "rbp_m18=0x%llx rbp_m20=0x%llx "
              "rbp_m28=0x%llx rbp_m30=0x%llx hleRsp=%p hleStack=%s",
              tag ? tag : "<unknown>", name && name[0] ? name : "<unknown>",
              symbol_name && symbol_name[0] ? symbol_name : "<unknown>",
              reinterpret_cast<void*>(result), reinterpret_cast<void*>(arg0),
              reinterpret_cast<void*>(guest_return), static_cast<unsigned long long>(off),
              module ? module->file.string().c_str() : "<unknown>", regs_rc,
              reinterpret_cast<void*>(regs.rip), reinterpret_cast<void*>(regs.old_ip),
              reinterpret_cast<void*>(regs.regs[4]), reinterpret_cast<void*>(regs.regs[5]),
              reinterpret_cast<void*>(regs.regs[0]), reinterpret_cast<void*>(regs.regs[3]),
              reinterpret_cast<void*>(regs.regs[1]), reinterpret_cast<void*>(regs.regs[2]),
              reinterpret_cast<void*>(regs.regs[6]), reinterpret_cast<void*>(regs.regs[7]),
              reinterpret_cast<void*>(regs.regs[12]), reinterpret_cast<void*>(regs.regs[13]),
              reinterpret_cast<void*>(regs.regs[14]), reinterpret_cast<void*>(regs.regs[15]),
              reinterpret_cast<void*>(stack_ret), reinterpret_cast<void*>(guard_ptr),
              static_cast<unsigned long long>(guard_value), static_cast<unsigned long long>(rbp_m08),
              static_cast<unsigned long long>(rbp_m10), static_cast<unsigned long long>(rbp_m18),
              static_cast<unsigned long long>(rbp_m20), static_cast<unsigned long long>(rbp_m28),
              static_cast<unsigned long long>(rbp_m30), reinterpret_cast<void*>(guest_rsp),
              stack_bytes.c_str());
}

struct ScopedExecutorHleGuestThreadBind {
    Libraries::Kernel::Pthread* previous = Libraries::Kernel::g_curthread;
    bool changed = false;

    ScopedExecutorHleGuestThreadBind(std::uint64_t guest_thread, const char* name,
                                     const char* symbol_name) {
        auto* thread = reinterpret_cast<Libraries::Kernel::Pthread*>(guest_thread);
        if (thread == nullptr || thread == previous) {
            return;
        }
        Libraries::Kernel::g_curthread = thread;
        changed = true;

        static std::atomic_int log_budget{128};
        if (log_budget.fetch_sub(1, std::memory_order_relaxed) > 0) {
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_HLE_THREAD_BIND] guestThread=%p name=%s hle=%s symbol=%s",
                      static_cast<void*>(thread), thread->name.c_str(),
                      name && name[0] ? name : "<unknown>",
                      symbol_name && symbol_name[0] ? symbol_name : "<unknown>");
        }
    }

    ~ScopedExecutorHleGuestThreadBind() {
        if (changed) {
            Libraries::Kernel::g_curthread = previous;
        }
    }
};

struct ExecutorHleBoundaryPrelude {
    ExecutorHleBoundaryPrelude() {
        std::atomic_thread_fence(std::memory_order_acquire);
        PublishCurrentJitGcRegisterRootsAtHleBoundary();
    }
};

struct ScopedExecutorHleGuestReadLease {
    ExecutorActiveGuestReadLease previous = g_active_hle_guest_read_lease;

    ScopedExecutorHleGuestReadLease(const std::uint64_t guest_rsp,
                                    const std::uint64_t guest_thread) {
        const std::uint64_t stack_pointer = JitCanonicalHostPointer(guest_rsp);
        const std::uint64_t generation =
            g_box64_guest_readable_generation.load(std::memory_order_acquire);
        if (generation == 0) {
            return;
        }

        auto* const thread = reinterpret_cast<Libraries::Kernel::Pthread*>(guest_thread);
        if (thread != nullptr && thread->attr.stackaddr_attr != nullptr &&
            thread->attr.stacksize_attr != 0) {
            const std::uint64_t base = JitCanonicalHostPointer(
                reinterpret_cast<std::uint64_t>(thread->attr.stackaddr_attr));
            const std::uint64_t size = thread->attr.stacksize_attr;
            const std::uint64_t page_base = stack_pointer & ~JitRegisteredPageMask;
            if (JitRangeContained(stack_pointer, sizeof(std::uint64_t), base, size) &&
                JitRangeContained(page_base, JitRegisteredPageSize, base, size) &&
                IsJitRegisteredPageCached(stack_pointer, sizeof(std::uint64_t))) {
                g_active_hle_guest_read_lease = {
                    .base = page_base,
                    .size = JitRegisteredPageSize,
                    .generation = generation,
                };
                return;
            }
        }




        std::uint64_t slot_base = 0;
        if (!TryResolveExternalHleFrameSlot(stack_pointer, slot_base)) {
            return;
        }
        g_active_hle_guest_read_lease = {
            .base = slot_base,
            .size = Lsx4::FexHleLease::SlotSize,
            .generation = generation,
        };
    }

    ~ScopedExecutorHleGuestReadLease() {
        g_active_hle_guest_read_lease = previous;
    }
};

struct ScopedExecutorHleBoundary {
    ExecutorHleBoundaryPrelude prelude;
    ScopedExecutorHleGuestReadLease guest_read_lease;
    ScopedExecutorCurrentHleContext current_context;
    ScopedExecutorHleGuestThreadBind guest_thread_bind;
    bool release_pending = true;

    ScopedExecutorHleBoundary(
        const std::uint64_t guest_rsp, const char* name, const char* symbol,
        const std::array<std::uint64_t, 8>& floating_arguments,
        const std::uint64_t guest_thread)
        : guest_read_lease(guest_rsp, guest_thread),
          current_context(guest_rsp, name, symbol, floating_arguments),
          guest_thread_bind(guest_thread, name, symbol) {}

    void Release() {
        if (!release_pending) {
            return;
        }
        std::atomic_thread_fence(std::memory_order_release);
        release_pending = false;
    }

    ~ScopedExecutorHleBoundary() {
        Release();
    }
};

struct ScopedExecutorLeafHleBoundary {
    ExecutorHleBoundaryPrelude prelude;
    bool release_pending = true;

    void Release() {
        if (!release_pending) {
            return;
        }
        std::atomic_thread_fence(std::memory_order_release);
        release_pending = false;
    }

    ~ScopedExecutorLeafHleBoundary() {
        Release();
    }
};

enum class ExecutorHleFpAbi : std::uint8_t {
    None = 0,
    UnaryF32,
    BinaryF32,
    UnaryF64,
    BinaryF64,
    SincosF32,
    SincosF64,
    Ngs2PanInit,
    VideoOutGamma,
};

enum class ExecutorHleStackAbi : std::uint8_t {
    None = 0,
    FiberInitialize,
    FiberInitializeImpl,
};

bool HleNameMatchesAnyNid(const char* name,
                          const std::initializer_list<const char*> nids) {
    return std::any_of(nids.begin(), nids.end(), [&](const char* nid) {
        return HleNameMatches(name, nullptr, nid);
    });
}

ExecutorHleFpAbi ClassifyLibcMathHleAbi(const std::uint64_t native_function,
                                        const char* name) {
    using namespace Libraries::LibcInternal;

    if (native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_sincosf)) ||
        HleNameMatchesAnyNid(name, {"pztV4AF18iI"})) {
        return ExecutorHleFpAbi::SincosF32;
    }
    if (native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_sincos)) ||
        HleNameMatchesAnyNid(name, {"jMB7EFyu30Y"})) {
        return ExecutorHleFpAbi::SincosF64;
    }
    if (native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_atan2f)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_powf)) ||
        HleNameMatchesAnyNid(name, {"EH-x713A99c", "1D0H2KNjshE"})) {
        return ExecutorHleFpAbi::BinaryF32;
    }
    if (native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_atan2)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_pow)) ||
        HleNameMatchesAnyNid(name, {"HUbZmOnT-Dg", "9LCjpWyQ5Zc"})) {
        return ExecutorHleFpAbi::BinaryF64;
    }
    if (native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_sinf)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_cosf)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_tanf)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_asinf)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_acosf)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_atanf)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_expf)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_exp2f)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_logf)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_log10f)) ||
        HleNameMatchesAnyNid(name, {"Q4rRL34CEeE", "-P6FNMzk2Kc", "ZE6RNL+eLbk",
                                    "GZWjF-YIFFk", "QI-x0SL8jhw", "weDug8QD-lE",
                                    "8zsu04XNsZ4", "wuAQt-j+p4o", "RQXLbdT2lc4",
                                    "lhpd6Wk6ccs"})) {
        return ExecutorHleFpAbi::UnaryF32;
    }
    if (native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_sin)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_cos)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_tan)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_asin)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_acos)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_atan)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_exp)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_exp2)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_log)) ||
        native_function == reinterpret_cast<std::uint64_t>(HOST_CALL(internal_log10)) ||
        HleNameMatchesAnyNid(name, {"H8ya2H00jbI", "2WE3BTYVwKM", "T7uyNqP7vQA",
                                    "7Ly52zaL44Q", "JBcgYuW8lPU", "OXmauLdQ8kY",
                                    "NVadfnzQhHQ", "dnaeGXbjP6E", "rtV7-jWC6Yg",
                                    "WuMbPBKN1TU"})) {
        return ExecutorHleFpAbi::UnaryF64;
    }
    if (HleNameMatches(name, "sceNgs2PanInit", "xa8oL9dmXkM")) {
        return ExecutorHleFpAbi::Ngs2PanInit;
    }
    if (HleNameMatches(name, "sceVideoOutColorSettingsSetGamma", "DYhhWbJSeRg")) {
        return ExecutorHleFpAbi::VideoOutGamma;
    }
    return ExecutorHleFpAbi::None;
}

