        ExecutorHlePointerResultFamily::None;
    std::unique_ptr<std::atomic_bool> pointer_result_audited;
    bool known_target = false;
    bool executable = false;
    bool kernel_debug_out_text = false;
    bool abort_target = false;
    bool stack_chk_target = false;
    bool bad_alloc_target = false;
    bool pthread_target = false;
    bool fex_guest_thread_exit_target = false;
    bool fex_context_replacing_fiber_target = false;
    bool pthread_create_target = false;
    bool pthread_trylock_target = false;
    bool pthread_cond_timedwait_target = false;
    bool blocking_sem_wait_target = false;
    bool system_service_load_exec_target = false;
    bool libc_compare_target = false;
    bool live_trace_target = false;
    bool light_oracle_hle_flight_target = false;
    bool audio_out_target = false;
    ExecutorHleFpAbi fp_abi = ExecutorHleFpAbi::None;
    ExecutorHleStackAbi stack_abi = ExecutorHleStackAbi::None;
    bool gl_uniform1f = false;
    bool gl_uniform2f = false;
    bool gl_uniform4f = false;
    bool gl_clear_color = false;
    bool gl_tex_parameterf = false;
    bool gl_tex_image_2d = false;
    bool gl_tex_sub_image_2d = false;
    bool gl_read_pixels = false;
