    g_imt_wrapper_arg_base = g_imt_wrapper_base + wrappers_sz;
    g_imt_wrapper_func_cell =
        (g_imt_wrapper_arg_base + static_cast<std::size_t>(kImtWrapperPoolN) * 8u + 7u) &
        ~std::uint64_t{7u};
    g_imt_wrapper_counter_addr = g_imt_wrapper_func_cell + 8u;
    *reinterpret_cast<std::uint64_t*>(g_imt_wrapper_counter_addr) = 0;
    g_imt_alloc_overflow_counter_addr = g_imt_wrapper_counter_addr + 8u;
    g_imt_alloc_overflow_log_addr = (g_imt_alloc_overflow_counter_addr + 8u + 15u) &
                                    ~std::uint64_t{15u};
    *reinterpret_cast<std::uint64_t*>(g_imt_alloc_overflow_counter_addr) = 0;
    std::memset(reinterpret_cast<void*>(g_imt_alloc_overflow_log_addr), 0, 64u * 8u * 8u);
    g_imt_tail_overflow_counter_addr = g_imt_alloc_overflow_log_addr + 64u * 8u * 8u;
    *reinterpret_cast<std::uint64_t*>(g_imt_tail_overflow_counter_addr) = 0;
    g_imt_probe_method_addr = g_imt_tail_overflow_counter_addr + 8u;
    g_imt_probe_propid_addr = g_imt_probe_method_addr + 8u;
    *reinterpret_cast<std::uint64_t*>(g_imt_probe_method_addr) = 0;
    *reinterpret_cast<std::uint64_t*>(g_imt_probe_propid_addr) = 0;
    *reinterpret_cast<std::uint64_t*>(g_imt_wrapper_func_cell) = 0x8014b2b10ull;
    g_imt_patch_cursor.store(((g_imt_tail_overflow_counter_addr + 8u + 15u) &
                              ~std::uint64_t{15u}) - base,
                             std::memory_order_relaxed);
