    const std::size_t brent_power_fixup = k - sizeof(std::int32_t);
    emit({0x48, 0x89, 0x5c, 0x24, 0x08});
    emit({0x48, 0xd1, 0x64, 0x24, 0x10});
    emit({0x48, 0xc7, 0x44, 0x24, 0x18, 0x00, 0x00, 0x00, 0x00});
    const std::size_t brent_done = k;
    patch_rel32(brent_update_fixup, brent_update);
    patch_rel32(brent_init_done_fixup, brent_done);
    patch_rel32(brent_power_fixup, brent_done);

    emit({0x48, 0x8b, 0x3b, 0x4c, 0x89, 0xe6, 0x41, 0xff, 0xd7});
    emit({0x48, 0x8d, 0x53, 0x10, 0x85, 0xc0});
    emit({0x0f, 0x84, 0x00, 0x00, 0x00, 0x00});
    const std::size_t loop_fixup = k - sizeof(std::int32_t);
    emit({0x48, 0x8b, 0x43, 0x08});
    emit({0xe9, 0x00, 0x00, 0x00, 0x00});
    const std::size_t epilogue_fixup = k - sizeof(std::int32_t);

