                std::this_thread::sleep_for(std::chrono::milliseconds(1000));
                if (g_iface_miss_buf == 0) continue;
                const auto* q = reinterpret_cast<volatile std::uint64_t*>(g_iface_miss_buf);
                const std::uint64_t count = q[0], klass = q[1], iface = q[2], idx = q[3], result = q[4];
                if (count == last) continue;
