bool IsMappedGuestPltResolverTail(const Core::Module& module,
                                  const std::uint64_t raw_target,
                                  std::uint64_t* normalized_target = nullptr) {
    const auto info = module.GetModuleInfo();
    const auto base = module.GetBaseAddress();
    const std::array<std::uint64_t, 2> candidates = {
        raw_target,
        raw_target <= UINT64_MAX - base ? base + raw_target : 0,
    };
    for (const auto target : candidates) {
        if (target == 0) {
            continue;
        }
        bool executable = false;
        for (std::uint32_t index = 0; index < info.num_segments; ++index) {
            const auto& segment = info.segments[index];
            if ((segment.prot & PF_EXEC) == 0 || target < segment.address ||
                target > segment.address + segment.size ||
                segment.address + segment.size - target < 6) {
                continue;
            }
            executable = true;
            break;
        }
        if (!executable) {
            continue;
        }
        const auto* code = reinterpret_cast<const std::uint8_t*>(target);
        const bool push_imm32_tail = code[0] == 0x68 && code[5] == 0xe9;
        const bool push_imm8_tail = code[0] == 0x6a && code[2] == 0xe9;
        if (!push_imm32_tail && !push_imm8_tail) {
            continue;
        }
        if (normalized_target != nullptr) {
            *normalized_target = target;
        }
        return true;
    }
    return false;
}

struct FexLazyPltAudit {
    std::uint32_t scanned{};
    std::uint32_t repaired{};
    std::uint32_t remaining{};
    std::vector<std::string> samples;
};

FexLazyPltAudit ScanFexLazyPltSlots(Core::Linker& linker, const bool clear_rela_bits) {
    FexLazyPltAudit audit{};
    for (std::size_t module_index = 0; module_index < linker.GetModuleCount(); ++module_index) {
        Core::Module* module = linker.GetModule(static_cast<s32>(module_index));
        if (module == nullptr || module->dynamic_info.symbol_table == nullptr ||
            module->dynamic_info.str_table == nullptr) {
            continue;
        }
        const auto base = module->GetBaseAddress();
        const std::uint32_t regular_relocation_count =
            module->dynamic_info.relocation_table_size / sizeof(elf_relocation);
        module->ForEachRelocation([&](elf_relocation* relocation, const u32 index,
                                      const bool is_jump_relocation) {
            if (!is_jump_relocation || relocation->GetType() != R_X86_64_JUMP_SLOT) {
                return;
            }
            ++audit.scanned;
            const std::uint64_t slot = base + relocation->rel_offset;
            std::uint64_t target = 0;
            std::memcpy(&target, reinterpret_cast<const void*>(slot), sizeof(target));
            std::uint64_t normalized_target = 0;
            if (!IsMappedGuestPltResolverTail(*module, target, &normalized_target)) {
                return;
            }
            const auto symbol_index = relocation->GetSymbol();
            const elf_symbol& symbol = module->dynamic_info.symbol_table[symbol_index];
            const char* raw_name = module->dynamic_info.str_table + symbol.st_name;
            const std::uint32_t bit_index = regular_relocation_count + index;
            if (audit.samples.size() < 8) {
                std::ostringstream sample;
                sample << module->file.filename().string() << ':'
                       << (raw_name != nullptr ? raw_name : "<unnamed>") << "@slot="
                       << Hex64(slot) << " target=" << Hex64(normalized_target)
                       << " bit=" << bit_index;
                audit.samples.emplace_back(sample.str());
            }
            if (clear_rela_bits) {
                module->ClearRelaBit(bit_index);
                ++audit.repaired;
            } else {
                ++audit.remaining;
            }
        });
    }
    return audit;
}

struct FexOptionalWeakPltRepair {
    std::uint32_t zeroed{};
    std::vector<std::string> samples;
};

FexOptionalWeakPltRepair ResolveFexOptionalWeakPltSlots(Core::Linker& linker) {
    FexOptionalWeakPltRepair repair{};
    for (std::size_t module_index = 0; module_index < linker.GetModuleCount(); ++module_index) {
        Core::Module* module = linker.GetModule(static_cast<s32>(module_index));
        if (module == nullptr || module->dynamic_info.symbol_table == nullptr ||
            module->dynamic_info.str_table == nullptr) {
            continue;
        }
        const auto base = module->GetBaseAddress();
        const std::uint32_t regular_relocation_count =
            module->dynamic_info.relocation_table_size / sizeof(elf_relocation);
        const std::size_t symbol_count =
            module->dynamic_info.symbol_table_total_size / sizeof(elf_symbol);
        module->ForEachRelocation([&](elf_relocation* relocation, const u32 index,
                                      const bool is_jump_relocation) {
            if (!is_jump_relocation || relocation->GetType() != R_X86_64_JUMP_SLOT) {
                return;
            }
            const std::uint64_t slot = base + relocation->rel_offset;
            std::uint64_t target = 0;
            std::memcpy(&target, reinterpret_cast<const void*>(slot), sizeof(target));
            if (!IsMappedGuestPltResolverTail(*module, target)) {
                return;
            }

            const auto symbol_index = relocation->GetSymbol();
            if (symbol_index >= symbol_count) {
                return;
            }
            const elf_symbol& symbol = module->dynamic_info.symbol_table[symbol_index];
            const auto symbol_type = symbol.GetType();
            if (symbol.GetBind() != STB_WEAK || symbol.st_shndx != 0 || symbol.st_value != 0 ||
                (symbol_type != STT_NOTYPE && symbol_type != STT_FUN) ||
                symbol.st_name >= module->dynamic_info.str_table_size) {
                return;
            }

            const char* raw_name = module->dynamic_info.str_table + symbol.st_name;
            const std::size_t available = module->dynamic_info.str_table_size - symbol.st_name;
            const auto* name_end = static_cast<const char*>(std::memchr(raw_name, '\0', available));
            if (name_end == nullptr || name_end == raw_name) {
                return;
            }
            const std::string_view name{raw_name,
                                        static_cast<std::size_t>(name_end - raw_name)};
            if (name.find('#') != std::string_view::npos) {
                return;
            }

            const std::uint64_t weak_undefined_value = 0;
            std::memcpy(reinterpret_cast<void*>(slot), &weak_undefined_value,
                        sizeof(weak_undefined_value));
            const std::uint32_t bit_index = regular_relocation_count + index;
            module->SetRelaBit(bit_index);
            ++repair.zeroed;
            if (repair.samples.size() < 8) {
                std::ostringstream sample;
                sample << module->file.filename().string() << ':' << name << "@slot="
                       << Hex64(slot) << " bit=" << bit_index;
                repair.samples.emplace_back(sample.str());
            }
        });
    }
    return repair;
}

bool ResolveFexLazyPltSlots(Core::Linker& linker, std::string& error) {
    const auto before = ScanFexLazyPltSlots(linker, true);
    if (before.repaired != 0) {
        linker.RelocateAllImports();
    }
    const auto optional_weak = ResolveFexOptionalWeakPltSlots(linker);
    const auto after = ScanFexLazyPltSlots(linker, false);
    std::ostringstream samples;
    for (std::size_t index = 0; index < after.samples.size(); ++index) {
        if (index != 0) {
            samples << ';';
        }
        samples << after.samples[index];
    }
    std::ostringstream optional_weak_samples;
    for (std::size_t index = 0; index < optional_weak.samples.size(); ++index) {
        if (index != 0) {
            optional_weak_samples << ';';
        }
        optional_weak_samples << optional_weak.samples[index];
    }
    NativeLog(after.remaining == 0 ? ANDROID_LOG_INFO : ANDROID_LOG_ERROR,
              "[EXECUTOR_FEX_EAGER_PLT] scanned=%u repaired=%u optionalWeakZeroed=%u "
              "remaining=%u samples=%s optionalWeakSamples=%s",
              before.scanned, before.repaired, optional_weak.zeroed, after.remaining,
              samples.str().empty() ? "<none>" : samples.str().c_str(),
              optional_weak_samples.str().empty() ? "<none>"
                                                  : optional_weak_samples.str().c_str());
    if (after.remaining == 0) {
        return true;
    }
    error = "FEX requires eager JUMP_SLOT resolution; unresolved lazy PLT slots remain: " +
            samples.str();
    return false;
}

void InstallBox64HleTrampolines(Core::Module& module) {
    ResetHleTrampolineTelemetry();
    const auto base = module.GetBaseAddress();

    module.ForEachRelocation([&](elf_relocation* rel, u32, bool) {
        const auto type = rel->GetType();
        if (type != R_X86_64_GLOB_DAT && type != R_X86_64_JUMP_SLOT && type != R_X86_64_64) {
            return;
        }
        if (!module.dynamic_info.symbol_table || !module.dynamic_info.str_table) {
            return;
        }

        const auto symbol_index = rel->GetSymbol();
        const elf_symbol& symbol = module.dynamic_info.symbol_table[symbol_index];
        if (symbol.GetType() != STT_FUN) {
            return;
        }

        const std::uint64_t slot = base + rel->rel_offset;
        if (!slot) {
            return;
        }

        auto* slot_ptr = reinterpret_cast<std::uint64_t*>(slot);
        const std::uint64_t native_value = *slot_ptr;
        if (!native_value || GuestAddressInsideModule(module, native_value)) {
            return;
        }
        if (!LooksLikeNativeRuntimePointer(native_value)) {
            return;
        }

        const char* raw_name = module.dynamic_info.str_table + symbol.st_name;
        const std::string name = raw_name ? raw_name : "";
        const std::uint64_t thunk = ResolveFexHleImportThunk(native_value, name);
        if (!thunk) {
            ++g_box64_hle_trampoline_skipped;
            return;
        }
        for (auto it = g_box64_hle_targets.rbegin(); it != g_box64_hle_targets.rend(); ++it) {
            if (it->thunk == thunk) {
                it->module_path = module.file.string();
                it->rel_offset = rel->rel_offset;
                it->slot = slot;
                break;
            }
        }
        const std::string native_name = NativePointerImportName(native_value);
        std::uint64_t write_thunk = thunk;
        if (IsAbortHleTarget(name.c_str(), nullptr) ||
            SymbolNameContains(native_name.c_str(), "ExecutorAbort")) {
            if (AbortNoRetEnabled() && AbortNoopStub()) {
                write_thunk = AbortNoopStub();
            }
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_ABORT_IMPORT] module=%s raw=%s relOff=0x%llx slot=%p "
                      "native=%p nativeName=%s thunk=%p noret=%d",
                      module.file.string().c_str(), name.c_str(),
                      static_cast<unsigned long long>(rel->rel_offset),
                      reinterpret_cast<void*>(slot), reinterpret_cast<void*>(native_value),
                      native_name.c_str(), reinterpret_cast<void*>(write_thunk), AbortNoRetEnabled());
        }
        *slot_ptr = write_thunk;
    });

    const auto info = module.GetModuleInfo();
    for (std::uint32_t i = 0; i < info.num_segments; ++i) {
        const auto& segment = info.segments[i];
        if (segment.size < sizeof(std::uint64_t)) {
            continue;
        }
        if ((segment.prot & PF_WRITE) == 0 || (segment.prot & PF_EXEC) != 0) {
            continue;
        }

        const std::uint64_t begin = (segment.address + 7u) & ~std::uint64_t{7u};
        const std::uint64_t end = segment.address + segment.size;
        for (std::uint64_t slot = begin; slot + sizeof(std::uint64_t) <= end;
             slot += sizeof(std::uint64_t)) {
            ++g_box64_hle_trampoline_scanned_slots;
            auto* slot_ptr = reinterpret_cast<std::uint8_t*>(slot);
            std::uint64_t native_value = 0;
            std::memcpy(&native_value, slot_ptr, sizeof(native_value));
            if (!native_value || GuestAddressInsideModule(module, native_value) ||
                !LooksLikeNativeRuntimePointer(native_value)) {
                continue;
            }

            const HleTargetTelemetry* known_target = FindKnownHleFunctionTarget(native_value);
            if (!known_target) {
                NativeLog(ANDROID_LOG_INFO,
                          "[EXECUTOR_HLE_POST_SCAN_SKIP] slot=%p target=%p reason=not_function_import "
                          "name=%s",
                          reinterpret_cast<void*>(slot), reinterpret_cast<void*>(native_value),
                          NativePointerImportName(native_value).c_str());
                continue;
            }

            const std::string name = known_target->name.empty() ? NativePointerImportName(native_value)
                                                                : known_target->name;
            const std::uint64_t thunk = ResolveFexHleImportThunk(native_value, name);
            if (!thunk) {
                ++g_box64_hle_trampoline_skipped;
                continue;
            }
            for (auto it = g_box64_hle_targets.rbegin(); it != g_box64_hle_targets.rend(); ++it) {
                if (it->thunk == thunk) {
                    it->module_path = module.file.string();
                    it->slot = slot;
                    break;
                }
            }
            std::uint64_t write_thunk = thunk;
            if (SymbolNameContains(name.c_str(), "ExecutorAbort") && AbortNoRetEnabled() &&
                AbortNoopStub()) {
                write_thunk = AbortNoopStub();
            }
            std::memcpy(slot_ptr, &write_thunk, sizeof(write_thunk));
            ++g_box64_hle_trampoline_post_scan_patched;
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_HLE_POST_SCAN] slot=%p target=%p thunk=%p name=%s",
                      reinterpret_cast<void*>(slot), reinterpret_cast<void*>(native_value),
                      reinterpret_cast<void*>(write_thunk), name.c_str());
            if (SymbolNameContains(name.c_str(), "ExecutorAbort")) {
                NativeLog(ANDROID_LOG_INFO,
                          "[EXECUTOR_ABORT_IMPORT] module=%s raw=%s relOff=post_scan slot=%p "
                          "native=%p nativeName=%s thunk=%p",
                          module.file.string().c_str(), name.c_str(),
                          reinterpret_cast<void*>(slot), reinterpret_cast<void*>(native_value),
                          name.c_str(), reinterpret_cast<void*>(thunk));
            }
        }
    }
}

extern "C" int executor_lsx4_android_patch_box64_hle_imports(void* module_ptr) {
    auto* module = reinterpret_cast<Core::Module*>(module_ptr);
    if (module == nullptr) {
        return -1;
    }
    InstallBox64HleTrampolines(*module);
    const int status = g_box64_hle_trampoline_skipped == 0 ? 0 : -2;
    NativeLog(status == 0 ? ANDROID_LOG_INFO : ANDROID_LOG_ERROR,
              "[EXECUTOR_HLE_DYNAMIC_TRAMPOLINES] path=%s result=%d count=%llu "
              "skipped=%u postScanPatched=%llu usedBytes=%llu",
              module->file.string().c_str(),
              status,
              static_cast<unsigned long long>(g_box64_hle_trampoline_count),
              g_box64_hle_trampoline_skipped,
              static_cast<unsigned long long>(g_box64_hle_trampoline_post_scan_patched),
              static_cast<unsigned long long>(g_box64_hle_trampoline_used));
    return status;
}

std::string BuildHleTrampolineStatusJson() {
    std::ostringstream out;
    out << "{"
        << R"("enabled":true,)"
        << R"("syscall":")" << Hex64(ExecutorBox64HleBridgeSyscall) << R"(",)"
        << R"("count":)" << g_box64_hle_trampoline_count << ","
        << R"("skipped":)" << g_box64_hle_trampoline_skipped << ","
        << R"("postScanSlots":)" << g_box64_hle_trampoline_scanned_slots << ","
        << R"("postScanPatched":)" << g_box64_hle_trampoline_post_scan_patched << ","
        << R"("slab":")"
        << Hex64(reinterpret_cast<std::uint64_t>(g_box64_hle_trampoline_slab)) << R"(",)"
        << R"("slabCapacity":)" << ExecutorBox64HleTrampolineSlabSize << ","
        << R"("usedBytes":)" << g_box64_hle_trampoline_used << ","
        << R"("slotBytes":)" << ExecutorBox64HleTrampolineSize << ","
        << R"("maxEmittedBytes":)" << g_box64_hle_max_emitted_bytes << ","
        << R"("emissionCanaryFailures":)"
        << g_box64_hle_emission_canary_failures << ","
        << R"("protocolFingerprint":")"
        << Hex64(Lsx4::FexHleLease::ProtocolFingerprint) << R"(",)"
        << R"("samples":[)";
    for (std::size_t i = 0; i < g_box64_hle_trampoline_samples.size(); ++i) {
        if (i != 0) {
            out << ",";
        }
        out << R"(")" << JsonEscape(g_box64_hle_trampoline_samples[i]) << R"(")";
    }
    out << "]}";
    return out.str();
}

std::string ElfTypeName(const e_type_s type) {
    switch (type) {
    case ET_EXEC:
        return "ET_EXEC";
    case ET_DYN:
        return "ET_DYN";
    case ET_SCE_EXEC:
        return "ET_SCE_EXEC";
    case ET_SCE_DYNEXEC:
        return "ET_SCE_DYNEXEC";
    case ET_SCE_DYNAMIC:
        return "ET_SCE_DYNAMIC";
    case ET_SCE_STUBLIB:
        return "ET_SCE_STUBLIB";
    default:
        return "ET_UNKNOWN";
    }
}

std::string BuildScanStatus(const char* path, Core::Loader::Elf& elf) {
    const auto self = elf.GetSElfHeader();
    const auto header = elf.GetElfHeader();
    const auto phdrs = elf.GetProgramHeader();
    const bool is_self = elf.IsSelfFile();
    const bool is_elf = elf.IsElfFile();

    int load_segments = 0;
    bool has_proc_param = false;
    bool has_dynlib_data = false;
    bool has_tls = false;
    bool has_dynamic = false;
    for (const auto& phdr : phdrs) {
        load_segments += phdr.p_type == PT_LOAD ? 1 : 0;
        has_proc_param = has_proc_param || phdr.p_type == PT_SCE_PROCPARAM;
        has_dynlib_data = has_dynlib_data || phdr.p_type == PT_SCE_DYNLIBDATA;
        has_tls = has_tls || phdr.p_type == PT_TLS;
        has_dynamic = has_dynamic || phdr.p_type == PT_DYNAMIC;
    }

    std::ostringstream out;
    out << "{"
        << R"("state":"scanned",)"
        << R"("core":"lsx4-native",)"
        << R"("path":")" << JsonEscape(path ? path : "") << R"(",)"
        << R"("format":")" << (is_self ? "SELF" : (is_elf ? "ELF" : "unknown")) << R"(",)"
        << R"("self":)" << (is_self ? "true" : "false") << ","
        << R"("elf":)" << (is_elf ? "true" : "false") << ","
        << R"("self_magic":")" << Hex64(self.magic) << R"(",)"
        << R"("self_segments":)" << self.segment_count << ","
        << R"("elf_type":")" << ElfTypeName(header.e_type) << R"(",)"
        << R"("elf_machine":)" << static_cast<unsigned>(header.e_machine) << ","
        << R"("elf_osabi":)" << static_cast<unsigned>(header.e_ident.ei_osabi) << ","
        << R"("entry":")" << Hex64(header.e_entry) << R"(",)"
        << R"("program_headers":)" << phdrs.size() << ","
        << R"("load_segments":)" << load_segments << ","
        << R"("has_sce_procparam":)" << (has_proc_param ? "true" : "false") << ","
        << R"("has_sce_dynlibdata":)" << (has_dynlib_data ? "true" : "false") << ","
        << R"("has_tls":)" << (has_tls ? "true" : "false") << ","
        << R"("has_dynamic":)" << (has_dynamic ? "true" : "false") << ","
        << R"("next_step":"wire Core::Emulator::Run/Linker::LoadModule behind Android surface and Box64 entry trampoline")"
        << "}";
    return out.str();
}

std::filesystem::path ResolveLaunchPath(const std::string& raw_path) {
    std::filesystem::path path{raw_path};
    if (std::filesystem::is_directory(path)) {
        path /= "eboot.bin";
    }
    return path;
}

void SeedStoreSandbox(const std::filesystem::path& app0_dir,
                      const std::filesystem::path& user_app_path) {
    try {
        const auto target_settings = user_app_path / "settings.ini";
        if (!std::filesystem::exists(target_settings) ||
            std::filesystem::file_size(target_settings) == 0) {
            const char* executor_settings =
                "[Settings]\n"
                "temppath=/user/app/NPXS39041/downloads\n"
                "CDN=https://api.pkg-zone.com\n"
                "Secure_Boot=1\n"
                "TTF_Font=/executor/use-embedded-store-font.ttf\n"
                "auto_install=0\n"
                "Legacy_Install=0\n"
                "auto_load_cache=0\n";
            std::ofstream settings_out(target_settings, std::ios::binary | std::ios::trunc);
            settings_out << executor_settings;
            settings_out.close();
            NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_STORE_SEED] executor settings.ini => %s",
                      target_settings.string().c_str());
        }

        const auto target_db = user_app_path / "store.db";
        const auto source_db = app0_dir / "store.db";
        const auto source_media_db = app0_dir / "Media" / "store.db";
        if ((!std::filesystem::exists(target_db) || std::filesystem::file_size(target_db) == 0) &&
            std::filesystem::exists(source_db)) {
            std::filesystem::copy_file(source_db, target_db,
                                       std::filesystem::copy_options::overwrite_existing);
            NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_STORE_SEED] store.db => %s",
                      target_db.string().c_str());
        } else if ((!std::filesystem::exists(target_db) ||
                    std::filesystem::file_size(target_db) == 0) &&
                   std::filesystem::exists(source_media_db)) {
            std::filesystem::copy_file(source_media_db, target_db,
                                       std::filesystem::copy_options::overwrite_existing);
            NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_STORE_SEED] Media/store.db => %s",
                      target_db.string().c_str());
        }

        const auto source_font = app0_dir / "assets" / "fonts" / "HelveticaWorld-Multi.ttf";
        const auto target_font =
            app0_dir / "assets" / "fonts" / "SCE-PS3-RD-R-LATIN.TTF";
        if (std::filesystem::exists(source_font) && !std::filesystem::exists(target_font)) {
            std::filesystem::copy_file(source_font, target_font,
                                       std::filesystem::copy_options::overwrite_existing);
            NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_STORE_SEED] PS4 font alias => %s",
                      target_font.string().c_str());
        }
    } catch (const std::exception& e) {
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_STORE_SEED] skipped: %s", e.what());
    }
}

