bool InstallUnityMonoScriptCompareTrace(Core::Module& module, const std::uint64_t offset,
                                        const std::uint8_t target_reg,
                                        std::atomic<std::uint64_t>& counter,
                                        UnityEntryTraceEntry* trace_entries,
                                        const std::size_t trace_entry_count, const char* name,
                                        const char* phase) {
    constexpr std::size_t kPatchLen = 16;
    constexpr std::uint64_t kStringCompareOffset = 0x020f5b40ull;
    if (!trace_entries || trace_entry_count == 0 ||
        (trace_entry_count & (trace_entry_count - 1)) != 0 || trace_entry_count > 256) {
        return false;
    }
    if (target_reg != 13 && target_reg != 15) {
        return false;
    }
    const std::uint64_t address = module.GetBaseAddress() + offset;
    const std::uint64_t compare = module.GetBaseAddress() + kStringCompareOffset;
    if (!ModuleContainsExecutableRange(module, address, kPatchLen) ||
        !ModuleContainsExecutableRange(module, compare, 16)) {
        return false;
    }
    const std::array<std::uint8_t, kPatchLen> expected_r15{
        0x48, 0x8b, 0x7b, 0x20,
        0x4c, 0x89, 0xfe,
        0xe8, 0xbb, 0xa1, 0xf5, 0x01,
        0x48, 0x8d, 0x4b, 0x10
    };
    const std::array<std::uint8_t, kPatchLen> expected_r13{
        0x48, 0x8b, 0x7b, 0x20,
        0x4c, 0x89, 0xee,
        0xe8, 0xeb, 0xa0, 0xf5, 0x01,
        0x48, 0x8d, 0x4b, 0x10
    };
    const auto* original = reinterpret_cast<const std::uint8_t*>(address);
    const auto& expected = target_reg == 15 ? expected_r15 : expected_r13;
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_UNITY_PRELOAD_ENTRY_INSTALL] phase=%s name=%s addr=0x%llx "
              "offset=0x%llx exact=compare target=r%u bytes=%s",
              phase ? phase : "?", name ? name : "?",
              static_cast<unsigned long long>(address), static_cast<unsigned long long>(offset),
              static_cast<unsigned>(target_reg), GuestBytesHex(address, 32).c_str());
    if (std::memcmp(original, expected.data(), expected.size()) != 0) {
        return false;
    }

    const std::size_t tramp_size = 320;
    const std::uint64_t tramp = AllocateUnityFrameProbeTrampoline(tramp_size);
    if (!tramp) {
        return false;
    }
    auto* code = reinterpret_cast<std::uint8_t*>(tramp);
    std::size_t cursor = 0;
    auto emit = [&](std::initializer_list<std::uint8_t> bytes) {
        for (const auto byte : bytes) {
            code[cursor++] = byte;
        }
    };
    auto emit_u64 = [&](const std::uint64_t value) {
        std::memcpy(code + cursor, &value, sizeof(value));
        cursor += sizeof(value);
    };

    emit({0x9c});
    emit({0x50});
    emit({0x51});
    emit({0x41, 0x53});
    emit({0x48, 0xb8});
    emit_u64(reinterpret_cast<std::uint64_t>(&counter));
    emit({0xf0, 0x48, 0xff, 0x00});
    emit({0x48, 0x8b, 0x08});
    emit({0x48, 0xff, 0xc9});
    emit({0x83, 0xe1, static_cast<std::uint8_t>(trace_entry_count - 1)});
    emit({0x48, 0xc1, 0xe1, 0x07});
    emit({0x48, 0xb8});
    emit_u64(reinterpret_cast<std::uint64_t>(trace_entries));
    emit({0x48, 0x01, 0xc8});
    emit({0x4c, 0x8b, 0x5c, 0x24, 0x20});
    emit({0x4c, 0x89, 0x18});
    emit({0x4c, 0x8b, 0x5b, 0x20});
    emit({0x4c, 0x89, 0x58, 0x08});
    if (target_reg == 15) {
        emit({0x4c, 0x89, 0x78, 0x10});
    } else {
        emit({0x4c, 0x89, 0x68, 0x10});
    }
    emit({0x48, 0x89, 0x58, 0x18});
    emit({0x4c, 0x8b, 0x5c, 0x24, 0x08});
    emit({0x4c, 0x89, 0x58, 0x20});
    emit({0x4c, 0x89, 0x40, 0x28});
    emit({0x4c, 0x89, 0x48, 0x30});
    emit({0x4c, 0x8d, 0x5c, 0x24, 0x20});
    emit({0x4c, 0x89, 0x58, 0x38});
    emit({0x4c, 0x8b, 0x5c, 0x24, 0x10});
    emit({0x4c, 0x89, 0x58, 0x40});
    emit({0x48, 0x89, 0x58, 0x48});
    emit({0x4c, 0x89, 0x60, 0x50});
    emit({0x4c, 0x89, 0x68, 0x58});
    emit({0x4c, 0x89, 0x70, 0x60});
    emit({0x4c, 0x89, 0x78, 0x68});
    emit({0x41, 0x5b});
    emit({0x59});
    emit({0x58});
    emit({0x9d});

    emit({0x48, 0x8b, 0x7b, 0x20});
    if (target_reg == 15) {
        emit({0x4c, 0x89, 0xfe});
    } else {
        emit({0x4c, 0x89, 0xee});
    }
    emit({0x49, 0xbb});
    emit_u64(compare);
    emit({0x41, 0xff, 0xd3});
    emit({0x48, 0x8d, 0x4b, 0x10});
    EmitAbsRipJmp(code + cursor, address + kPatchLen);
    cursor += 14;
    __builtin___clear_cache(reinterpret_cast<char*>(tramp), reinterpret_cast<char*>(tramp + cursor));

    std::array<std::uint8_t, kPatchLen> patch{};
    EmitAbsRipJmp(patch.data(), tramp);
    patch[14] = 0x90;
    patch[15] = 0x90;
    if (!PatchGuestCode(address, std::span<const std::uint8_t>(patch.data(), patch.size()), name)) {
        return false;
    }
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_UNITY_PRELOAD_ENTRY_INSTALL] phase=%s name=%s result=patched "
              "addr=0x%llx tramp=0x%llx exact=compare",
              phase ? phase : "?", name ? name : "?", static_cast<unsigned long long>(address),
              static_cast<unsigned long long>(tramp));
    return true;
}

