void ApplyUnityPreloadSchedulerProbePatch(Core::Module& module, const char* phase) {
    const auto root = ExecutorProbeRoot();
    if (root.empty()) {
        return;
    }
    const auto sentinel = root / "run-live-unitypreload-scheduler-probe";
    if (!std::filesystem::exists(sentinel)) {
        return;
    }
    const auto module_path = module.file.string();
    if (module_path.find("CUSA00754") == std::string::npos ||
        module_path.find("eboot.bin") == std::string::npos) {
        return;
    }
    g_unity_preload_scheduler_probe_narrow.store(true, std::memory_order_release);

    auto register_trace = [](auto& trace, const char* name) {
        RegisterBox64GuestReadableRange(trace.data(), sizeof(UnityEntryTraceEntry) * trace.size(),
                                        name);
    };
    register_trace(g_unity_entry_preload_job_schedule_trace,
                   "unity_entry_preload_job_schedule_trace");
    register_trace(g_unity_entry_preload_thread_create_job_trace,
                   "unity_entry_preload_thread_create_job_trace");
    register_trace(g_unity_entry_job_queue_submit_trace, "unity_entry_job_queue_submit_trace");
    register_trace(g_unity_entry_job_queue_buffered_trace, "unity_entry_job_queue_buffered_trace");
    register_trace(g_unity_entry_job_queue_wake_loop_trace, "unity_entry_job_queue_wake_loop_trace");
    register_trace(g_unity_entry_job_queue_post_trace, "unity_entry_job_queue_post_trace");

    std::uint32_t patched = 0;
    patched += InstallUnityEntryTrace(module, 0x00051ce0ull,
                                      g_unity_entry_preload_job_schedule_count,
                                      g_unity_entry_preload_job_schedule_trace.data(),
                                      g_unity_entry_preload_job_schedule_trace.size(),
                                      "PreloadJobSchedule", phase)
                   ? 1u
                   : 0u;
    patched += InstallUnityEntryTrace(module, 0x00099500ull,
                                      g_unity_entry_preload_thread_create_job_count,
                                      g_unity_entry_preload_thread_create_job_trace.data(),
                                      g_unity_entry_preload_thread_create_job_trace.size(),
                                      "PreloadThreadCreateJob", phase)
                   ? 1u
                   : 0u;
    patched += InstallUnityEntryTrace(module, 0x000513b0ull, g_unity_entry_job_queue_submit_count,
                                      g_unity_entry_job_queue_submit_trace.data(),
                                      g_unity_entry_job_queue_submit_trace.size(),
                                      "JobQueueSubmit513b0", phase)
                   ? 1u
                   : 0u;
    patched += InstallUnityEntryTrace(module, 0x0005143eull, g_unity_entry_job_queue_buffered_count,
                                      g_unity_entry_job_queue_buffered_trace.data(),
                                      g_unity_entry_job_queue_buffered_trace.size(),
                                      "JobQueueBuffered5143e", phase)
                   ? 1u
                   : 0u;
    patched += InstallUnityEntryTrace(module, 0x00051487ull, g_unity_entry_job_queue_wake_loop_count,
                                      g_unity_entry_job_queue_wake_loop_trace.data(),
                                      g_unity_entry_job_queue_wake_loop_trace.size(),
                                      "JobQueueWakeLoop51487", phase)
                   ? 1u
                   : 0u;
    patched += InstallUnityEntryTrace(module, 0x000514b6ull, g_unity_entry_job_queue_post_count,
                                      g_unity_entry_job_queue_post_trace.data(),
                                      g_unity_entry_job_queue_post_trace.size(),
                                      "JobQueuePost514b6", phase)
                   ? 1u
                   : 0u;
    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_UNITY_PRELOAD_SCHED_INSTALL] phase=%s result=done patched=%u source=%s",
              phase ? phase : "?", patched, sentinel.string().c_str());
    StartUnityPreloadEntryProbeSummaryThread();
}

