int LoadAndroidAppMediaModulesForLive(Core::Linker& linker, const std::filesystem::path& launch_path) {
#ifndef __ANDROID__
    (void)linker;
    (void)launch_path;
    return 0;
#else
    const std::filesystem::path app0 = launch_path.parent_path();
    const std::filesystem::path modules_dir = app0 / "Media" / "Modules";
    if (!std::filesystem::exists(modules_dir) || !std::filesystem::is_directory(modules_dir)) {
        NativeLog(ANDROID_LOG_INFO,
                  "[EXECUTOR_LIVE_MEDIA_MODULES] stage=skip reason=missing_dir dir=%s",
                  modules_dir.string().c_str());
        return 0;
    }

    std::vector<std::filesystem::path> candidates;
    for (const auto& entry : std::filesystem::directory_iterator(modules_dir)) {
        if (!entry.is_regular_file()) {
            continue;
        }
        const auto path = entry.path();
        const auto ext = path.extension().string();
        if (ext == ".sprx" || ext == ".prx") {
            candidates.push_back(path);
        }
    }
    std::sort(candidates.begin(), candidates.end());




    const auto mono_candidate = std::find_if(
        candidates.begin(), candidates.end(),
        [](const auto& path) { return IsMonoPs4ModulePath(path); });
    if (mono_candidate != candidates.end()) {
        const std::string mono_path = mono_candidate->string();
        RequireFexHleSignalSafepoints("media-module-scan", mono_path.c_str());
    }

    int loaded = 0;
    int failed = 0;
    for (const auto& path : candidates) {
        if (linker.FindByName(path) != static_cast<u32>(-1)) {
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_LIVE_MEDIA_MODULES] stage=already_loaded path=%s",
                      path.string().c_str());
            continue;
        }
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_LIVE_MEDIA_MODULES] stage=load_begin path=%s",
                  path.string().c_str());
        const int handle = linker.LoadModule(path, true);
        if (handle < 0) {
            ++failed;
            NativeLog(ANDROID_LOG_ERROR,
                      "[EXECUTOR_LIVE_MEDIA_MODULES] stage=load_failed path=%s rc=%d",
                      path.string().c_str(), handle);
            continue;
        }
        ++loaded;
        if (Core::Module* module = linker.GetModule(handle)) {
            NativeLog(ANDROID_LOG_INFO,
                      "[EXECUTOR_LIVE_MEDIA_MODULES] stage=load_ok path=%s handle=%d base=0x%llx "
                      "exports=%zu libs=%zu",
                      path.string().c_str(), handle,
                      static_cast<unsigned long long>(module->GetBaseAddress()),
                      module->GetExportModules().size(), module->GetExportLibs().size());
        } else {
            NativeLog(ANDROID_LOG_WARN,
                      "[EXECUTOR_LIVE_MEDIA_MODULES] stage=load_no_module path=%s handle=%d",
                      path.string().c_str(), handle);
        }
    }

    NativeLog(ANDROID_LOG_INFO,
              "[EXECUTOR_LIVE_MEDIA_MODULES] stage=done dir=%s candidates=%zu loaded=%d failed=%d",
              modules_dir.string().c_str(), candidates.size(), loaded, failed);
    return failed == 0 ? loaded : -failed;
#endif
}

