        ok &= WriteGuestQwordIfDifferent(arg_base + 0x40, kPoisonHighZero, &old_q8);
        ok &= WriteGuestQwordIfDifferent(arg_base + 0x48, kPoisonFull);
        ok &= WriteGuestQwordIfDifferent(arg_base + 0x50, kPoisonFull);
        ok &= WriteGuestQwordIfDifferent(arg_base + 0x58, kPoisonE3);
        ok &= WriteGuestQwordIfDifferent(arg_base + 0x60, kUnityGfxMagic);
        ok &= WriteGuestQwordIfDifferent(arg_base + 0x68, kUnityGfxSmall);
        ok &= WriteGuestQwordIfDifferent(arg_base + 0x80, arg_base + 0x80);
