    const auto gpu_content_probe_sentinel =
        std::filesystem::path(g_root) / "run-gpu-content-probe";
    if (std::filesystem::exists(gpu_content_probe_sentinel)) {
        setenv("EXECUTOR_GPU_CONTENT_PROBE", "1", 1);

        struct ProbeConfigKey {
            std::string_view key;
            const char* environment;
            std::uint64_t minimum;
            std::uint64_t maximum;
        };
        constexpr std::array ProbeConfigKeys{
            ProbeConfigKey{"budget", "EXECUTOR_GPU_CONTENT_PROBE_BUDGET", 1, 32},
            ProbeConfigKey{"maxBytes", "EXECUTOR_GPU_CONTENT_PROBE_MAX_BYTES", 4096,
                           64ull * 1024 * 1024},
            ProbeConfigKey{"buffers", "EXECUTOR_GPU_CONTENT_PROBE_BUFFERS", 0, 1},
            ProbeConfigKey{"drawFirst", "EXECUTOR_GPU_CONTENT_PROBE_DRAW_FIRST", 1,
                           1'000'000'000},
            ProbeConfigKey{"drawCount", "EXECUTOR_GPU_CONTENT_PROBE_DRAW_COUNT", 0,
                           1'000'000},
            ProbeConfigKey{"drawStride", "EXECUTOR_GPU_CONTENT_PROBE_DRAW_STRIDE", 1,
                           1'000'000},
            ProbeConfigKey{"drawHash", "EXECUTOR_GPU_CONTENT_PROBE_DRAW_HASH", 0,
                           std::numeric_limits<std::uint64_t>::max()},
            ProbeConfigKey{"drawHash1", "EXECUTOR_GPU_CONTENT_PROBE_DRAW_HASH1", 0,
                           std::numeric_limits<std::uint64_t>::max()},
            ProbeConfigKey{"drawHash2", "EXECUTOR_GPU_CONTENT_PROBE_DRAW_HASH2", 0,
                           std::numeric_limits<std::uint64_t>::max()},
            ProbeConfigKey{"drawHash3", "EXECUTOR_GPU_CONTENT_PROBE_DRAW_HASH3", 0,
                           std::numeric_limits<std::uint64_t>::max()},
            ProbeConfigKey{"drawTriggerHash", "EXECUTOR_GPU_CONTENT_PROBE_DRAW_TRIGGER_HASH", 0,
                           std::numeric_limits<std::uint64_t>::max()},
            ProbeConfigKey{"dispatchFirst", "EXECUTOR_GPU_CONTENT_PROBE_DISPATCH_FIRST", 1,
                           1'000'000'000},
            ProbeConfigKey{"dispatchCount", "EXECUTOR_GPU_CONTENT_PROBE_DISPATCH_COUNT", 0,
                           1'000'000},
        };
        constexpr std::uintmax_t MaxProbeConfigBytes = 4096;
        std::error_code probe_config_ec;
        const auto probe_config_size =
            std::filesystem::file_size(gpu_content_probe_sentinel, probe_config_ec);
        unsigned probe_config_warnings = 0;
        auto warn_probe_config = [&](const char* reason, std::string_view line) {
            if (probe_config_warnings++ < 16) {
                const char* line_text = line.empty() ? "" : line.data();
                NativeLog(ANDROID_LOG_WARN,
                          "[EXECUTOR_GPU_CONTENT_PROBE_CONFIG] source=sentinel path=%s "
                          "status=ignored reason=%s line=%.*s",
                          gpu_content_probe_sentinel.string().c_str(), reason,
                          static_cast<int>(std::min<std::size_t>(line.size(), 160)), line_text);
            }
        };
        if (!probe_config_ec && probe_config_size <= MaxProbeConfigBytes) {
            std::ifstream config_stream(gpu_content_probe_sentinel);
            std::string line;
            while (std::getline(config_stream, line)) {
                std::string_view text{line};
                if (const auto comment = text.find('#'); comment != std::string_view::npos) {
                    text = text.substr(0, comment);
                }
                auto trim = [](std::string_view value) {
                    while (!value.empty() &&
                           std::isspace(static_cast<unsigned char>(value.front()))) {
                        value.remove_prefix(1);
                    }
                    while (!value.empty() &&
                           std::isspace(static_cast<unsigned char>(value.back()))) {
                        value.remove_suffix(1);
                    }
                    return value;
                };
                text = trim(text);
                if (text.empty()) {
                    continue;
                }
                const auto separator = text.find('=');
                if (separator == std::string_view::npos) {
                    warn_probe_config("expected_key_equals_value", text);
                    continue;
                }
                const std::string_view key = trim(text.substr(0, separator));
                const std::string_view raw_value = trim(text.substr(separator + 1));
                const auto key_it = std::find_if(
                    ProbeConfigKeys.begin(), ProbeConfigKeys.end(), [&](const ProbeConfigKey& item) {
                        return item.key == key;
                    });
                if (key_it == ProbeConfigKeys.end()) {
                    warn_probe_config("unknown_key", key);
                    continue;
                }
                if (raw_value.empty() || raw_value.front() == '-') {
                    warn_probe_config("invalid_unsigned_value", text);
                    continue;
                }
                const std::string value_text{raw_value};
                char* parse_end{};
                errno = 0;
                const auto parsed = std::strtoull(value_text.c_str(), &parse_end, 0);
                if (errno == ERANGE || parse_end == value_text.c_str() || *parse_end != '\0' ||
                    parsed < key_it->minimum || parsed > key_it->maximum) {
                    warn_probe_config("value_out_of_range", text);
                    continue;
                }
                const std::string normalized = std::to_string(parsed);
                setenv(key_it->environment, normalized.c_str(), 1);
            }
        } else if (probe_config_ec) {
            warn_probe_config("not_a_readable_regular_file", {});
        } else {
            warn_probe_config("file_too_large", {});
        }

        auto configured_or_default = [](const char* name) {
            const char* value = std::getenv(name);
            return value && *value ? value : "<default>";
        };
        NativeLog(
            ANDROID_LOG_INFO,
            "[EXECUTOR_GPU_CONTENT_PROBE_CONFIG] source=sentinel path=%s status=enabled "
            "budget=%s maxBytes=%s buffers=%s drawFirst=%s drawCount=%s drawStride=%s drawHash=%s "
            "drawHash1=%s drawHash2=%s drawHash3=%s drawTriggerHash=%s dispatchFirst=%s "
            "dispatchCount=%s",
            gpu_content_probe_sentinel.string().c_str(),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_BUDGET"),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_MAX_BYTES"),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_BUFFERS"),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_DRAW_FIRST"),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_DRAW_COUNT"),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_DRAW_STRIDE"),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_DRAW_HASH"),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_DRAW_HASH1"),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_DRAW_HASH2"),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_DRAW_HASH3"),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_DRAW_TRIGGER_HASH"),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_DISPATCH_FIRST"),
            configured_or_default("EXECUTOR_GPU_CONTENT_PROBE_DISPATCH_COUNT"));
    }
