namespace {
std::atomic<bool> g_present_pump_run{false};
std::thread g_present_pump_thread;
std::mutex g_present_pump_control;
}

extern "C" int executor_lsx4_runtime_stop_present_pump() {
    std::lock_guard control(g_present_pump_control);
    g_present_pump_run.store(false, std::memory_order_release);
    if (g_present_pump_thread.joinable()) {
        g_present_pump_thread.join();
    }
    NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_PRESENT_PUMP] stopped");
    return 0;
}

extern "C" int executor_lsx4_runtime_start_present_pump(const char* frame_path, int fps) {
    if (frame_path == nullptr || frame_path[0] == '\0') {
        return -1;
    }
    std::lock_guard control(g_present_pump_control);
    g_present_pump_run.store(false, std::memory_order_release);
    if (g_present_pump_thread.joinable()) {
        g_present_pump_thread.join();
    }
    const std::string path = frame_path;
    const auto interval =
        std::chrono::milliseconds(fps > 0 ? std::max(1, 1000 / fps) : 62);
    g_present_pump_run.store(true, std::memory_order_release);
    g_present_pump_thread = std::thread([path, interval] {
        std::filesystem::file_time_type last_mtime{};
        std::uintmax_t last_size = 0;
        std::uint64_t presented = 0;
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_PRESENT_PUMP] started path=%s intervalMs=%lld",
                  path.c_str(), static_cast<long long>(interval.count()));
        while (g_present_pump_run.load(std::memory_order_acquire)) {
            std::error_code ec;
            const auto mtime = std::filesystem::last_write_time(path, ec);
            const auto size = ec ? 0 : std::filesystem::file_size(path, ec);
            if (!ec && size >= 64 && (mtime != last_mtime || size != last_size)) {
                const int rc = executor_lsx4_runtime_present_frame_dump_file(path.c_str());
                if (rc == 0) {
                    last_mtime = mtime;
                    last_size = size;
                    ++presented;
                    if (presented <= 8 || (presented & 63u) == 0) {
                        NativeLog(ANDROID_LOG_INFO,
                                  "[EXECUTOR_PRESENT_PUMP] presented=%llu size=%llu",
                                  static_cast<unsigned long long>(presented),
                                  static_cast<unsigned long long>(size));
                    }
                }
            }
            std::this_thread::sleep_for(interval);
        }
        NativeLog(ANDROID_LOG_INFO, "[EXECUTOR_PRESENT_PUMP] exit presented=%llu",
                  static_cast<unsigned long long>(presented));
    });
    return 0;
}

